window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch10"]={"id":"ch10","title":"第六章(一) 细胞信号转导","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"信号分子 · 受体 · 第二信使","modules":[{"i":0,"name":"绪论 · 概览","slides":[{"i":0,"sec":"","title":"第6讲 细胞信号转导/细胞通讯","notes":"细胞通讯 (cell communication)\n多细胞生物，细胞间或细胞内精确、高效接收信息，\n并级联放大，引起快速的细胞生理反应or 基因活动，\n使生物体对外界环境刺激作出相应的反应。\n【结合课本/笔记】总趋势●细胞生物学与分子生物学(包括分子遗传学与生物化学) 相互渗透与交融是总的发展趋势。重点领域●染色体DNA与蛋白质相互作用关系—主要是非组蛋白对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装","page":1,"level":"掌握","img":"assets/img/ch10/p001.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于细胞通讯，下列叙述正确的是？","o":["A. 细胞间或细胞内精确高效接收信息并级联放大，引起相应反应","B. 细胞通讯仅指神经细胞之间的信息传递","C. 细胞通讯只引起快速生理反应，不影响基因活动","D. 单细胞生物不存在任何形式的细胞通讯"],"a":"A","e":"细胞通讯指多细胞生物细胞间或细胞内精确、高效地接收信息并级联放大，引起快速的细胞生理反应或基因活动变化，使生物体对外界刺激作出反应。","oe":["正确，细胞通讯接收信息并级联放大引起反应。","错误，细胞通讯不限于神经细胞之间。","错误，细胞通讯也可引起基因活动变化。","错误，单细胞生物也存在细胞通讯。"]},"cards":null,"mem":"细胞通讯：精确接收、级联放大、应答环境","big":"assets/img/ch10/big/p001.jpg"},{"i":1,"sec":"","title":"细胞通讯的基本过程：","notes":"●信号分子的合成：主要来源内分泌细胞\n●信号分子从合成细胞释放到周围环境；\n●信号分子向靶细胞运输：血液循环为主\nμ靶细胞对信号分子识别检测：质膜、胞内受体特异选择；\n●靶细胞对细胞外信号转导，转化为胞内信号；\n●胞内信号作用于效应分子，逐级放大的级联反应，引起细胞\n代谢、生长、基因表达等方面的变化；\n●信号分子完成任务后，信号的解除灭活，终止细胞应答。","page":2,"level":"掌握","img":"assets/img/ch10/p002.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列哪项不属于细胞通讯的基本过程？","o":["A. 信号分子的合成与释放","B. 信号分子运输至靶细胞","C. 靶细胞识别受体并转导信号","D. 靶细胞随机吞噬信号分子"],"a":"D","e":"细胞通讯基本过程包括信号分子的合成与释放、运输、靶细胞识别检测、信号转导、效应产生以及信号解除灭活，不包括随机吞噬信号分子。","oe":["信号分子的合成与释放属通讯基本过程。","信号分子运输至靶细胞属基本过程。","靶细胞识别受体并转导信号属基本过程。","随机吞噬信号分子不是细胞通讯的基本过程。"],"basis":"信号分子的合成...释放...运输...靶细胞对信号分子识别检测...转导"},"cards":null,"mem":"通讯七步：合成→释放→运输→识别→转导→效应→灭活","big":"assets/img/ch10/big/p002.jpg"},{"i":2,"sec":"","title":"Extracellular signals can act slowly or rapidly to change the","notes":"behavior of a target cell\n【中文讲解·对照课本/考点】\n考点：绪论 · 概览 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页主题为细胞外信号（extracellular signals）改变靶细胞（target cell）行为，作用可快可慢。核心概念：同一类胞外信号作用于靶细胞后，有的在数秒内引起快速反应，如离子通道开放、代谢酶活性改变；有的需数小时甚至数天，如调控基因表达、促进增殖分化。翟中和《细胞生物学》第九章据此区分快、慢信号通路。","page":3,"level":"掌握","img":"assets/img/ch10/p003.jpg","anim":null,"fig":null,"points":null,"check":{"q":"细胞外信号改变靶细胞行为可快可慢，下列属于快速反应的是？","o":["A. 调控基因表达促进细胞分化","B. 离子通道开放、代谢酶活性改变","C. 促进细胞增殖","D. 诱导细胞长期分化"],"a":"B","e":"胞外信号有的在数秒内引起快速反应，如离子通道开放、代谢酶活性改变；有的需数小时至数天，如调控基因表达、促进增殖与分化。","oe":["错误，调控基因表达促进分化属慢反应。","正确，通道开放与酶活性改变属秒级快速反应。","错误，促进细胞增殖通常需较长时间。","错误，诱导细胞长期分化属于慢反应范畴。"]},"cards":null,"mem":"胞外信号效快慢：秒级通道/代谢，时天级基因","big":"assets/img/ch10/big/p003.jpg"},{"i":3,"sec":"","title":"胞内信号分子可以传递、放大、 受体与信号分子空间结构的","notes":"再整合和分流输入的信号。   互补性是二者特异结合的主\n要因素，但并不是简单的一\n对一关系。\n可能有不同受体，引起不同生理\n学效应。如乙酰胆碱(心肌细胞、骨\n骼肌、唾液腺细胞)\n同胞外信号，产生相同效应。\n如肝脏细胞肾上腺素、胰高血糖\n素受体各自被对应信号激活后，都促进\n糖原分解升高血糖。","page":4,"level":"掌握","img":"assets/img/ch10/p004.jpg","anim":null,"fig":null,"points":["同一种化学信号在不同细胞中","同一个细胞上不同受体应答不"],"check":{"q":"关于信号分子与受体关系的叙述，正确的是？","o":["A. 同一信号分子在不同细胞可引起不同生理效应","B. 信号与受体严格一对一，一种信号只有一种受体","C. 受体与配体结合只靠非特异性疏水作用","D. 不同受体在同一细胞应答结果一定相同"],"a":"A","e":"受体与信号分子空间结构互补是特异结合的主要因素，但并非简单一对一；同一信号在不同细胞可有不同受体、引起不同效应(如乙酰胆碱)，同一细胞不同受体应答也不同。","oe":["正确，如乙酰胆碱在不同细胞效应不同。","错误，同一信号可结合不同受体，并非一对一。","错误，二者的空间结构互补性是特异结合主因。","错误，同一细胞不同受体应答可不同。"]},"cards":null,"mem":"信号可整合分流：同信号异受体，异受体同效应","big":"assets/img/ch10/big/p004.jpg"},{"i":4,"sec":"","title":"同一信号分子(eg. 乙酰胆碱)能引起不同靶细","notes":"胞的不同反应。\n心肌细胞：降低收缩频率\n唾液腺细胞：分泌唾液\n骨骼肌细胞：肌肉收缩","page":5,"level":"掌握","img":"assets/img/ch10/p005.jpg","anim":null,"fig":null,"points":null,"check":{"q":"乙酰胆碱作用于下列靶细胞产生的反应，对应正确的是？","o":["A. 心肌细胞——降低收缩频率","B. 心肌细胞——分泌唾液","C. 骨骼肌细胞——降低收缩频率","D. 唾液腺细胞——肌肉收缩"],"a":"A","e":"同一信号分子乙酰胆碱可引起不同靶细胞的不同反应：心肌细胞降低收缩频率，唾液腺细胞分泌唾液，骨骼肌细胞发生肌肉收缩。","oe":["乙酰胆碱使心肌细胞降低收缩频率，正确。","分泌唾液的是唾液腺细胞，不是心肌细胞。","骨骼肌细胞对乙酰胆碱的表现为肌肉收缩。","唾液腺细胞分泌唾液，而非肌肉收缩。"],"basis":"心肌细胞：降低收缩频率；唾液腺细胞：分泌唾液；骨骼肌细胞：肌肉收缩"},"cards":null,"mem":"乙酰胆碱：心肌降频、唾液分泌、骨骼肌收缩","big":"assets/img/ch10/big/p005.jpg"}],"mcq":[{"id":"ch10_mcq_7","mod":"绪论 · 概览","modI":0,"q":"霍乱杆菌引起急性腹泻是由于（              ）。","o":["A．G 蛋白持续激活","B．G 蛋白不能被激活","C．受体封闭","D．蛋白激酶 PKC 功能异常","E．蛋白激酶 PKA 异常"],"a":"A","e":"","kp":"ch10_s0_0","oe":["霍乱毒素使Gs的α亚基持续激活，腺苷酸环化酶过度活化，正确。","霍乱毒素是持续激活G蛋白，而非使G蛋白不能被激活。","霍乱弧菌引起腹泻并非受体被封闭所致。","蛋白激酶C功能异常与霍乱弧菌腹泻机制无关。","PKA异常是G蛋白持续激活的下游后果，非霍乱毒素直接作用。"]}],"judge":[{"id":"ch10_judge_7","modI":0,"q":"ras 是一个癌基因。（  ）","a":"错","e":"ras 是一个原癌基因，如果带有使其始终处于活化状态的突变，才会变成癌基因。","kp":"ch10_s0_0","oe":["误以为ras本身就是癌基因，故判对。","ras是原癌基因，只有发生使其持续活化的突变后才变为癌基因。"]},{"id":"ch10_judge_8","modI":0,"q":"乙酰胆碱对一个动物的不同细胞有不同的效应，而且它和不同细胞上的不同受体分子相 结合。（      ）","a":"对","e":"比如，乙酰胆碱通过结合一种 G 蛋白耦联受体而减弱心肌细胞的搏动；通过结合 另一不同的乙酰胆碱受体而刺激骨骼肌细胞的收缩。这种受体是一种配体门控离子通道。","kp":"ch10_s0_3","oe":["乙酰胆碱可结合心肌G蛋白偶联受体减弱搏动，结合骨骼肌配体门控通道刺激收缩。","误以为一种信号分子只对应一种受体和一种效应，忽略受体类型的多样性。"]}],"fill":[{"id":"ch10_fill_14","modI":0,"q":"自身免疫性受体病是由于______。","a":"机体产生抗自身受体的抗体，与受体结合后使受体失去功能或改变作用方向查看答 案","kp":"ch10_s0_0","oe":["机体产生抗自身受体的抗体，结合后使受体失活或改变作用"]}],"short":[{"id":"ch10_short_1","modI":0,"q":"简述细胞通讯的方式。","a":"（1）细胞通过分泌化学信号进行的通讯，包括内分泌、旁分泌、自分泌和化学突触等。 （2）细胞间接触性依赖的通讯：细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白。 （3）间隙连接：使细胞质相互沟通，实现代谢偶联或电偶联。","kp":"ch10_s0_1"},{"id":"ch10_short_3","modI":0,"q":"蛋白质获取磷酸基团在细胞信号系统传导中的作用如何？","a":"（1）细胞内的信号蛋白主要分为两大类：一类在蛋白激酶的作用下磷酸化，共价结合 ATP 所提供的磷酸基团；另一类则在信号作用下结合 GTP，通常以 GTP 取代 GDP。 （2）这两种胞内信号蛋白的共同特征是，在信号达到时通过获得一个或几个磷酸集团而被 激活，而在信号减弱时能去除这些集团，从而失去活性。在信号中继网中，某个信号蛋白磷 酸化通常造成下游的蛋白依次发生磷酸化，形成磷酸化级联反应。","kp":"ch10_s0_0"},{"id":"ch10_short_6","modI":0,"q":"简述日咳产生的细胞学原因。","a":"百日咳毒素催化 Gi 的α亚基 ADP－核糖基化，降低了 GTP 与 Gi 的α亚基的结合水平， 使 Gi 的α亚基不能活化，从而阻断了 Ri 受体对腺苷酸环化酶的抑制作用。","kp":"ch10_s0_0"},{"id":"ch10_short_12","modI":0,"q":"细胞信号转导的复杂性主要表现在哪几个方面？","a":"细胞信号转导的复杂性主要表现在以下方面： （1）多途径多层次的细胞信号传递通路具有收敛性和发散性的特点。每种受体都能识别与 结合各自的特异性配体，来自各种非相关受体的信号，可以在细胞内收敛激活一个共同的效 应器（如 Ras 或 Raf 蛋白）的信号。另外，来自相同配体的信号（如表皮生长因子或胰岛素）， 又可发散激活各种不同的效应器，导致多样化的细胞应答。 （2）细胞信号转导既具有专一性，又具有作用的相似性。配体与受体在结构上的互补是细 胞信号转导具有专一性的重要基础；同时细胞信号转导又有相似的作用机制，因此细胞面临 各种纷杂的胞外信号时，只通过少数几种第二信使便可介导多种多样的细胞应答反应。如不 同细胞因子与受体组成的复合体中往往含有相同亚基，由此诱导相似的信号转导；一种配体 与受体结合可诱发多种信号转导途径，如在配体作用下，RTK 不同位点的 Tyr 残基自磷酸 化，可分别结合不同信号蛋白或接头蛋白，引出不同的信号通路；G 蛋白与受体偶联可介导 腺苷酸环化酶和 PLC 等，分别引出 cAMP 和 IP3-DAG 两种信号通路。 （3）信号转导过程有放大作用，但这种放大作用又必须受到适度调控，这表现为信号放大 作用和信号终止作用的并存。正常生理条件下，激素配体本身对受体数目的影响，信号分子 的磷酸化与去磷酸化，G 蛋白的 GTP 或 GDP 结合状态可逆变化，Ca2 的释放与回收等，都 ＋   可使信号转导精确而适度，不是持续的而是对胞外信号瞬间的反应，一旦破坏了这种正常的 正负反馈机制，细胞就会病变。 （4）当细胞长期暴露于某种形式的刺激下时，细胞对刺激的反应会降低，即细胞适应现象。 细胞适应的方式有：逐渐降低表面受体数目；快速钝化受体，降低受体配体的亲和力；在受 体已经被激活的情况下，其下游信号蛋白发生变化，使信号通路受阻。这种适应性是通过负 反馈条件实现的。 （5）细胞信号转导的复杂性还表现在它的非线性方面。细胞无时无刻不在复杂环境的信号 轰炸之下，这些信号分别协调启动细胞各种信号途径，最后做出合理的应答反应。因此，细 胞各种不同信号通路不是彼此孤立的，其最重要的特征就是形成一个复杂的信号网络系统， 它具有高度的非线性特点，被称为交叉对话。这种机制使信号经网络系统分析、整合后最终 表现为特定的生理功能，从而使细胞具有一定自我修复机制和补偿能力。","kp":"ch10_s0_0"},{"id":"ch10_short_13","modI":0,"q":"试述参与细胞信号转导的细胞膜受体的种类与特点。","a":"参与细胞信号转导的细胞膜受体的种类与特点如下： （1）酶联受体 受体结构域具有潜在酶活性或者受体本身不具有酶活性但其胞内段与酶联系，在受到刺激时 能激活下游靶酶。如生长因子类受体，这类受体存在于细胞膜上，受体本身具有酪氨酸激酶 的活性，能直接催化底物的磷酸化。 （2）离子通道受体 某些神经递质的受体，它们也存在于细胞膜上，其本身是一种或几种离子的离子通道，配体 与这类受体结合后，改变了受体的空间构象，使离子通道开放或关闭，控制着离子进出细胞。 （3）G 蛋白偶联的受体 普遍存在于各类真核细胞表面，通过与细胞内 G 蛋白偶联，受到刺激时改变 G 蛋白的构象， 从而激活下游靶蛋白活性，引起应答。如神经递质、激素、肽类和胺类配体等的受体。","kp":"ch10_s0_0"}],"calc":[],"term":[]},{"i":1,"name":"一、信号分子","slides":[{"i":5,"sec":"一、信号分子","title":"一、信号分子","notes":"指生物体内的某些化学分子，主要用来在细胞间和细\n胞内传递信息，如激素、神经递质、生长因子等，其\n唯一功能是与细胞受体结合并传递信息。\n●水溶性信使－细胞表面受体\n●脂溶性信号－胞质或核受体\n例如：\n（占脊椎动物细胞80％，细胞质膜受体）\n腺素和甲状腺素\n【结合课本/笔记】第二节 细胞通讯与信号传递●细胞通讯与细胞识别●细胞的信号分子与受体●通过细胞内受体介导的信号传递●通过细胞表面受体介导的信号跨膜传递●由细胞表面整合蛋白介导的信号传递●细胞信号传递的基本特征与蛋白激酶的网络整合信息","page":6,"level":"掌握","img":"assets/img/ch10/p006.jpg","anim":null,"fig":null,"points":["蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","氨基酸衍生物：酪氨酸衍生的小分子激素，如肾上","类固醇激素(不溶于水，作用于细胞内受体)","可溶解的气体分子等"],"check":{"q":"关于信号分子的叙述，正确的是？","o":["A. 既是营养物质又是能源物质","B. 水溶性信号分子作用于胞质或核受体","C. 脂溶性信号分子只能作用于膜表面受体","D. 其唯一功能是与细胞受体结合并传递信息"],"a":"D","e":"信号分子是生物体内传递信息的化学分子(激素、神经递质、生长因子等)，既非营养物也非能源或结构物质，其唯一功能是与受体结合传递信息；水溶性信使作用于表面受体，脂溶性信号作用于胞内受体。","oe":["错误，信号分子非营养物、能源或结构物质。","错误，水溶性信使作用于细胞表面受体。","错误，脂溶性信号作用于胞质或核受体。","正确，信号分子唯一功能是结合受体传递信息。"]},"cards":null,"mem":"信号分子：水溶性配表面受体，脂溶性配胞内受体","big":"assets/img/ch10/big/p006.jpg"}],"mcq":[{"id":"ch10_mcq_3","mod":"一、信号分子","modI":1,"q":"对于由整联蛋白介导的信号传递，下列哪项说法错误？（            ）","o":["A．胞外配体主要为细胞外基质成分，如纤连蛋白等","B．整联蛋白与胞外配体的相互作用只产生一种胞内信号，即胞内 Ca2+浓度增加","C．当胞外配体与整联蛋白结合，可导致分子开关蛋白 Rho 蛋白激活","D．最终作用是与细胞增殖相关的基因被激活，细胞周期相关蛋白合成"],"a":"B","e":"整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞质基质，肌 醇第二信使的合成，胞内酪氨酸残基的磷酸化等。","kp":"ch10_s1_5","oe":["胞外配体主要是纤连蛋白等细胞外基质成分，说法正确。","整联蛋白可产生Ca2+升高、肌醇第二信使、酪氨酸磷酸化等多种信号，B错。","配体与整联蛋白结合可激活分子开关蛋白Rho，说法正确。","最终激活细胞增殖相关基因并合成细胞周期相关蛋白，说法正确。"]}],"judge":[{"id":"ch10_judge_10","modI":1,"q":"细胞外信号都是通过细胞表面受体来进行跨膜信号传递的。（                    ）","a":"错","e":"有的脂溶性的信号分子可以跨膜进入细胞与胞内受体结合。","kp":"ch10_s1_5","oe":["误以为所有胞外信号都必须经细胞表面受体传递。","脂溶性信号分子可穿膜进入细胞与胞内受体结合，故“都”的说法错误。"]}],"fill":[{"id":"ch10_fill_6","modI":1,"q":"细胞的信号传递是______、______、______、______的______过程。","a":"多通路；多环节；多层次；高度复杂可控","kp":"ch10_s1_5","oe":["同一信号可经多条通路传递，体现多通路性","信号传递需经受体、G蛋白、效应酶等多环节","信号可在膜、胞质、核等多个层次传递整合","该过程高度复杂，又受多种机制精细调控","整体是一个多级放大、可精确调控的信号转导过程"]},{"id":"ch10_fill_8","modI":1,"q":"通过黏合斑由整联蛋白介导的信号传递通路有两条：______和______。","a":"由细胞表面到细胞核的信号通路；由细胞表面到细胞质核糖体的信号通路","kp":"ch10_s1_5","oe":["一条由细胞表面经信号传至细胞核，调节基因表达","另一条由细胞表面传至细胞质核糖体，调节蛋白合成"]},{"id":"ch10_fill_12","modI":1,"q":"动物细胞间通讯连接的主要方式是______，植物细胞的通讯连接方式是通过______。","a":"间隙连接；胞间连丝","kp":"ch10_s1_5","oe":["动物细胞间以间隙连接沟通，允许小分子直接通过","植物细胞间通过胞间连丝相连，是其特有连接"]}],"short":[{"id":"ch10_short_11","modI":1,"q":"举例说明 G 蛋白偶联细胞表面受体介导信号跨膜转导的通路及其作用机制。 相关试题：G-蛋白偶联系统信号转导的主要特点是什么？","a":"G 蛋白偶联细胞表面受体介导信号跨膜转导的通路主要有两条：cAMP 信号通路和磷脂 酰肌醇信号通路。同时，在磷脂酰肌醇信号通路中，存在一个“双信使系统”，因而 G 蛋白 偶联受体信号转导形成一个复杂的网络结构。 （1）cAMP 信号通路 ①信号通路：激素→G 蛋白偶联受体→G 蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白。 ②作用机制：cAMP 活化 PKA，PKA 催化亚基转位进入细胞核，使基因调控蛋白（cAMP 应答元件结合蛋白，CREB）磷酸化，磷酸化的基因调控蛋白 CREB 与核内 CREB 结合蛋白 （CBP）特异结合形成复合物，复合物与靶基因调控序列结合，激活靶基因的表达。 （2）磷脂酰肌醇信号通路“双信使系统” 胞外信号分子与 GPCR 结合，活化 G 蛋白，进而激活磷脂酶 C（PLC），催化 PIP2 水解生 成 IP3 和 DAG 两个第二信使。 ①IP3-Ca2 信号通路 ＋   a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→IP3→胞内 Ca2 浓度升高→Ca2 结合蛋白（CaM）→钙调蛋白依赖激酶→基因调控蛋白。 ＋             ＋   b．作用机制：IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，引起 Ca2 释放并进入细胞质 ＋         ＋   基质，通过结合钙调蛋白引起细胞反应，如引起肌细胞的收缩。 ②DAG-PKC 信号通路 a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→DAG→激活 PKC→蛋白磷酸化或者促 Na ／H 交换使胞内 pH 变化等。 ＋   ＋   b．作用机制：IP3-Ca2 信号通路释放的 Ca2 将细胞质中游离的蛋白激酶 C（PKC）募集到细 ＋           ＋   胞质膜上，结合在质膜上的第二信使 DAG 活化并激活与质膜结合的 PKC，接着 PKC 作用 于下游底物，引起多种细胞反应，如细胞分泌、肌肉收缩、细胞增殖分化等。","kp":"ch10_s1_5"}],"calc":[],"term":[]},{"i":2,"name":"1.1 化学信号","slides":[{"i":6,"sec":"1.1    化学信号","title":"1.1    化学信号","notes":"内分泌激素：由内分泌细胞产生，分泌到血液中，广泛地运送\n到生物体全身－距离最远。如类固醇激素、胰岛素、肾上腺\n素、甲状腺素等。\n旁分泌(局部介质)：只作用于周围局部细胞，分泌出来后停留\n在分泌细胞周围的细胞外液体中。eg.生长因子、淋巴因子、\n前列腺素、NO。\n神经递质/化学突触：神经末梢释放出来的信号，因扩散距离有\n限，神经突触必须与靶细胞很近。如乙酰胆碱等，作用速度\n快、部位精确、维持时间短、与受体亲和力低。\n自分泌信号：信号发放细胞与靶细胞为同类或图一个细胞，常\n见于癌细胞。","page":7,"level":"掌握","img":"assets/img/ch10/p007.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列信号分子中，属于旁分泌（局部介质）的是？","o":["A. 胰岛素、肾上腺素、甲状腺素","B. 生长因子、前列腺素、NO","C. 乙酰胆碱等神经递质","D. 类固醇激素"],"a":"B","e":"旁分泌信号分泌后停留在分泌细胞周围的细胞外液中，只作用于局部细胞，如生长因子、淋巴因子、前列腺素、NO；胰岛素等属内分泌激素。","oe":["错误，胰岛素、肾上腺素、甲状腺素属内分泌激素。","正确，生长因子、前列腺素、NO属旁分泌局部介质。","错误，乙酰胆碱等属化学突触的神经递质。","错误，类固醇激素主要经血液运输，属内分泌。"]},"cards":null,"mem":"四类化学信号：内分泌/旁分泌/神经递质/自分泌","big":"assets/img/ch10/big/p007.jpg"},{"i":7,"sec":"1.1    化学信号","title":"化学信号","notes":"【结合课本/笔记】细胞通讯（cell communication）一个细胞发出的信息通过介质传递到另一个细胞产生相应的反应。细胞间的通讯对于多细胞生物体的发生和组织的构建，协调细胞的功能，控制细胞的生长、分裂、分化和凋亡是必须的。●细胞通讯方式：●分泌化学信号进行通讯●内分泌（endocrine）●旁分泌（paracrine）●自分泌（autocrine）●化学突触（chemical synapse）●接触性依赖的通讯细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白●间隙连接实现代谢偶联或电偶联","page":8,"level":"掌握","img":"assets/img/ch10/p008.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列哪项不属于细胞通讯的方式？","o":["A. 内分泌","B. 旁分泌","C. 自分泌","D. 胞吞作用"],"a":"D","e":"细胞通讯方式包括分泌化学信号（内分泌、旁分泌、自分泌、化学突触）、接触性依赖的通讯以及间隙连接，胞吞作用不属于细胞通讯方式。","oe":["内分泌属于分泌化学信号的通讯方式之一。","旁分泌属于分泌化学信号的通讯方式之一。","自分泌属于分泌化学信号的通讯方式之一。","胞吞是物质摄取过程，不属细胞通讯方式。"],"basis":"内分泌...旁分泌...自分泌...化学突触...接触性依赖的通讯...间隙连接"},"cards":null,"mem":"通讯方式：分泌(内/旁/自/突触)+接触依赖+间隙连接","big":"assets/img/ch10/big/p008.jpg"}],"mcq":[],"judge":[{"id":"ch10_judge_1","modI":2,"q":"细胞间的通讯就是通过细胞间形成缝隙连接，是细胞质相互沟通而实现的。（              ）","a":"错","e":"间隙连接仅仅是细胞通讯的一种方式，细胞通讯还可以通过分泌化学信号以及细胞 直接接触而实现，而且这两种方式是相对较普遍的。","kp":"ch10_s2_7","oe":["误以为细胞通讯仅有间隙连接一种方式，故判对。","间隙连接只是方式之一，还普遍存在分泌化学信号及细胞直接接触等方式。"]}],"fill":[{"id":"ch10_fill_1","modI":2,"q":"生物体内的化学信号分子一般可以分为______和______两类。","a":"亲脂性的信号分子；亲水性的信号分子","kp":"ch10_s2_7","oe":["亲脂性信号分子可穿过脂双层，与胞内受体结合","亲水性信号分子不能过膜，需与膜表面受体结合"]},{"id":"ch10_fill_17","modI":2,"q":"细胞分泌化学信号的作用方式可分为：________、________、________；通过化学突触 传递神经信号。","a":"自分泌；内分泌；旁分泌","kp":"ch10_s2_6","oe":["自分泌指信号分子作用于自身或同类细胞","内分泌指信号经血液运输作用于远处靶细胞","旁分泌指信号分子作用于邻近的靶细胞"]}],"short":[],"calc":[],"term":[{"id":"ch10_term_1","modI":2,"term":"细胞通讯（cell communication）。","def":"细胞通讯（cell communication）是指一个细胞发出的信号通过某种介质传递到另一细胞， 并使其产生相应的反应。细胞通讯在多细胞生物体的发生和组织的构建，协调细胞的功能， 控制细胞的生长和分裂中发挥了重要的作用。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_7","modI":2,"term":"signal transduction","def":"signal transduction 的中文名称是信号转导。信号转导是指一个细胞发出的信息，可通过 介质传递到另一个细胞并产生相应的反应的过程，是一种复杂的系统通讯活动及协助细胞的 活动。信号转导可以实现细胞间通讯，是协调多细胞生物细胞间功能、控制细胞的生长和分 裂、组织发生与形态建成所必需的关键过程。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_9","modI":2,"term":"细胞通讯","def":"细胞通讯是指一个细胞发出的信息通过介质（又称配体）传递到另一个靶细胞并与其相 应的受体相互作用，然后通过细胞信号转导产生靶细胞内一系列生理生化变化，最终表现为 靶细胞整体的生物学效应的过程。","kps":"","kp":"ch10_s2_7"}]},{"i":3,"name":"1.2 细胞内的信号分子","slides":[{"i":8,"sec":"1.2   细胞内的信号分子","title":"气体信号分子 如NO, CO等，可以自由扩散入细胞。","notes":"1.2   细胞内的信号分子\n第二信使(second messenger):\n靶细胞外信号(第一信使)如不能进入细胞，作用于\n细胞表面受体，产生靶细胞内信号(非蛋白类小分\n子)，其浓度变化(增/减)启动或调节细胞内稍晚出现\n的信号应答；具有携带传递和放大信号的功能。\n环腺苷酸(cAMP)、cGMP、磷脂酸肌醇 (IP3),\n二酰基甘油(DAG)、钙离子","page":9,"level":"掌握","img":"assets/img/ch10/p009.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于气体信号分子（如NO、CO）进入细胞的方式，下列叙述正确的是？","o":["A. 可自由扩散进入细胞","B. 需与膜受体结合后经G蛋白进入","C. 通过主动运输逆浓度进入","D. 通过胞饮作用进入"],"a":"A","e":"气体信号分子如NO、CO等可以自由扩散入细胞，属于能直接跨膜进入细胞的一类信号分子。","oe":["NO、CO可自由扩散入细胞，正确。","气体分子无需与膜受体结合即可进入细胞。","自由扩散不消耗能量，不需逆浓度主动运输。","它们是简单扩散，不通过胞饮作用。"],"basis":"气体信号分子 如NO, CO等，可以自由扩散入细胞"},"cards":null,"mem":"第二信使：cAMP/cGMP/IP3/DAG/Ca2+","big":"assets/img/ch10/big/p009.jpg"},{"i":9,"sec":"1.2   细胞内的信号分子","title":"4 common intracellular second messengers","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：1.2 细胞内的信号分子 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n• 第二信使（second messengers）：细胞表面受体接受细胞外信号后转换而来的细胞内信号称为第二信使。细胞内有5种最重要的第二信使：cAMP、cGMP、1，2-二酰甘油、1，4，5-三磷酸肌醇、Ca2+等。\n\n【本页英文讲解】\n本页主题：4种常见的胞内第二信使（intracellular second messengers）。第二信使是胞外信号分子（第一信使）与受体结合后，在细胞内生成或释放的小分子，负责把信号放大并向下游传递。原文仅列出标题，未给出具体名称；按翟中和教材，常见者包括cAMP、cGMP、IP3（三磷酸肌醇）和Ca2+（钙离子）等。考点：第二信使的放大效应与可扩散性。","page":10,"level":"掌握","img":"assets/img/ch10/p010.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列全部属于常见胞内第二信使的一组是？","o":["A. ATP、ADP、AMP、腺苷","B. 胰岛素、胰高血糖素、肾上腺素","C. GDP、GTP、NAD+、FAD","D. cAMP、cGMP、IP3、Ca2+"],"a":"D","e":"常见第二信使包括cAMP、cGMP、IP3（三磷酸肌醇）、DAG和Ca2+等。","oe":["这些是能量代谢核苷酸，非第二信使。","这些属于第一信使（胞外信号分子）。","GDP、GTP、NAD+、FAD均不属第二信使范畴。","四者均为常见胞内第二信使，正确。"]},"cards":null,"mem":"四种常见第二信使，介导胞内信号级联放大","big":"assets/img/ch10/big/p010.jpg"}],"mcq":[{"id":"ch10_mcq_1","mod":"1.2   细胞内的信号分子","modI":3,"q":"下列有关气体信号分子 NO 的说法，错误的是（          ）。","o":["A．在平滑肌细胞内，L 精氨酸在 NO 合酶催化作用下生成 NO","B．NO 通过增强可溶性鸟苷酸环化酶的活性，发挥作用","C．鸟苷酸环化酶催化 GTP 生成 cGMP，cGMP 介导蛋白质的磷酸化","D．NO 通过舒张血管平滑肌治疗心绞痛，NO 也参与大脑的学习记忆生理过程"],"a":"A","e":"血管内皮细胞和神经细胞是 NO 的生成细胞，NO 再经扩散进入平滑肌细胞发挥作 用。","kp":"ch10_s3_8","oe":["NO由血管内皮细胞和神经细胞产生后扩散入平滑肌，A项来源错误。","NO通过激活可溶性鸟苷酸环化酶发挥作用，该说法正确。","鸟苷酸环化酶催化GTP生成cGMP，经PKG使蛋白磷酸化，正确。","NO舒张血管平滑肌可治心绞痛，也参与学习记忆，说法正确。"]},{"id":"ch10_mcq_5","mod":"1.2   细胞内的信号分子","modI":3,"q":"动物细胞内引起储存 Ca2 释放的第二信使分子是（               ）。 ＋","o":["A．IP3","B．DAG","C．cAMP","D．cGMP"],"a":"A","e":"IP3（三磷酸肌醇）作为第二信使，从质膜扩散到细胞质，引起 Ca2 从内质网钙库 ＋   中释放出来，导致细胞内 Ca2 浓度瞬间增高，这一作用发生在几乎所有真核细胞中。 ＋","kp":"ch10_s3_8","oe":["IP3作为第二信使扩散至内质网，打开钙通道促使Ca2+释放，正确。","DAG主要激活蛋白激酶C，不直接引起内质网钙库释放。","cAMP激活PKA，与内质网储存钙的释放无直接关系。","cGMP激活PKG，不引起内质网储存钙的释放。"]}],"judge":[{"id":"ch10_judge_9","modI":3,"q":"NO 作为信号分子，它能使细胞内的 cAMP 水平升高。（              ）","a":"错","e":"NO 释放后可以激活其受体，从而刺激生成第二信使 cGMP，cGMP 的作用是通过 cGMP 依赖的蛋白激酶 G 的活化抑制肌动-肌球蛋白复合物信号通路，导致血管平滑肌的舒 张。","kp":"ch10_s3_8","oe":["误以为NO通过升高cAMP发挥作用，故判对。","NO激活受体后生成第二信使cGMP，经蛋白激酶G引起血管平滑肌舒张。"]}],"fill":[{"id":"ch10_fill_4","modI":3,"q":"在体内发现的第一个气体信号分子是______。","a":"NO","kp":"ch10_s3_8","oe":["NO是首先发现的气体信号分子，可扩散并舒张血管"]},{"id":"ch10_fill_11","modI":3,"q":"NO 在胞外极不稳定，被氧化后以______的形式存在于细胞外液中。","a":"硝酸根或亚硝酸根","kp":"ch10_s3_8","oe":["NO不稳定，氧化成硝酸根或亚硝酸根后才稳定存在"]}],"short":[],"calc":[],"term":[]},{"i":4,"name":"二、受体(receptor)","slides":[{"i":10,"sec":"二、受体(receptor)","title":"信号分子称为配体 (ligand)","notes":"二、受体(receptor)\n位于细胞膜表面或细胞内能识别和选择性结合某\n种配体信号的生物大分子，与配体结合后，产生化学\n或物理的信号，以启动一系列信号传递过程，最终表\n现为生物学效应。\nthat is shaped to recognize the signal molecule with high\nspecificity, helping to ensure that the receptor responds only\nto the appropritate signal and not to the many other\nsignaling molecules surrounding the cell.\nconcentrations(typically ×10-8M), and their receptors usually\nbind them with high affinity.\n【中文讲解·对照课本/考点】\n考点：二、受体(receptor) ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 信号分子（signaling molecules）：是指生物体内的某些化学分子，即非营养物，又非能源物质和结构物质，而且也不是酶，它们主要是用来在细胞间和细胞内传递信息，如激素、神经递质、生长因子等统称为信号分子，它们的唯一功能是同细胞受体结合，传递细胞信息。\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页区分两个基本概念。信号分子称为配体（ligand）。受体（receptor）是位于细胞膜表面或细胞内、能识别并选择性结合某种配体的生物大分子，结合后产生化学或物理信号，启动信号传递并产生生物学效应。受体结合位点能高特异性识别信号分子；许多信号分子浓度极低（约10⁻⁸ M），受体以高亲和力（high affinity）结合。考点：受体的特异性与高亲和力。","page":11,"level":"掌握","img":"assets/img/ch10/p011.jpg","anim":null,"fig":null,"points":["The binding site of the receptor has a complex structure","Many signal molecules act at very low"],"check":{"q":"关于受体(receptor)的叙述，正确的是？","o":["A. 受体与配体结合无特异性","B. 受体都位于细胞核内","C. 位于膜表面或细胞内，能高特异性识别结合配体并引发信号","D. 受体与配体的亲和力很低"],"a":"C","e":"受体是位于细胞膜表面或细胞内、能识别和选择性结合某种配体信号的生物大分子；其结合位点结构复杂，可高特异性、高亲和力地结合信号分子。","oe":["受体对配体的识别具有高度特异性。","受体可位于膜表面或细胞内，不都在核内。","受体高特异性识别结合配体并引发信号，正确。","受体通常以高亲和力结合信号分子。"],"basis":"位于细胞膜表面或细胞内能识别和选择性结合某种配体信号的生物大分子"},"cards":null,"mem":"受体=特异结合配体的大分子，高亲和，低浓度信号","big":"assets/img/ch10/big/p011.jpg"},{"i":11,"sec":"二、受体(receptor)","title":"受体是一类能够识别和选择性结合某种配体（信号分子）的大","notes":"分子；\n体。\n细胞内受体     细胞表面受体\n\n【读图讲解】\n本页讲受体及其分类。文字定义受体为能识别并选择性结合配体(信号分子)的大分子，绝大多数是蛋白质且多为糖蛋白，少数为糖脂(如霍乱毒素、百日咳毒素受体)，也有糖蛋白与糖脂组成的复合物(如促甲状腺素受体)。下方两图对比：左为细胞内受体，小分子疏水性信号分子经载体蛋白进入靶细胞，与胞内受体蛋白结合后作用于细胞核；右为细胞表面受体，亲水性信号分子不能过膜，只能与质膜上的受体蛋白结合。要点：信号分子性质决定受体所在位置。","page":12,"level":"掌握","img":"assets/img/ch10/p012.jpg","anim":null,"fig":null,"points":["绝大多数受体都是蛋白质且多为糖蛋白，","少数受体是糖脂（如霍乱毒素受体和百日咳毒素受体），","有的受体是糖蛋白和糖脂组成的复合物, 如促甲状腺素受"],"check":{"q":"关于受体化学本质的叙述，正确的是？","o":["A. 绝大多数受体是蛋白质且多为糖蛋白，少数为糖脂","B. 所有受体都是核酸","C. 受体均位于细胞膜表面","D. 促甲状腺素受体由纯脂质构成"],"a":"A","e":"受体绝大多数是蛋白质且多为糖蛋白，少数是糖脂(如霍乱毒素、百日咳毒素受体)，有的为糖蛋白与糖脂组成的复合物(如促甲状腺素受体)；亲水信号作用于表面受体，疏水信号作用于胞内受体。","oe":["正确，受体多为糖蛋白，少数为糖脂。","错误，受体绝大多数是蛋白质，并非核酸。","错误，小分子疏水信号作用于细胞内受体。","错误，促甲状腺素受体是糖蛋白和糖脂复合物。"]},"cards":null,"mem":"受体分胞内/表面；多为糖蛋白，少数糖脂(霍乱毒素)","big":"assets/img/ch10/big/p012.jpg"},{"i":12,"sec":"二、受体(receptor)","title":"亲水性","notes":"疏水/亲脂性\n神经递质、\n类固醇激素(甾类激     生长因子；\n素)；           多肽类激素\n视黄酸(类维生素A)\n甲状腺素","page":13,"level":"掌握","img":"assets/img/ch10/p013.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列信号分子中属于亲水性、不能自由穿过细胞膜的是？","o":["A. 多肽类激素","B. 类固醇激素","C. 甲状腺素","D. 视黄酸（类维生素A）"],"a":"A","e":"多肽类激素、神经递质、生长因子为亲水性；类固醇激素、甲状腺素、视黄酸为亲脂性。","oe":["多肽类激素为亲水性，不能自由穿膜，正确。","类固醇激素为疏水/亲脂性，可穿膜。","甲状腺素属亲脂性信号分子，可自由穿膜。","视黄酸为亲脂性，可穿过细胞膜。"]},"cards":null,"mem":"亲水信号→表面受体；疏水/亲脂信号→胞内受体","big":"assets/img/ch10/big/p013.jpg"}],"mcq":[{"id":"ch10_mcq_4","mod":"二、受体(receptor)","modI":4,"q":"下列关于信号分子的描述中，不正确的是（                ）。","o":["A．神经递质属于亲脂性信号","B．本身不具有酶的活性","C．能传递信息","D．可作为作用底物"],"a":"A","e":"神经递质属于亲水性信号分子。","kp":"ch10_s4_11","oe":["神经递质属亲水性信号分子而非亲脂性，故A错误。","信号分子本身不具酶活性，须与受体结合发挥作用，正确。","信号分子能传递信息，该说法正确。","信号分子可作为作用底物，该说法正确。"]}],"judge":[{"id":"ch10_judge_2","modI":4,"q":"所有的受体都是跨膜蛋白质。（       ）","a":"错","e":"细胞表面的受体多为跨膜糖蛋白，但细胞内的受体如基因调控蛋白等不一定是。","kp":"ch10_s4_11","oe":["误以为受体均为跨膜蛋白，故判对。","胞内受体（如核受体、基因调控蛋白）并非跨膜蛋白，故“所有”说法错误。"]}],"fill":[{"id":"ch10_fill_5","modI":4,"q":"根据信号转导机制和受体蛋白类型的不同，细胞表面受体可以分为______、______ 、 ______。","a":"离子通道耦联受体；G 蛋白耦联受体；酶连受体","kp":"ch10_s4_11","oe":["离子通道耦联受体即配体门控离子通道","G蛋白耦联受体经G蛋白调节效应器传信号","酶连受体胞内具酶活性或招募酶，如受体酪氨酸激酶"]},{"id":"ch10_fill_7","modI":4,"q":"甾类激素诱导的基因活化分为两个阶段：______和______。","a":"直接活化少数特殊基因转录的初级反应阶段；初级反应的基因产物再活化其他基因产生延迟 的次级反应","kp":"ch10_s4_12","oe":["激素受体复合物先直接激活少数特殊基因转录","初级反应产物再激活其他基因，产生延迟次级反应"]}],"short":[{"id":"ch10_short_5","modI":4,"q":"霍乱毒素通过什么机制引起腹泻的？","a":"霍乱毒素是一种作用于 G 蛋白的毒素，它可将 NAD+上的 ADP-核糖基团共价结合到 Gs 的α亚基上，使蛋白核糖化，这样抑制了α亚基的 GTP 酶活性，从而抑制了 GTP 的水解， 使 Gs 一直处于激活状态。结果使腺苷酸环化酶处于永久活性状态，cAMP 的形成无法终止， 引起 Na+与水分子不断分泌到肠腔，而导致严重腹泻。","kp":"ch10_s4_11"},{"id":"ch10_short_14","modI":4,"q":"概述细胞表面受体的分类（配体、受体、信号转导机制）。","a":"受体是指一类能够识别和选择性结合某种配体（信号分子）的大分子，主要是糖蛋白和 糖脂。细胞表面受体主要识别和结合亲水性信号分子，包括分泌型信号分子（如神经递质、 多肽类激素、生长因子等）或膜结合型信号分子（细胞表面抗原、细胞表面黏着分子等）。 根据信号转导机制和受体蛋白类型的不同，细胞表面受体分为： （1）离子通道偶联受体，受体本身既有信号（配体）结合位点，又是离子通道。 （2）G 蛋白偶联受体（GPCR），是细胞表面受体中最大家族。 （3）酶联受体，其中一种受体胞内结构域具有潜在酶活性，另一类是受体本身不具酶活性， 而是受体胞内段与酶相联系。","kp":"ch10_s4_11"}],"calc":[{"id":"ch10_calc_5","modI":4,"q":"图解细胞表面受体调节基因表达的信号通路。","a":"相关图解参见 9.1 复习笔记中图 9-1-2 至图 9-1-9。 （1）G 蛋白偶联受体介导的信号通路 ①激活离子通道的 G 蛋白偶联受体介导的信号通路 a．心肌细胞上 M 乙酰胆碱受体激活的 G 蛋白开启 K 通道。 ＋   b．Gt 蛋白偶联的光受体的活化诱发 cGMP 门控阳离子通道的关闭。 ②激活或抑制腺苷酸环化酶的 G 蛋白偶联受体 ③激活磷脂酶 C，以 IP3 和 DAG 作为双信使的 G 蛋白偶联受体介导的信号通路 （2）酶联受体介导的信号转导 ①受体酪氨酸激酶及 RTK-Ras 蛋白信号通路 ②PI3K-PKB（Akt）信号通路 ③TGF-β受体及其 TGF-β-Smad 信号通路 ④细胞生长因子受体与 JAK-STAT 信号通路 （3）其他细胞表面受体介导的信号通路 ①Wnt 受体和 Hedgehog 受体介导的信号通路 ②NF-κB 和 Notch 信号通路","kp":"ch10_s4_11"}],"term":[]},{"i":5,"name":"三、NO信号[Ca2+→NO→cGMP→PKG]","slides":[{"i":13,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"三、NO信号[Ca2+→NO→cGMP→PKG]","notes":"(细胞内受体-鸟苷酸环化酶)\nNO作为信号分子的研究备受关注，R. Furchgott 等三位美国科\n学家因此获得1998年诺贝尔医学和生理学奖。\nNO是一种自由基性质的气体，具脂溶性，可快速扩散透过细胞\n膜，到达邻近靶细胞（细胞内受体结合）发挥作用。\n血管内皮细胞和神经细胞是NO的生成细胞。\n5-10 seconds), in the extracellular space在氧气和水的条件\n下被氧化为硝酸根或亚硝酸根。\n少心脏的工作负荷，降低心肌对氧气的需求。","page":14,"level":"掌握","img":"assets/img/ch10/p014.jpg","anim":null,"fig":null,"points":["NO acts only locally because it has a short half-life (about","硝酸甘油治疗心绞痛(心肌缺血)，即NO松弛了血管，减"],"check":{"q":"关于NO信号分子的叙述，正确的是？","o":["A. 是亲水性大分子，不能通过细胞膜","B. 半衰期很长，可远距离运输发挥作用","C. 具脂溶性，可快速扩散透过细胞膜作用于邻近靶细胞","D. 主要由红细胞大量产生"],"a":"C","e":"NO是具脂溶性的自由基性质气体，可快速扩散透过细胞膜到达邻近靶细胞，半衰期很短(约5-10秒)故仅局部作用；血管内皮细胞和神经细胞是其生成细胞。","oe":["错误，NO是脂溶性小分子气体，可自由扩散。","错误，NO半衰期仅约5-10秒，只能局部作用。","正确，NO脂溶性，快速扩散作用于邻近细胞。","错误，NO主要由血管内皮细胞和神经细胞产生。"]},"cards":null,"mem":"NO通路：Ca2+→NO→cGMP→PKG，脂溶速扩散","big":"assets/img/ch10/big/p014.jpg"},{"i":14,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"1998年诺贝尔生理学和医学奖","notes":"Robert F Furchgott, Louis J Ignarro和Ferid Murad，他们发现\n了“一氧化氮在心血管系统中作为信号分子\".\nLouis J Ignarro,         Ferid Murad, born 1936\nRobert F Furchgott,\nborn 1941                Dept. of Integrative\nborn 1916\nDept. of Pharmacology,   Dept. of Molecular and   Biology\nSUNY Health Science      Medical Pharmacology     Pharmacology and\nCenter                   UCLA School of           Physiology\nNew York                 Medicine                 University of Texas\nLos Angeles\nMedical School, Houston\n【中文讲解·对照课本/考点】\n考点：三、NO信号[Ca2+→NO→cGMP→PKG] ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页介绍1998年诺贝尔生理学或医学奖。获奖者Robert F. Furchgott、Louis J. Ignarro和Ferid Murad发现“一氧化氮（nitric oxide, NO）在心血管系统中作为信号分子”。NO是气体信号分子，可松弛血管平滑肌、调节血压。该发现说明气体信号分子可穿膜直接发挥作用。考点：NO是气体信号分子的经典实例。","page":15,"level":"掌握","img":"assets/img/ch10/p015.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于气体信号分子一氧化氮(NO)，下列叙述正确的是？","o":["A. 可作为信号分子参与心血管系统的调节","B. 只能作为毒性气体，无信号功能","C. 属于蛋白质类信号分子","D. 必须通过与膜受体结合才能进入细胞"],"a":"A","e":"NO是发现于心血管系统中的气体信号分子，可作为信息传导物质使血管平滑肌舒张；它是小分子气体，可自由扩散进入细胞。","oe":["NO在心血管系统中作为信号分子，正确。","NO具有重要的信号功能，并非仅是有毒气体。","NO是小分子气体，不是蛋白质。","NO可自由扩散，不依赖膜受体进入。"],"basis":"一氧化氮在心血管系统中作为信号分子"},"cards":null,"mem":"1998诺奖：Furchgott等三人发现NO信号分子","big":"assets/img/ch10/big/p015.jpg"},{"i":15,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"Furchgott的“三明治”试验","notes":"内皮细胞层被去除了。\n胞舒张，扩张血管壁。 。\n(Ach-induced relaxation of blood vessels was dependent on the\nendothelium.)\n平滑肌细胞\n\n【读图讲解】\n本页介绍Furchgott的「三明治」试验。文字说明实验用两种主动脉：一种内皮细胞层完整，另一种去除内皮。结果乙酰胆碱只有在内皮细胞完整时才能使血管平滑肌细胞舒张、扩张血管壁，即ACh引起的血管舒张依赖完整内皮。图中左幅为去除内皮，ACh使平滑肌进一步收缩(曲线上升)；右幅为保留内皮，ACh使平滑肌舒张(曲线下降)，并据此发现来自内皮的舒张因子EDRF。要点：该实验证明血管舒张由内皮释放的扩散性因子介导。","page":16,"level":"掌握","img":"assets/img/ch10/p016.jpg","anim":null,"fig":null,"points":["两种类型的主动脉：一种具有完整的内皮细胞层；另一种的","乙酰胆碱只有在內皮细胞完整时才会使血管平滑肌细"],"check":{"q":"Furchgott三明治实验说明？","o":["A. 乙酰胆碱引起的血管舒张依赖完整的内皮细胞","B. 乙酰胆碱直接作用于平滑肌使其舒张","C. 去除内皮后乙酰胆碱不引起收缩","D. 血管舒张由平滑肌自身产生，与内皮无关"],"a":"A","e":"Furchgott比较内皮完整与去除内皮的主动脉：乙酰胆碱只有在内皮细胞完整时才使血管平滑肌舒张，证明Ach引起的血管舒张依赖完整内皮，且由内皮释放的扩散性因子介导。","oe":["正确，实验表明Ach舒张血管依赖完整内皮。","错误，去除内皮后Ach反使平滑肌收缩。","错误，去除内皮后Ach使平滑肌进一步收缩。","错误，舒张依赖内皮释放的扩散性因子。"]},"cards":null,"mem":"三明治实验：ACh舒血管依赖完整内皮(EDRF)","big":"assets/img/ch10/big/p016.jpg"},{"i":16,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"1980年Furchgott实验成功地呈现：","notes":"管壁，是一种未知的信息传导物质而造成血管平\n滑肌放松。\n→他命名这种信息传导物质为EDRF\n(endothelium-derived relaxing factor，內皮细胞舒\n张因子)。","page":17,"level":"掌握","img":"assets/img/ch10/p017.jpg","anim":null,"fig":null,"points":["乙酰胆碱只有在內皮细胞完整时才会扩张血"],"check":{"q":"Furchgott实验发现，乙酰胆碱扩张血管的前提是？","o":["A. 血管平滑肌细胞完整","B. 血管内皮细胞完整","C. 血液中存在高浓度NO","D. 血管神经末梢完整"],"a":"B","e":"乙酰胆碱只有在内皮细胞完整时才会扩张血管，据此Furchgott推测内皮释放一种未知信息传导物质并命名EDRF（内皮细胞舒张因子）。","oe":["关键在于内皮细胞完整，而非平滑肌。","内皮完整时乙酰胆碱才扩张血管，正确。","该实验并非以外源高浓度NO为前提。","实验强调的是内皮而非神经末梢。"],"basis":"乙酰胆碱只有在內皮细胞完整时才会扩张血管"},"cards":null,"mem":"Furchgott命名EDRF=内皮细胞舒张因子","big":"assets/img/ch10/big/p017.jpg"},{"i":17,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"⎯identified EDRF as a molecule by using spectral(光谱) analysis","notes":"Ignarro’s spectral analysis\nof hemoglobin.\nHemoglobin (yellow) exposed to\nendothelial cells that were\nstimulated to produce EDRF (green)\nHemoglobin (yellow) directly exposed\nto NO (green).\nThe shift of absorption curves is\nidentical, hence EDRF is NO.\n【中文讲解·对照课本/考点】\n考点：三、NO信号[Ca2+→NO→cGMP→PKG] ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页讲述Ignarro的光谱分析（spectral analysis）实验。他报告内皮依赖性舒张因子（EDRF）能松弛血管，并利用血红蛋白（hemoglobin）光谱鉴定其本质：将内皮细胞受刺激产生的EDRF作用于血红蛋白，与NO直接作用者相比，吸收曲线位移完全相同，从而证明EDRF就是NO。考点：EDRF的化学本质为一氧化氮，实验中的对照与光谱比对是关键。","page":18,"level":"掌握","img":"assets/img/ch10/p018.jpg","anim":null,"fig":null,"points":["He reported that EDRF relaxed blood vessels."],"check":{"q":"Ignarro证明EDRF本质的实验依据是？","o":["A. EDRF可自身分解为硝酸根","B. EDRF与前列环素结构相同","C. EDRF与NO作用于血红蛋白的吸收曲线位移完全相同","D. EDRF能激活腺苷酸环化酶"],"a":"C","e":"Ignarro利用血红蛋白光谱分析，将内皮细胞受刺激产生的EDRF作用于血红蛋白，与NO直接作用者比较，二者吸收曲线位移完全相同，从而证明EDRF就是NO。","oe":["错误，这不是证明EDRF即NO的直接依据。","错误，EDRF不是前列环素，本质是NO。","正确，两者使血红蛋白吸收曲线位移相同。","错误，NO主要激活鸟苷酸环化酶使cGMP升高。"]},"cards":null,"mem":"光谱分析：EDRF与NO吸收曲线同→EDRF即NO","big":"assets/img/ch10/big/p018.jpg"},{"i":18,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"鸟苷酸环化酶","notes":"Murad’s enzyme activation\nNO 通过刺激鸟苷酸环化酶(Guanylyl cyclase)诱导\ncGMP的合成，抑制myosin-actin的相互作用，导致血\n管平滑肌舒张。\n【中文讲解·对照课本/考点】\n考点：三、NO信号[Ca2+→NO→cGMP→PKG] ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页讲解】\n本页讲解NO信号通路中的鸟苷酸环化酶（Guanylyl cyclase），以Murad的酶激活实验为背景。NO通过刺激鸟苷酸环化酶，诱导cGMP（环鸟苷酸）的合成；cGMP进而抑制肌球蛋白与肌动蛋白（myosin-actin）的相互作用，导致血管平滑肌舒张。这也解释了硝酸甘油等药物舒张血管的分子机制。考点联系翟中和《细胞生物学》第九章细胞信号转导第三节G蛋白偶联受体及相关通路，需掌握“Ca2+→NO→cGMP→PKG”及NO作为气体信号分子的作用特点。","page":19,"level":"掌握","img":"assets/img/ch10/p019.jpg","anim":null,"fig":null,"points":null,"check":{"q":"NO舒张血管平滑肌时，其直接激活的酶是？","o":["A. 磷脂酶C","B. 腺苷酸环化酶","C. 鸟苷酸环化酶","D. 磷酸二酯酶"],"a":"C","e":"NO刺激鸟苷酸环化酶，使GTP生成cGMP增多，进而抑制myosin-actin相互作用而舒张平滑肌。","oe":["磷脂酶C参与肌醇磷脂通路，生成IP3和DAG。","腺苷酸环化酶生成cAMP，非NO直接激活的酶。","NO激活鸟苷酸环化酶使cGMP增多，正确。","磷酸二酯酶降解cAMP/cGMP，与NO激活无关。"]},"cards":null,"mem":"NO激活鸟苷酸环化酶→cGMP↑→舒血管平滑肌","big":"assets/img/ch10/big/p019.jpg"},{"i":19,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"血管神经末梢释放乙酰胆碱(acetylcholine, ACh)","notes":"血管内皮细胞膜上：乙酰胆碱受体GPCR\n→磷脂酶C激活，产生IP3\nCa2+ 通道开放(Ca2+升高)\n→ Niric oxide synthase, NOS\nL-精氨酸→ NO+ L瓜氨酸\n● NO\n鸟苷酸环化酶(平滑肌细胞内受体)\nGTP→cGMP合成增多\n●活化PKG，抑制actin/myosin\n血管平滑肌细胞舒张，血管扩张变大、血流通畅","page":20,"level":"掌握","img":"assets/img/ch10/p020.jpg","anim":null,"fig":null,"points":null,"check":{"q":"血管内皮细胞中，乙酰胆碱(ACh)促进NO生成的信号途径是？","o":["A. ACh直接激活鸟苷酸环化酶生成NO","B. ACh受体GPCR→腺苷酸环化酶→cAMP→PKA→NOS生成NO","C. ACh激活酪氨酸激酶受体→Ras→NO","D. ACh受体GPCR→磷脂酶C→IP3→Ca2+升高→NOS催化精氨酸生成NO"],"a":"D","e":"ACh结合内皮细胞GPCR激活磷脂酶C，产生IP3使Ca2+升高，经NOS催化L-精氨酸生成NO。","oe":["鸟苷酸环化酶在平滑肌细胞内，不是生成NO的酶。","该途径为cAMP-PKA，不介导内皮NO生成。","酪氨酸激酶受体通路与ACh促NO生成无关。","ACh经GPCR-PLC-IP3-Ca2+激活NOS生成NO，正确。"]},"cards":null,"mem":"ACh→IP3→Ca→NOS→NO→cGMP→舒张血管","big":"assets/img/ch10/big/p020.jpg"},{"i":20,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"NO使血管平滑肌舒张：","notes":"硝酸甘油治疗心绞痛-心肌缺血；NO松弛血管)\n\n【读图讲解】\n本页说明NO使血管平滑肌舒张的机制，并联系硝酸甘油治疗心绞痛。图中标注5个步骤：①乙酰胆碱(ACh)与血管内皮细胞表面受体结合；②Ca2+进入内皮细胞；③在Ca2+和NO合酶作用下，精氨酸(Arg)转化为NO；④NO扩散进入邻近平滑肌细胞；⑤NO激活鸟苷酸环化酶，使GTP生成cGMP，cGMP引起平滑肌松弛、血管扩张。要点：NO是气体性信号分子，通过cGMP途径舒张血管，故硝酸甘油可缓解心肌缺血。","page":21,"level":"掌握","img":"assets/img/ch10/p021.jpg","anim":null,"fig":null,"points":null,"check":{"q":"硝酸甘油可缓解心绞痛，其作用机制是？","o":["A. 抑制乙酰胆碱酯酶，提高ACh浓度","B. 激活腺苷酸环化酶，使cAMP增多","C. 阻断钙通道，减少心肌收缩","D. 释放NO激活鸟苷酸环化酶，使cGMP增多、血管舒张"],"a":"D","e":"硝酸甘油在体内释放NO，激活平滑肌鸟苷酸环化酶使cGMP增多，引起血管舒张、改善心肌缺血。","oe":["硝酸甘油的作用与抑制乙酰胆碱酯酶无关。","其作用不通过cAMP增多实现。","硝酸甘油不是钙通道阻断剂，不能减少心肌收缩。","释放NO经cGMP途径舒血管，正确。"]},"cards":null,"mem":"硝酸甘油治心绞痛：释放NO→cGMP→舒血管","big":"assets/img/ch10/big/p021.jpg"},{"i":21,"sec":"三、NO信号[Ca2+→NO→cGMP→","title":"NO在神经系统疾病中的双重作用","notes":"功能。\n暂的通过NOS的激活而导致的NO增高，进而使脑血\n管扩张、增加脑血流、抗血小板凝集，从而抗缺血性\n脑损伤而起保护作用。\n吞噬细胞会诱导产生大量NOS，由此造成的NO过度\n释放则引起神经毒作用。","page":22,"level":"掌握","img":"assets/img/ch10/p022.jpg","anim":null,"fig":null,"points":["NO在神经细胞中产生，参与大脑的学习记忆的生理","如脑缺血损伤，研究表明一旦脑缺血发生后即有短","但如果病程发展到中、晚期，梗死灶内炎症细胞、"],"check":{"q":"关于NO在神经系统疾病中的双重作用，正确的是？","o":["A. NO在缺血任何阶段均只有保护作用","B. 早期短暂NO增高有保护作用，晚期大量NO释放产生神经毒作用","C. NO过量释放可保护神经元免受损伤","D. NO由吞噬细胞产生后抑制NOS"],"a":"B","e":"NO在神经细胞中参与学习记忆等生理功能；脑缺血早期短暂NO增高可扩张脑血管、增加脑血流、抗血小板凝集而起保护作用；中晚期梗死灶内炎症、吞噬细胞诱导大量NOS，NO过度释放则引起神经毒作用。","oe":["错误，晚期大量NO产生神经毒作用。","正确，早期NO起保护作用，晚期过量致神经毒。","错误，过量NO反而引起神经毒作用。","错误，炎症细胞诱导产生大量NOS，使NO过度释放。"]},"cards":null,"mem":"NO双重作用：早期扩血管保护；晚期过量致神经毒","big":"assets/img/ch10/big/p022.jpg"}],"mcq":[{"id":"ch10_amcq_1","mod":"三、NO信号[Ca2+→NO→cGMP→PKG]","modI":5,"q":"关于「NO信号[Ca2+→NO→cGMP→PKG]」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. NO acts only locally because it has a short half-life (about","C. 同一个细胞上不同受体应答不","D. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基"],"a":"B","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13","oe":["同一信号在不同细胞反应不同属信号传递一般特点，非NO信号要点。","NO半衰期短，只能局部发挥作用，符合NO气体信号特征，正确。","同一细胞上不同受体应答不同属受体特异性，与NO信号通路无关。","多肽激素的肽链长度描述属激素分类，与NO信号通路无关。"]}],"judge":[{"id":"ch10_judge_6","modI":5,"q":"来源于质膜的不同信号能通过细胞内不同信号途径间的相互作用而被整合。（         ）","a":"对","e":"","kp":"ch10_s5_18","oe":["胞内不同信号转导途径之间存在交叉对话，可对多种膜来源信号进行整合。","误以为各信号通路彼此孤立，其实通路间相互作用可实现信号整合。"]},{"id":"ch10_ajudge_2","modI":5,"q":"NO acts only locally because it has a short half-life (about","a":"对","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13","oe":["NO半衰期极短，扩散距离有限，只能作用于局部，故说法正确。","误以为NO可远距离稳定运输，忽视了它极短的半衰期。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":6,"name":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","slides":[{"i":22,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","notes":"多肽或水溶性分子)\n离子通道偶联受体\n跨膜结构域和胞内酶活性结构域","page":23,"level":"掌握","img":"assets/img/ch10/p023.jpg","anim":null,"fig":null,"points":["既有信号结合位点，本身又是离子通道的一部分","跨膜信号转导无需中间步骤，反应快","常见于可兴奋细胞间的突触信号传递如：nAchR","G蛋白偶联型受体","必须与G蛋白偶联才能产生胞内信使，传递信号","G蛋白为αβγ三个亚基组成的异三聚体G蛋白","进化相当保守，酵母→人","酶联受体","本身既是受体又是酶，有3个结构区:胞外配体结合域，","常见生长因子受体，具有酪氨酸蛋白激酶活性"],"check":{"q":"关于三类细胞膜表面受体的叙述，正确的是？","o":["A. G蛋白偶联受体是单次跨膜蛋白","B. 酶联受体本身不具有酶活性","C. 离子通道受体需G蛋白偶联才能发挥作用","D. 离子通道偶联受体反应快，常见于可兴奋细胞突触信号传递"],"a":"D","e":"膜表面受体分三类：离子通道偶联受体既是结合位点又是通道一部分，无需中间步骤、反应快，见于可兴奋细胞突触传递(nAChR)；G蛋白偶联受体需G蛋白偶联；酶联受体本身既受体又酶，常见生长因子受体具酪氨酸激酶活性。","oe":["错误，G蛋白偶联受体为7次跨膜受体。","错误，酶联受体本身既是受体又是酶。","错误，离子通道受体无需G蛋白中间步骤。","正确，离子通道受体反应快，见于突触传递。"]},"cards":null,"mem":"三类膜受体：离子通道偶联/G蛋白偶联/酶联","big":"assets/img/ch10/big/p023.jpg"},{"i":23,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"G-蛋白偶联受体与信","notes":"号分子结合时，信号\n先传递到一个G-蛋白\n(GTP结合蛋白)，然\n酶类和蛋白活性调节     后再通过它激活其它\n酶联受体本身在细\n胞内侧一端具有酶的\n活性，当其胞外端与\n配体信号分子结合后，\n单次跨膜   二聚体化：激活的普遍机制   则启动细胞膜内侧另\n一端的酶活性。只\n基因表达调控    跨膜1次","page":24,"level":"掌握","img":"assets/img/ch10/p024.jpg","anim":null,"fig":null,"points":["短期效应         靶蛋白。7次跨膜","长期效应"],"check":{"q":"关于G蛋白偶联受体的叙述，正确的是？","o":["A. 七次跨膜，与信号分子结合后通过G蛋白激活下游效应器","B. 单次跨膜，受体本身即具酶活性","C. 属于细胞内受体","D. 与配体结合后直接进入细胞核"],"a":"A","e":"G蛋白偶联受体为7次跨膜受体，与信号分子结合后，信号先传递给G蛋白(GTP结合蛋白)，再通过它激活其它酶和蛋白，产生短期或长期效应。","oe":["GPCR七次跨膜并通过G蛋白激活下游，正确。","单次跨膜且本身具酶活性的是酶联受体。","GPCR位于细胞膜表面，属膜受体。","GPCR不进入细胞核，靠下游通路起作用。"],"basis":"信号先传递到一个G-蛋白...然后再通过它激活其它酶类和蛋白...7次跨膜"},"cards":null,"mem":"GPCR 7次跨膜；酶联受体单跨膜、二聚化、具酶活","big":"assets/img/ch10/big/p024.jpg"},{"i":24,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"2021诺贝尔生理和医学奖","notes":"温度和机械压力如何\n被感知，转化为神经\n冲动信号？\nHow are nerve\nimpluses initiated so\nthat temperature and\npressure can be\nperceived?\n【中文讲解·对照课本/考点】\n考点：四、细胞膜表面的受体(信号分子为亲水蛋白质、 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n•  recognition）●概念：细胞通过其表面的受体与胞外信号物质分子（配体）选择性地相互作用，进而导致胞内一系列生理生化变化，最终表现为细胞整体的生物学效应的过程。●信号通路（signaling pathway）细胞识别是通过各种不同的信号通路实现的。细胞接受外界信号，通过一整套特定的机制，将胞外信号转导为胞内信号，最终调节特定基因的表达，引起细胞的应答反应，这种反应系列称之为细胞信号通路。\n\n【本页英文讲解】\n本页主题为2021年诺贝尔生理学或医学奖。核心问题：温度和机械压力如何被感知并转化为神经冲动信号？即神经冲动（nerve impulses）如何被引发，使机体感知温度与压力。该奖授予David Julius与Ardem Patapoutian，分别发现温度感受器和机械感受器。考点：感受器属于离子通道，外界物理刺激可直接门控通道，把物理信号转换为电信号。","page":25,"level":"掌握","img":"assets/img/ch10/p025.jpg","anim":null,"fig":null,"points":null,"check":{"q":"温度与机械压力被感知并转化为神经冲动的机制，主要涉及？","o":["A. 通过G蛋白偶联受体产生cAMP","B. 通过胞吞将刺激物摄入神经元","C. 通过DNA转录变化直接产生冲动","D. 离子通道被物理刺激门控，将物理信号转换为电信号"],"a":"D","e":"温度和机械压力如何被感知并转化为神经冲动，其核心是感受器属于离子通道，外界物理刺激可直接门控通道，把物理信号转换为电信号。","oe":["该过程由离子通道直接门控，非经cAMP通路。","温度与压力的感知并不依赖胞吞作用。","神经冲动是电信号，不直接由转录变化产生。","离子通道被物理刺激门控并转换为电信号，正确。"],"basis":"感受器属于离子通道，外界物理刺激可直接门控通道，把物理信号转换为电信号"},"cards":null,"mem":"2021诺奖：温度与机械压力如何转为神经冲动","big":"assets/img/ch10/big/p025.jpg"},{"i":25,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"戴维·朱利叶斯利用辣椒素（一种来自辣椒的刺激性化合物，可引起灼","notes":"烧感）来识别皮肤神经末梢中对热有反应的感受器。\nTRPV1，encoded a novel ion channel protein, is a heat-sensing\nreceptor 热敏受体（capsaicin receptor) and is activated at temperatures\nperceived as painful. 该受体能在令人感到疼痛的温度下被激活。\n【中文讲解·对照课本/考点】\n考点：四、细胞膜表面的受体(信号分子为亲水蛋白质、 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。","page":26,"level":"掌握","img":"assets/img/ch10/p026.jpg","anim":null,"fig":null,"points":null,"check":{"q":"戴维·朱利叶斯利用辣椒素识别出的热敏受体是？","o":["A. 视紫红质","B. TRPV1","C. Piezo1","D. Piezo2"],"a":"B","e":"Julius用辣椒素识别皮肤神经末梢的热感受器TRPV1，它可被致痛温度激活的离子通道。","oe":["视紫红质是视网膜光受体，非热敏受体。","TRPV1是辣椒素受体、热敏离子通道，正确。","Piezo1为机械门控离子通道，非热敏受体。","Piezo2为机械敏感离子通道，非热敏受体。"]},"cards":null,"mem":"朱利叶斯：辣椒素→TRPV1热敏受体，痛温激活","big":"assets/img/ch10/big/p026.jpg"},{"i":26,"sec":"四、细胞膜表面的受体(信号分子为亲水蛋白","title":"阿尔代姆·帕塔普蒂","notes":"安利用压敏细胞发现\n了一种可对皮肤和内\n脏中的机械刺激做出\n反应的新型感受器。\nCultured\nmechanosensitive\ncells were poked\nwith a micropipette.\nPiezo1 and Piezo2 are ion channels that are directly activated\nby the exertion of pressure on cell membrane.\n【中文讲解·对照课本/考点】\n考点：四、细胞膜表面的受体(信号分子为亲水蛋白质、 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n•  recognition）●概念：细胞通过其表面的受体与胞外信号物质分子（配体）选择性地相互作用，进而导致胞内一系列生理生化变化，最终表现为细胞整体的生物学效应的过程。●信号通路（signaling pathway）细胞识别是通过各种不同的信号通路实现的。细胞接受外界信号，通过一整套特定的机制，将胞外信号转导为胞内信号，最终调节特定基因的表达，引起细胞的应答反应，这种反应系列称之为细胞信号通路。\n\n【本页英文讲解】\n本页介绍阿尔代姆·帕塔普蒂安（Ardem Patapoutian）。研究者用微吸管（micropipette）戳压压敏细胞（mechanosensitive cells），发现一种可对皮肤和内脏机械刺激作出反应的新型感受器。Piezo1和Piezo2是离子通道，可被细胞膜上的压力直接激活。考点：Piezo是机械门控离子通道，可把机械力转为电信号。","page":27,"level":"掌握","img":"assets/img/ch10/p027.jpg","anim":null,"fig":null,"points":null,"check":{"q":"帕塔普蒂安发现的Piezo1、Piezo2属于？","o":["A. 机械门控离子通道","B. 酪氨酸激酶受体","C. G蛋白偶联受体","D. 热敏离子通道"],"a":"A","e":"Piezo1和Piezo2是离子通道，可被细胞膜所受压力直接激活，将机械刺激转为电信号。","oe":["Piezo1/2为机械门控离子通道，正确。","Piezo不具酪氨酸激酶活性。","Piezo是离子通道，不是GPCR。","热敏受体为TRPV1，非Piezo。"]},"cards":null,"mem":"帕塔普蒂安：微管戳压→Piezo1/2机械门控通道","big":"assets/img/ch10/big/p027.jpg"}],"mcq":[{"id":"ch10_mcq_6","mod":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","modI":6,"q":"表皮生长因子（EGF）的穿膜信号转导是通过（                ）实现的。","o":["A．活化酪氨酸激酶","B．活化酪氨酸磷酸酶","C．cAMP 调节途径","D．cGMP 调节途径"],"a":"A","e":"EGF 的受体分子是酪氨酸激酶受体，EGF 可以活化酪氨酸激酶受体，使其获得激 酶活性，从而传导信号。","kp":"ch10_s6_22","oe":["EGF受体属酪氨酸激酶受体，结合EGF后激活其激酶活性，正确。","酪氨酸磷酸酶催化去磷酸化，与EGF受体被激活相反。","EGF不通过cAMP调节途径实现穿膜信号转导。","EGF不通过cGMP调节途径实现穿膜信号转导。"]}],"judge":[{"id":"ch10_judge_4","modI":6,"q":"激素受体都具有酪氨酸受体结构域。(       )","a":"错","e":"激素受体都具有各自激素的特异结构域。","kp":"ch10_s6_22","oe":["误以为激素受体都含酪氨酸激酶结构域，故判对。","各类激素受体具有各自激素的特异结构域，并非都有酪氨酸受体结构域。"]}],"fill":[{"id":"ch10_fill_3","modI":6,"q":"从蛋白结构看，蛋白激酶 A 是由______组成的，而蛋白激酶 C 是______组成。","a":"四个亚基；只有一条肽链","kp":"ch10_s6_22","oe":["PKA由两个调节亚基和两个催化亚基组成四聚体","PKC只由一条肽链构成，含调节区和催化区"]},{"id":"ch10_fill_10","modI":6,"q":"受体自磷酸化的结果是激活了受体的______活性，磷酸化的酪氨酸残基可被含有______ 结构域的胞内信号蛋白识别。","a":"酪氨酸蛋白激酶；SH2","kp":"ch10_s6_22","oe":["配体使受体二聚化，自磷酸化激活酪氨酸蛋白激酶","磷酸化酪氨酸残基可被含SH2结构域的蛋白识别"]},{"id":"ch10_fill_15","modI":6,"q":"细胞内的受体具有同源性，一般由 800 个氨基酸组成，分为三个结构域，即______，______ 和______。","a":"C 端与信号分子结合部位；中部与 DNA 结合部位；N 端激活基因转录部位查看答 案","kp":"ch10_s6_22","oe":["C端为与信号分子（激素）结合的部位","中间为与DNA结合的结构域，常含锌指结构","N端为激活基因转录的结构域，调节表达"]}],"short":[],"calc":[{"id":"ch10_calc_1","modI":6,"q":"试述细胞接受化学信号后调节基因表达的途径？","a":"（1）细胞内受体的本质是激素激活的基因调控蛋白，当细胞内受体接受甾类激素后， 会引起受体构象变化，使得结合在受体上的抑制蛋白复合物解离，暴露出受体与 DNA 结合 的位点，受体被激活，激活的受体通过结合于特异 DNA 序列将调节基因的表达。（20 由细 胞外受体接受水溶性的激素信号，通过信号转导在细胞内会产生第二信号分子 IP3／DG 和 第三信使 Ca 离子。蛋白激酶 C(PKC)在 DG 和 Ca2+浓度的升高条件下，激活细胞内的靶酶 蛋白激酶 C，PKC 激活时成为膜结合的酶，属于多功能丝氨酸、苏氨酸激酶，可作用于胞 质中的某些酶，参与生化反应的调节；也可作用于细胞核的转录因子，参与基因表达的调控。","kp":"ch10_s6_23"}],"term":[{"id":"ch10_term_5","modI":6,"term":"离子通道耦联受体（ion-channel-coupled receptor）。","def":"离子通道耦联受体是由多亚基组成的受体一离子通道复合体，本身既有结合位点，又是 离子通道，其跨膜信号转导无需中间步骤。","kps":"","kp":"ch10_s6_22"},{"id":"ch10_term_8","modI":6,"term":"RTK","def":"RTK 的中文名称是受体酪氨酸激酶。受体酪氨酸激酶是一类酶联受体，既是受体，又 具有酶功能。当 RTK 与其配体结合后，两个受体在膜上二聚化，两个受体分子具有微弱的 蛋白激酶活性，当它们相互靠近后通过相互磷酸化的机制将二者自身的蛋白激酶活化，使下 游蛋白的酪氨酸残基磷酸化，从而实现信号转导的功能。所有的受体酪氨酸激酶都由三个部 分组成：具配体结合位点的胞外结构域、单次跨膜的疏水α螺旋区、具酪氨酸蛋白激酶活性 的胞内结构域。","kps":"","kp":"ch10_s6_22"}]},{"i":7,"name":"4.1 G protein-Cou","slides":[{"i":27,"sec":"4.1    G protein-Cou","title":"G蛋白偶联的受体","notes":"4.1    G protein-Coupled receptors (GPCR)\n细胞表面受体的最大家族，哺乳动物\n细胞中已鉴定有数百个之多，可结合\n蛋白或肽类激素、神经递质、氨基酸\n或脂肪酸衍生物等多种信号分子。\n但已有的分析表明，所有G蛋白偶联受体都\n有类似结构：一条来回跨膜7次的多肽\n链组成。\n如脊椎动物眼中的光激活受体－视紫\n红质和鼻中的嗅觉受体、味觉受体。\nLigand(orange)\nThere are more than 800 GPCRs in humans, and      binds in a pocket\nin mice there are about 1000 concerned with the   between the helices\nsense of smell alone.\n【中文讲解·对照课本/考点】\n考点：4.1 G protein-Cou ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系","page":28,"level":"掌握","img":"assets/img/ch10/p028.jpg","anim":null,"fig":null,"points":null,"check":{"q":"所有G蛋白偶联受体(GPCR)共有的结构特征是？","o":["A. 一次跨膜的单个跨膜区","B. 四次跨膜形成离子通道","C. 由α、β、γ三亚基组成","D. 一条来回跨膜7次的多肽链"],"a":"D","e":"GPCR均由一条来回跨膜7次的多肽链构成，是细胞表面受体最大家族。","oe":["一次跨膜是受体酪氨酸激酶的特征。","四次跨膜为离子通道偶联受体的特征。","α、β、γ三亚基指G蛋白，而非受体。","七次跨膜是GPCR的共同结构特征，正确。"]},"cards":null,"mem":"GPCR最大家族，7次跨膜，人的>800种","big":"assets/img/ch10/big/p028.jpg"},{"i":28,"sec":"4.1    G protein-Cou","title":"视紫红质","notes":"视网膜杆细胞中视紫                                     －G-蛋白偶联受体\n红质的三维结构\n当rhodopsin蛋白中\n的光吸收基团(red)吸\n收光量子后，视紫红\n视网膜的视杆细胞对光线                                          质被激活，其蛋白构\n非常敏感，负责接收弱光                                          象发生改变，进而将\n刺激。                                                  信号传递给细胞内的\nG-蛋白。\n人类视杆细胞含有大约\n4×107个rhodopsin。\nthe level of cGMP.\n(光信号下G蛋白偶联受体-视紫红质激活，引起cGMP水平下降,视\n杆细胞膜上阳离子通道关闭，膜超极化。","page":29,"level":"掌握","img":"assets/img/ch10/p029.jpg","anim":null,"fig":null,"points":["The receptor activation stimulated by light causes a fall rather than a rise in"],"check":{"q":"关于视紫红质信号通路的叙述，正确的是？","o":["A. 光激活视紫红质使cGMP升高，阳离子通道开放","B. 视紫红质属于酶联受体，本身具激酶活性","C. 光激活视紫红质使cGMP水平下降，阳离子通道关闭，膜超极化","D. 视紫红质激活导致视杆细胞膜去极化"],"a":"C","e":"视紫红质是视网膜杆细胞中的G蛋白偶联受体，光量子使其构象改变并将信号传给G蛋白，引起cGMP水平下降，视杆细胞膜上阳离子通道关闭，膜超极化。","oe":["错误，视网膜信号通路中cGMP是下降的。","错误，视紫红质是G蛋白偶联受体。","正确，光激活视紫红质使cGMP下降、通道关闭、超极化。","错误，cGMP下降使通道关闭，膜超极化。"]},"cards":null,"mem":"视紫红质=光激活GPCR，吸光变构→激活G蛋白","big":"assets/img/ch10/big/p029.jpg"},{"i":29,"sec":"4.1    G protein-Cou","title":"视杆细胞膜上","notes":"GPCR：光受体\n① 弱光下，GPCR视紫红质激活\n② cGMP磷酸二酯酶PDE催化cGMP→GMP，胞质内\ncGMP水平降低。\n③ 阳离子通道关闭(Na+, Ca2+)\n④ 细胞膜超极化","page":30,"level":"掌握","img":"assets/img/ch10/p030.jpg","anim":null,"fig":null,"points":null,"check":{"q":"视杆细胞受弱光刺激后，胞内cGMP水平及膜电位的变化是？","o":["A. cGMP升高，细胞膜超极化","B. cGMP降低，细胞膜超极化","C. cGMP升高，细胞膜去极化","D. cGMP降低，细胞膜去极化"],"a":"B","e":"弱光下视紫红质激活cGMP磷酸二酯酶，cGMP被水解而降低，阳离子通道关闭，细胞膜超极化。","oe":["cGMP方向错误，弱光下应降低。","cGMP降低致阳离子通道关闭、膜超极化，正确。","cGMP不是升高而是降低，膜也不去极化。","cGMP降低正确，但结果为超极化而非去极化。"]},"cards":null,"mem":"光→视紫红质→PDE降cGMP→阳离子通道关→超极化","big":"assets/img/ch10/big/p030.jpg"},{"i":30,"sec":"4.1    G protein-Cou","title":"The Nobel Prize in Chemistry 2012","notes":"\"for studies of G-protein-coupled receptors\"\nRobert J. Lefkowitz    Brian K. Kobilka\nRobert J. Lefkowitz,        Brian K. Kobilka,\nU.S. citizen.               U.S. citizen.\nStanford University School\nDuke University Medical\nof Medicine\nCenter\n【中文讲解·对照课本/考点】\n考点：4.1 G protein-Cou ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页主题为2012年诺贝尔化学奖，获奖理由是“对G蛋白偶联受体的研究”，获奖者为Robert J. Lefkowitz和Brian K. Kobilka。G蛋白偶联受体（G-protein-coupled receptors, GPCR）是最大的膜受体家族，通过激活异源三聚体G蛋白传递信号。考点：GPCR七次跨膜的结构特征及其作为药物靶点的地位。","page":31,"level":"掌握","img":"assets/img/ch10/p031.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于G蛋白偶联受体(GPCR)的结构特征，下列叙述正确的是？","o":["A. 七次跨膜，是最大的膜受体家族之一","B. 单次跨膜","C. 是细胞内受体","D. 不含跨膜结构域"],"a":"A","e":"G蛋白偶联受体具有七次跨膜的结构特征，是最大的膜受体家族，通过激活异源三聚体G蛋白传递信号，也是重要的药物靶点。","oe":["GPCR七次跨膜且为最大膜受体家族之一，正确。","单次跨膜是酶联受体等其它受体的特征。","GPCR是膜受体，不是细胞内受体。","GPCR含有七个跨膜结构域，故A正确。"],"basis":"GPCR七次跨膜的结构特征...最大的膜受体家族"},"cards":null,"mem":"2012化学诺奖：Lefkowitz/Kobilka","big":"assets/img/ch10/big/p031.jpg"},{"i":31,"sec":"4.1    G protein-Cou","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• BRAIN/EYES/HEART/LUNGS/MUSCLE/LIVER/FAT CELLS/STOMACH&INTESTINES —— 脑/眼/心/肺/肌肉/肝/脂肪细胞/胃肠（应激时的反应器官）\n• adrenal gland / medulla / cortex —— 肾上腺 / 髓质 / 皮质\n• adrenalin, noradrenalin, cortisol —— 肾上腺素、去甲肾上腺素、皮质醇\n• Figure 1. Time to flee! —— 图1 应激逃逸：脑发出神经信号与激素激活肾上腺，应激激素入血，全身细胞通过受体感知\n【读图讲解】\n情景图：应激时脑发信号并经激素激活肾上腺(adrenal gland)，引起瞳孔放大、心率加快、支气管扩张、肌肉血流增加、肝释放糖、消化道血流减少。考点：神经-体液调节；肾上腺髓质分泌肾上腺素/去甲肾上腺素、皮质分泌皮质醇，靶细胞靠受体感知信号。","page":32,"level":"掌握","img":"assets/img/ch10/p032.jpg","anim":null,"fig":null,"points":["BRAIN","EYES","HEART","Nervesignalswarntherest","Thepupils","Adrenalinandnoradrenalin","of thebody.Thebrainalso","expand.The"],"check":{"q":"应激（如“战斗或逃跑”）时，肾上腺髓质分泌的激素主要是？","o":["A. 肾上腺素和去甲肾上腺素","B. 皮质醇和醛固酮","C. 甲状腺素和视黄酸","D. 胰岛素和胰高血糖素"],"a":"A","e":"应激时肾上腺髓质分泌肾上腺素和去甲肾上腺素（皮质分泌皮质醇），经血液作用于全身靶细胞。","oe":["肾上腺髓质分泌肾上腺素和去甲肾上腺素，正确。","二者由肾上腺皮质分泌，与髓质不符。","甲状腺素由甲状腺分泌，视黄酸并非激素。","胰岛素、胰高血糖素由胰岛分泌。"]},"cards":null,"mem":"应激逃逸：脑→肾上腺(髓质肾上腺素/皮质醇)→全身","big":"assets/img/ch10/big/p032.jpg"},{"i":32,"sec":"4.1    G protein-Cou","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• 1 A hormone binds to the receptor —— 1 激素与受体结合\n• 2 receptor alters shape; G-protein binds & is activated —— 2 受体变构，G蛋白结合并被激活\n• 3 activated G-protein breaks apart; free α-subunit triggers reactions —— 3 活化G蛋白解离，游离α亚基触发反应链改变细胞代谢\n• 4 a new G-protein binds; receptor activates hundreds before hormone detaches —— 4 新G蛋白结合；激素脱离前受体可激活上百个G蛋白\n• hormone/receptor/cell membrane/α,β,γ —— 激素 / 受体 / 细胞膜 / α、β、γ 亚基\n• Figure 2 —— 图2 激素/气味/味觉分子结合表面受体→胞内级联反应\n【读图讲解】\n四步过程图：激素(hormone)结合膜受体(receptor)→受体变构激活G蛋白并使其解离→游离α亚基触发胞内反应链；一个激素可反复激活上百个G蛋白。考点：G蛋白偶联受体信号转导与信号放大(α/β/γ亚基)。","page":33,"level":"掌握","img":"assets/img/ch10/p033.jpg","anim":null,"fig":null,"points":["Thereceptoraltersshape.","Ahormonebinds","Inside thecell,theG-protein","to thereceptor.","bindsand isactivated.","hormone","receptor","33377737333"],"check":{"q":"激素通过G蛋白偶联受体转导信号时，G蛋白被激活的直接表现是？","o":["A. 受体被内吞入胞浆后激活G蛋白","B. 活化G蛋白解离，游离α亚基触发胞内反应","C. G蛋白与激素直接结合形成复合物","D. βγ亚基被降解，仅α亚基保留"],"a":"B","e":"受体变构后G蛋白结合并活化、解离，游离α亚基触发胞内反应链，一个激素可激活上百个G蛋白。","oe":["激活发生于膜上，不依赖受体内吞。","G蛋白活化后解离，α亚基触发下游反应，正确。","激素结合受体而非直接结合G蛋白。","βγ亚基并不被降解，而是与α亚基解离。"]},"cards":null,"mem":"四步：激素结合受体→变构激活G蛋白→α解离触发","big":"assets/img/ch10/big/p033.jpg"},{"i":33,"sec":"4.1    G protein-Cou","title":"Structural model of G","notes":"protein-coupled\nreceptor (rhodopsin)\nand its associated\nheterotrimeric G\nprotein (2001, 2006)\nThe 3 subunits of the G\nprotein are color coded.\n【中文讲解·对照课本/考点】\n考点：4.1 G protein-Cou ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页展示G蛋白偶联受体（GPCR，此处为视紫红质rhodopsin）及其偶联的异源三聚体G蛋白（heterotrimeric G protein）的结构模型，成果发表于2001、2006年。图中G蛋白的3个亚基（α、β、γ）用不同颜色标出。核心概念：受体与G蛋白偶联是信号跨膜传递的关键一步。考点：G蛋白由α、β、γ三亚基构成，α亚基结合并水解GTP。","page":34,"level":"掌握","img":"assets/img/ch10/p034.jpg","anim":null,"fig":null,"points":null,"check":{"q":"异源三聚体G蛋白的三个亚基是？","o":["A. α、β、δ","B. α、β、γ","C. α、γ、δ","D. β、γ、ε"],"a":"B","e":"异源三聚体G蛋白由α、β、γ三个亚基组成，图中三亚基以不同颜色标出；α亚基可结合并水解GTP。","oe":["G蛋白第三个亚基是γ，不是δ。","G蛋白由α、β、γ三亚基构成，正确。","选项缺少β亚基，亚基组合错误。","选项缺少α亚基，亚基组合错误。"],"basis":"G蛋白由α、β、γ三亚基构成"},"cards":null,"mem":"GPCR-异三聚体G蛋白结构：αβγ三亚基着色","big":"assets/img/ch10/big/p034.jpg"}],"mcq":[{"id":"ch10_amcq_3","mod":"4.1 G protein-Cou","modI":7,"q":"关于「G protein-Cou」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. 同一个细胞上不同受体应答不","C. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","D. The receptor activation stimulated by light causes a fall rather than a rise in"],"a":"D","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27","oe":["同一信号在不同细胞反应不同属信号传递特点，非G蛋白偶联受体内容。","同一细胞上不同受体应答不同属受体特异性，与本题无关。","多肽激素的肽链长度属信号分子分类，与G蛋白偶联受体无关。","光激活受体使cGMP水平下降而非上升，属GPCR光转导，正确。"]}],"judge":[{"id":"ch10_ajudge_4","modI":7,"q":"The receptor activation stimulated by light causes a fall rather than a rise in","a":"对","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27","oe":["光激活视紫红质后引起cGMP浓度下降而非升高，从而产生视觉信号。","误以为光激活受体使cGMP升高，方向判断正好相反。"]}],"fill":[],"short":[],"calc":[{"id":"ch10_calc_2","modI":7,"q":"从受体的角度解读家族性高胆固醇血症的发病机理。","a":"在肝细胞及肝外组织的细胞膜表面广泛存在着低密度脂蛋白(LDL)受体，它能与血浆中 富含胆固醇的 LDL 颗粒相结合，并经受体介导的内吞作用进入细胞。在细胞内受体与 LDL 解离，再回到细胞膜，而 LDL 则在溶酶体内降解并释放出胆固醇，供给细胞代谢需要并降 低血浆胆固醇含量。如果由于各种原因(如受体合成受损；受体发生细胞内转运障碍；受体 与配体结合力降低；受体内吞缺陷；受体再循环障碍)导致受体数量减少或功能异常，其对 血浆 LDL 的清除能力降低，患者出生后血浆 LDL 含量即高于正常，发生动脉粥样硬化的危 险也显著升高。","kp":"ch10_s7_27"}],"term":[]},{"i":8,"name":"4.1.1 G蛋白与跨膜信号转导","slides":[{"i":34,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"4.1.1   G蛋白与跨膜信号转导","notes":"蛋白两大类。具有GTPase的作用，通过对结合的GTP\n的可逆水解来完成静止态与激活态的转换。为细胞内\n信号转导过程中重要的分子开关。\n三个亚基组成， α亚基具内在的GTP水解酶活性。 α\n－GDP为静止态， α－GTP激活态。","page":35,"level":"掌握","img":"assets/img/ch10/p035.jpg","anim":null,"fig":null,"points":["G蛋白又称GTP结合蛋白，有异三聚体G蛋白、小G","G蛋白偶联受体中的是异三聚体G蛋白，由α、β、γ"],"check":{"q":"关于G蛋白偶联受体信号转导中的异三聚体G蛋白，叙述正确的是（　）","o":["A. 其激活与失活通过亚基的磷酸化与去磷酸化实现","B. 由单一多肽链组成，分子量约20～30kDa","C. 由α、β、γ三个亚基组成，α亚基具有内在的GTP水解酶活性","D. 结合GTP时为静止态，结合GDP时为激活态"],"a":"C","e":"异三聚体G蛋白由α、β、γ三个亚基组成，α亚基具内在GTP水解酶活性；α-GTP为激活态、α-GDP为静止态，它是重要的分子开关。","oe":["错误：G蛋白靠GTP/GDP可逆水解转换，而非磷酸化与去磷酸化。","错误：单一多肽链、20～30kDa是小G蛋白（如Ras）的结构特征。","正确：异三聚体G蛋白由α、β、γ三亚基组成，α亚基具内在GTP水解酶活性。","错误：α-GTP为激活态，α-GDP为静止态，两者被颠倒。"]},"cards":null,"mem":"G蛋白GTPase分子开关：α-GDP静，α-GTP活","big":"assets/img/ch10/big/p035.jpg"},{"i":35,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"异三聚体G-蛋白","notes":"◆组成:  一般由三个亚基组成, 分别叫α、 β、γ,\n其中β、γ两亚基通常紧密结合在一起, 只有在蛋白\n变性时才分开。\n◆功能位点: α-亚基具有三个功能位点：\n①GTP结合位点;\n②鸟苷三磷酸水解酶(GTPase)活性;\n③ADP-核糖化位点。","page":36,"level":"掌握","img":"assets/img/ch10/p036.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于异三聚体G蛋白α亚基的功能位点，正确的是？","o":["A. 只具ADP-核糖化位点，不能结合GTP","B. 只具GTP结合位点，无酶活性","C. 具ATP结合位点和ATPase活性","D. 具GTP结合位点、GTPase活性和ADP-核糖化位点"],"a":"D","e":"α亚基具有GTP结合位点、鸟苷三磷酸水解酶(GTPase)活性和ADP-核糖化位点三个功能位点。","oe":["α亚基确实能结合GTP，该说法错误。","α亚基还具GTPase活性，该说法不全面。","α亚基结合GTP而非ATP，无ATPase活性。","α亚基具备这三个功能位点，正确。"]},"cards":null,"mem":"异三聚体G蛋白αβγ，α具GTP结合与水解酶","big":"assets/img/ch10/big/p036.jpg"},{"i":36,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"无活性状态","notes":"α亚基结合GTP，激活并与β,γ亚基分开，与特\n定靶蛋白结合。\nG蛋白的激活态\n\n【读图讲解】\n本页展示G蛋白的激活态。上方为无活性状态：G蛋白由α、β、γ三亚基组成并结合GDP，静息时与受体相邻(左)或分离(右)。当信号分子与受体结合后，受体使α亚基上的GDP被GTP置换，α亚基结合GTP而被激活，并与βγ亚基分开，分别去结合特定靶蛋白。下方标注activated α subunit(GTP)与activated βγ complex，即G蛋白的激活态。要点：G蛋白以GDP/GTP结合状态充当分子开关，GTP结合型为「开」，并解离成α与βγ两部分发挥作用。","page":37,"level":"掌握","img":"assets/img/ch10/p037.jpg","anim":null,"fig":null,"points":null,"check":{"q":"G蛋白由无活性态转为激活态的关键变化是？","o":["A. α亚基上GTP被GDP置换并重新结合βγ","B. α亚基上GDP被GTP置换并与βγ亚基分开","C. α、β、γ三亚基聚合成一体","D. βγ亚基与GTP结合后解离"],"a":"B","e":"信号分子结合受体后，α亚基上的GDP被GTP置换，α亚基激活并与βγ分开，去结合靶蛋白。","oe":["这是G蛋白的失活过程，与激活方向正好相反。","GDP被GTP置换、α与βγ分开，正确。","G蛋白激活时亚基解离，而非聚合成一体。","结合GTP的是α亚基而非βγ。"]},"cards":null,"mem":"G蛋白活化：受体促GDP→GTP置换，α解离结合靶蛋白","big":"assets/img/ch10/big/p037.jpg"},{"i":37,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"心肌细胞","notes":"G-偶联受体和神经\n递质乙酰胆碱结合\nG蛋白-GTP激活\n激活的βγ亚基\n打开心肌细胞质膜\n上的K+通道\nK+到胞外，降低细\n胞的兴奋性。\nα亚基内在的GTPase活性将GTP水解\n为GDP，使其与靶蛋白脱离，并与βγ   G蛋白灭活态（静止态）\n复合物重新形成G蛋白－GDP的静止态","page":38,"level":"掌握","img":"assets/img/ch10/p038.jpg","anim":null,"fig":null,"points":null,"check":{"q":"乙酰胆碱使心肌细胞K+通道开放、膜超极化的过程中，直接打开K+通道的是？","o":["A. 激活的腺苷酸环化酶","B. 激活的βγ亚基","C. 激活的α亚基","D. 激活的PKA"],"a":"B","e":"心肌细胞中G蛋白激活后解离出的βγ亚基直接打开质膜K+通道，K+外流使膜超极化。","oe":["腺苷酸环化酶产生cAMP，不直接开通道。","激活的βγ亚基直接打开K+通道，正确。","此处打开K+通道的是βγ亚基，而非α亚基。","PKA为下游激酶，非直接开K+通道者。"]},"cards":null,"mem":"心肌ACh：Gβγ开K+通道→K+外流超极化→减慢收缩","big":"assets/img/ch10/big/p038.jpg"},{"i":38,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"α亚基内在的","notes":"GTPase活性将GTP\n水解为GDP，使其与\n靶蛋白脱离，并与βγ复\n合物重新形成G蛋白－     G蛋白灭活态\nGDP的静止态","page":39,"level":"掌握","img":"assets/img/ch10/p039.jpg","anim":null,"fig":null,"points":null,"check":{"q":"使G蛋白回到失活态（G蛋白-GDP静止态）的是？","o":["A. 腺苷酸环化酶水解cAMP","B. α亚基内在的GTPase将GTP水解为GDP","C. 磷脂酶C水解PIP2","D. GEF促进GDP解离并结合GTP"],"a":"B","e":"α亚基内在的GTPase活性将GTP水解为GDP，使其与靶蛋白脱离并与βγ重新形成G蛋白-GDP静止态。","oe":["腺苷酸环化酶催化合成cAMP，不水解cAMP。","α亚基GTPase水解GTP使G蛋白失活，正确。","磷脂酶C参与肌醇磷脂通路，与G蛋白失活无关。","GEF促进GDP换GTP，是激活而非失活。"]},"cards":null,"mem":"α亚基GTPase水解GTP成GDP，与βγ重组成静止态","big":"assets/img/ch10/big/p039.jpg"},{"i":39,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"小G蛋白","notes":"白，分子量只有20－30kDa。Ras , Rho,\nRab等\n●具有两种鸟嘌呤核苷酸的结合形式即结合GTP\n有活性，结合GDP无活性。\n●也具有内源GTPase活性，由它完成GTP,GDP的\n转换，结束一次信号传导过程。\n【结合课本/笔记】cAMP信号通路●反应链：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录●组分及其分析G-蛋白偶联受体G-蛋白活化与调节效应酶——腺苷酸环化酶●GPLR的失敏（desensitization）与减量调节●细菌毒素对G蛋白的修饰作用","page":40,"level":"掌握","img":"assets/img/ch10/p040.jpg","anim":null,"fig":null,"points":["异三聚体G蛋白：α, β, γ三亚基组成","小G蛋白：只有一条多肽链构成的单体G蛋","相同点："],"check":{"q":"下列与小G蛋白（如Ras、Rho、Rab）相符的叙述是（　）","o":["A. 结合GDP时具活性，结合GTP时失活","B. 由一条多肽链构成的单体G蛋白，结合GTP时具活性","C. 由α、β、γ三个亚基组成，α亚基水解GTP","D. 本身无GTPase活性，需GEF水解GTP使其失活"],"a":"B","e":"小G蛋白是仅由一条多肽链构成的单体G蛋白，分子量20～30kDa，结合GTP时具活性、结合GDP时失活，本身具内源GTPase活性完成GTP/GDP转换。","oe":["错误：小G蛋白结合GTP才具活性，结合GDP时失活。","正确：小G蛋白为单条多肽链构成的单体，结合GTP时呈活性状态。","错误：α、β、γ三亚基是异三聚体G蛋白的结构特征。","错误：小G蛋白具内源GTPase活性，可自行水解GTP结束信号。"]},"cards":null,"mem":"小G蛋白单体：GTP活、GDP静，自带GTPase","big":"assets/img/ch10/big/p040.jpg"},{"i":40,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Table 15-5 Ras superfamily of monomeric GTPases —— 表15-5 单体GTP酶的Ras超家族\n• Ras (H/K/N-Ras): relay signals from RTKs —— Ras(H/K/N-Ras)：传递RTK信号\n• Rheb: activates mTOR to stimulate growth —— Rheb：激活mTOR促生长\n• Rap1: activated by cAMP-GEF; influences adhesion via integrins —— Rap1：由cAMP-GEF激活，经整合素影响黏附\n• Rho/Rac/Cdc42: relay signals to cytoskeleton —— Rho/Rac/Cdc42：向细胞骨架传递信号\n• ARF1-6: coats on vesicles —— ARF1-6：囊泡外被组装\n• Rab1-60: vesicle traffic —— Rab1-60：囊泡运输\n• Ran: spindle assembly & nuclear transport —— Ran：纺锤体组装与核运输\n【读图讲解】\n表格(Table 15-5)：Ras 超家族单体GTP酶——Ras(H/K/N-Ras，转导RTK信号)、Rheb、Rap1，以及Rho(调控细胞骨架)、ARF(囊泡衣被)、Rab(囊泡运输)、Ran(核转运与纺锤体)。考点：各成员功能；Ras 突变与癌症。","page":41,"level":"掌握","img":"assets/img/ch10/p041.jpg","anim":null,"fig":null,"points":["Family","Somefamily","Somefunctions","members","Ras","H-Ras, K-Ras,","RelaysignalsfromRTKs","N-Ras"],"check":{"q":"Ras超家族单体GTP酶中，主要负责向细胞骨架传递信号的是？","o":["A. Ras","B. Ran","C. ARF1-6","D. Rho/Rac/Cdc42"],"a":"D","e":"Rho/Rac/Cdc42向细胞骨架传递信号；Ras转导RTK信号，Ran参与核转运与纺锤体组装。","oe":["Ras主要传递RTK信号，不参与细胞骨架调控。","Ran参与核转运和纺锤体组装。","ARF1-6参与囊泡衣被组装。","Rho/Rac/Cdc42负责向细胞骨架传递信号，正确。"]},"cards":null,"mem":"Ras传RTK；Rho管骨架；Rab管运输；Ran管核","big":"assets/img/ch10/big/p041.jpg"},{"i":41,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"GTPase 分子开关的调节蛋白","notes":"GTPase 超家族：\n三聚体G蛋白\n单体小 G蛋白\n\n【读图讲解】\n本页讲GTPase分子开关的调节蛋白。GTPase超家族包括三聚体G蛋白和单体小G蛋白。图中循环示意：失活态单体GTPase结合GDP(OFF)；GEF催化GDP换成GTP，使其变为结合GTP的活性态(ON)；而GAP能促进其GTP酶活性，使GTP水解为GDP并释放Pi，从而回到失活态。要点：G蛋白的开与关取决于所结合的是GTP还是GDP，GEF促进活化、GAP促进失活，二者共同调控开关循环，这是信号转导的通用机制。","page":42,"level":"掌握","img":"assets/img/ch10/p042.jpg","anim":null,"fig":null,"points":null,"check":{"q":"在GTPase分子开关循环中，GEF的作用是？","o":["A. 水解cAMP生成AMP","B. 促进GTP水解为GDP，使G蛋白失活","C. 直接磷酸化靶蛋白的丝氨酸残基","D. 催化GDP换成GTP，使G蛋白活化"],"a":"D","e":"GEF(鸟苷交换因子)促进GDP从G蛋白解离并结合GTP，使G蛋白转为活性态。","oe":["水解cAMP生成AMP的是磷酸二酯酶，而非GEF。","促进GTP水解失活的是GAP。","磷酸化底物蛋白是蛋白激酶的功能，不是GEF。","GEF催化GDP换GTP使G蛋白激活，正确。"]},"cards":null,"mem":"GEF换GTP则ON，GAP促水解回GDP即OFF","big":"assets/img/ch10/big/p042.jpg"},{"i":42,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"●GTPase激活蛋白(GTPase activating proteins, GAP):","notes":"加速GTP的水解，缩短应答时间。⎯In an “off” state\n●鸟苷交换因子（guanine nucleotide-exchange factor,\nGEF)：促进GDP从G蛋白上解离，结合GTP (细胞中\nGTP浓度is 10 times greater than GDP)，激活G蛋白。\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页讲G蛋白循环的调控。GTPase激活蛋白（GTPase activating protein, GAP）加速GTP水解，使G蛋白关闭，缩短应答时间；鸟苷交换因子（guanine nucleotide-exchange factor, GEF）促进GDP解离并结合GTP而激活，因胞内GTP约为GDP的10倍。考点：GAP关闭、GEF激活，控制信号时程。","page":43,"level":"掌握","img":"assets/img/ch10/p043.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于GAP与GEF对G蛋白的调节，正确的是？","o":["A. GAP加速GTP水解使其关闭，GEF促进结合GTP使其激活","B. 两者都促进GDP解离使G蛋白激活","C. GAP促进GTP水解使其激活，GEF使其关闭","D. 两者都促进GTP水解使G蛋白失活"],"a":"A","e":"GAP加速GTP水解、缩短应答时间使G蛋白关闭；GEF促进GDP解离并结合GTP而激活G蛋白。","oe":["GAP关闭、GEF激活，表述正确。","GAP不促进GDP解离，而是加速水解。","GAP使G蛋白关闭，而不是使其激活。","GEF是激活因子，不促进水解。"]},"cards":null,"mem":"GAP促水解关闭；GEF换GTP开启(GTP多10倍)","big":"assets/img/ch10/big/p043.jpg"},{"i":43,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"一种肠道内繁殖的细菌在","notes":"肠道产生霍乱毒素，进\n入小肠上皮细胞内\n霍乱毒素具有催化作用\n→ G蛋白核糖化\n抑制α亚基GTPase活性，抑制了GTP的水解\nGTP永久结合在α亚基上，G蛋白处于持续活化状态\n腺苷酸环化酶永久活化，致使小肠上皮细胞的胞质中\ncAMP合成失控，增加100倍以上。\n引起大量的Na+和水外流到肠腔，产生严重腹泻而脱水。","page":44,"level":"掌握","img":"assets/img/ch10/p044.jpg","anim":null,"fig":null,"points":null,"check":{"q":"霍乱毒素引起小肠上皮细胞大量腹泻的分子机制是？","o":["A. 直接抑制腺苷酸环化酶减少cAMP生成","B. 使G蛋白α亚基ADP-核糖化，抑制GTPase，G蛋白持续活化致cAMP剧增","C. 激活GTPase，加速GTP水解使G蛋白失活","D. 激活磷酸二酯酶加速cAMP降解"],"a":"B","e":"霍乱毒素使G蛋白核糖化、抑制α亚基GTPase活性，GTP无法水解而持续活化腺苷酸环化酶，cAMP剧增致Na+和水外流。","oe":["它使腺苷酸环化酶持续活化，非抑制。","核糖化抑制GTPase、持续活化致cAMP剧增，正确。","其作用是抑制而非激活GTPase。","它不激活磷酸二酯酶，反而使cAMP增多。"]},"cards":null,"mem":"霍乱毒素核糖化Gα抑制GTPase→cAMP暴增致腹泻","big":"assets/img/ch10/big/p044.jpg"},{"i":44,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"The mechanisms that shut off a","notes":"signal are as important as the\nmechanisms that turn it on.\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 离子通道偶联的受体介导的信号跨膜传递●信号途径●特点：●受体/离子通道复合体，四次/六次跨膜蛋白●跨膜信号转导无需中间步骤●主要存在于神经细胞或其他可兴奋细胞间的突触信号传递●有选择性：配体的特异性选择和运输离子的选择性\n\n【本页英文讲解】\n本页强调一个基本原则：关闭信号的机制与开启信号的机制同等重要。若信号不能及时终止，会导致应答持续、紊乱甚至癌变。原文仅给出这一命题，未展开具体途径。结合翟中和教材第九章，常见的关闭机制包括：配体降解、受体脱敏与内化、GAP加速GTP水解、第二信使被磷酸二酯酶降解等。考点：信号终止与信号启动同等关键。","page":45,"level":"掌握","img":"assets/img/ch10/p045.jpg","anim":null,"fig":null,"points":null,"check":{"q":"“关闭信号的机制与开启信号的机制同等重要”，下列不属于关闭信号机制的是？","o":["A. 配体降解","B. 受体脱敏与内化","C. 持续合成更多受体以增强信号","D. GAP加速GTP水解"],"a":"C","e":"关闭信号机制包括配体降解、受体脱敏与内化、GAP加速GTP水解、第二信使被磷酸二酯酶降解等；持续合成更多受体增强信号属于放大而非关闭。","oe":["配体降解可终止信号，属关闭机制。","受体脱敏与内化可终止信号，属关闭机制。","增强信号与关闭信号的目的相反。","GAP加速GTP水解使G蛋白失活，属关闭机制。"],"basis":"关闭信号的机制与开启信号的机制同等重要"},"cards":null,"mem":"关闭信号的机制与开启同等重要，失控则应答紊乱","big":"assets/img/ch10/big/p045.jpg"},{"i":45,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"1994年诺贝尔生理学和医学奖","notes":"\"for their discovery of G-proteins and the role of these\nproteins in signal transduction in cells\nAlfred G. Gilman\nMartin Rodbell\nUniversity of Texas      National Institute of\nSouthwestern Medical     Environmental Health Sciences\nCenter at Dallas         Research Triangle Park, NC,\nDallas, TX, USA          USA\nborn 1941                Born 1925, died 1998\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页介绍1994年诺贝尔生理学或医学奖，获奖理由是“发现G蛋白及其在细胞信号转导中的作用”。获奖者为Alfred G. Gilman（得克萨斯大学西南医学中心）和Martin Rodbell（美国国家环境卫生科学研究所）。他们揭示了G蛋白作为信号转导中转分子的功能，为GPCR通路奠定基础。考点：G蛋白的发现是细胞信号转导研究的里程碑。","page":46,"level":"掌握","img":"assets/img/ch10/p046.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于G蛋白在细胞信号转导中的作用，下列叙述正确的是？","o":["A. 作为受体与效应器之间的中转分子传递信号","B. 直接作为转录因子进入细胞核","C. 是催化DNA合成的酶","D. 是细胞骨架的主要组成成分"],"a":"A","e":"G蛋白作为信号转导的中转分子，在受体与效应器之间传递信号；其发现及其在信号转导中的作用是相关诺贝尔奖的获奖成果。","oe":["G蛋白在受体与效应器间中转信号，正确。","G蛋白不进入核内作为转录因子。","G蛋白是信号中转分子，并不是DNA合成酶。","细胞骨架主要由微丝、微管、中间纤维构成。"],"basis":"G蛋白作为信号转导中转分子的功能"},"cards":null,"mem":"1994诺奖：G蛋白发现者Gilman/Rodbell","big":"assets/img/ch10/big/p046.jpg"},{"i":46,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"G-protein","notes":"activation and\ninactivation cycle\n...with GTP and the G\nproteins is activated. The\nsubunits separate.\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页主题为G蛋白（G-protein）的激活与失活循环。原文指出：当G蛋白与GTP结合时即被激活，其亚基随之分离。核心机制：受体激活后促使G蛋白α亚基释放GDP并结合GTP，α亚基与βγ亚基解离，激活的α亚基（或βγ）再去调节下游效应器；随后α亚基固有的GTPase水解GTP，使亚基重新结合、G蛋白失活。考点：G蛋白的分子开关循环。","page":47,"level":"掌握","img":"assets/img/ch10/p047.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于G蛋白的激活与失活循环，下列叙述正确的是？","o":["A. 与GDP结合时被激活","B. 激活时αβγ三亚基始终紧密结合","C. 失活需要水解ATP","D. 与GTP结合时被激活、亚基解离，GTP水解后失活"],"a":"D","e":"当G蛋白与GTP结合时被激活，其亚基随之分离；随后α亚基固有的GTPase水解GTP，使亚基重新结合，G蛋白失活。","oe":["G蛋白与GTP结合时才被激活。","激活时亚基分离，并非始终结合。","失活靠水解GTP，而非ATP。","结合GTP激活并解离，水解GTP后失活，正确。"],"basis":"G蛋白与GTP结合被激活，亚基分离"},"cards":null,"mem":"G蛋白：结合GTP激活亚基分离，水解GDP失活重组","big":"assets/img/ch10/big/p047.jpg"},{"i":47,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"G-蛋白偶联反应具有特异性","notes":"G-蛋白的重要意义：在人类视网膜的圆柱细胞和圆锥细胞中\n发现有特定类型的G-蛋白。\n1. G proteins in our sense organs\ntranslate environmental information\ninto a language that the G proteins in\nthe brain can understand.\n2. G proteins in the nose are activated\nby olfactory stimuli.\n3. G proteins of the tongue register\ntaste.\n1.存在于我们的感受器官中的G-蛋白，能够将环境信息翻译\n成一种可以被大脑中的G-蛋白所理解的一种语言。\n2.鼻子中的G-蛋白在嗅觉的刺激作用下被激活。\n3. 舌头上的G-蛋白能够识别味道。\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 磷脂酰肌醇信号通路● “双信使系统”反应链：胞外信号分子→G-蛋白偶联受体→G-蛋白→","page":48,"level":"理解","img":"assets/img/ch10/p048.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于G蛋白在感受器官中的作用，正确的是？","o":["A. 感受器官中的G蛋白不介导信号转导","B. G蛋白只存在于视网膜，不参与嗅觉和味觉","C. G蛋白只参与视觉，与大脑信息处理无关","D. 鼻子中的G蛋白可被嗅觉刺激激活，舌头上的G蛋白能识别味道"],"a":"D","e":"感受器官中的G蛋白可将环境信息翻译为大脑可理解的语言，鼻中的G蛋白被嗅觉刺激激活，舌上的G蛋白识别味道。","oe":["感受器官G蛋白正是介导信号转导的关键。","G蛋白也参与嗅觉和味觉，不仅限于视网膜。","感受器G蛋白的信息可被大脑G蛋白解读。","鼻与舌的G蛋白分别参与嗅觉和味觉，正确。"]},"cards":null,"mem":"G蛋白具特异性：视网膜感光、鼻嗅觉、舌味觉各有专属","big":"assets/img/ch10/big/p048.jpg"},{"i":48,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"G-蛋白能够对 When in a rage, our adrenals release","notes":"激素产生反应 adrenaline into the blood. When it\nreaches the liver, glucose is formed,\ngiving energy for fight or flight. The\nheart and the blood vessels also become\nprepared.\n当人愤怒的时候，我们的肾上\n腺就会分泌肾上腺素到我们的\n血液中，当肾上腺素到达肝脏\n的时候，激素＋受体→G蛋白，\n信号通路→葡萄糖，为我们搏\n斗或逃跑提供能量。心脏和血\n管也同时进入了紧张状态。\n【中文讲解·对照课本/考点】\n考点：4.1.1 G蛋白与跨膜信号转导 ｜ 教材：第九章 细胞信号转导 · 第一~三节（概述 p156 / 细胞内受体 p164 / G蛋白偶联受体 p165）\n• 离子通道偶联的受体介导的信号跨膜传递●信号途径●特点：●受体/离子通道复合体，四次/六次跨膜蛋白●跨膜信号转导无需中间步骤●主要存在于神经细胞或其他可兴奋细胞间的突触信号传递●有选择性：配体的特异性选择和运输离子的选择性","page":49,"level":"掌握","img":"assets/img/ch10/p049.jpg","anim":null,"fig":null,"points":null,"check":{"q":"人愤怒时肾上腺素到达肝脏，经受体和G蛋白信号通路最终产生的是？","o":["A. 葡萄糖","B. 脂肪酸","C. 氨基酸","D. 尿素"],"a":"A","e":"肾上腺素到达肝脏后，激素＋受体→G蛋白，经信号通路产生葡萄糖，为搏斗或逃跑提供能量，心脏和血管也进入紧张状态。","oe":["肾上腺素经该通路最终产生的是葡萄糖。","该通路主要生成葡萄糖而非脂肪酸。","该通路产生葡萄糖，而不是氨基酸。","尿素是氮代谢产物，与该通路无关。"],"basis":"激素＋受体→G蛋白，信号通路→葡萄糖"},"cards":null,"mem":"激怒→肾上腺素→肝G蛋白通路→葡萄糖，备战能量","big":"assets/img/ch10/big/p049.jpg"},{"i":49,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"●   ●G蛋白偶联受体信号","notes":"通路的效应器\n\n【读图讲解】\n本页为G蛋白偶联受体(GPCR)信号通路的效应器示意。图中配体(Ligand)结合七次跨膜的受体(标①，有NH2端与COOH端)；受体激活G蛋白(标②，α、β、γ三亚基，结合GDP或GTP)；活化的G蛋白再去调节效应器(标③)。右侧文字列出效应器类型：离子通道(K+、Na+等)、腺苷酸环化酶(生成cAMP激活PKA)、磷脂酶C(生成IP3和DAG)。要点：效应器产生胞内第二信使，把胞外信号放大并转换为胞内反应。","page":50,"level":"掌握","img":"assets/img/ch10/p050.jpg","anim":null,"fig":null,"points":["离子通道(K+, Na+等)","腺苷酸环化酶→cAMP-PKA","磷脂酶C→IP3-DAG"],"check":{"q":"关于G蛋白偶联受体信号通路中的效应器，叙述正确的是（　）","o":["A. 受体为七次跨膜蛋白，其激活不依赖配体结合","B. 腺苷酸环化酶生成cAMP，进而激活蛋白激酶A","C. 磷脂酶C生成cAMP和IP3两种第二信使","D. 效应器均通过直接磷酸化靶蛋白来传递信号"],"a":"B","e":"GPCR通路的效应器包括离子通道、腺苷酸环化酶（生成cAMP激活PKA）和磷脂酶C（生成IP3和DAG），它们产生第二信使，把胞外信号放大并转换为胞内反应。","oe":["错误：GPCR为七次跨膜受体，须由配体结合才能被激活。","正确：腺苷酸环化酶催化生成cAMP，cAMP激活蛋白激酶A（PKA）。","错误：磷脂酶C生成IP3和DAG，cAMP由腺苷酸环化酶生成。","错误：效应器产生第二信使放大信号，并非直接磷酸化靶蛋白。"]},"cards":null,"mem":"GPCR效应器:离子通道/AC-cAMP/PLC-IP3","big":"assets/img/ch10/big/p050.jpg"},{"i":50,"sec":"4.1.1   G蛋白与跨膜信号转导","title":"心肌细胞：乙酰胆碱受体GPCR   效应器为","notes":"(一) 激活离子通道\nK+离子通道开放，\n细胞内K+外流\n膜超极化\n减缓心肌收缩频率。","page":51,"level":"掌握","img":"assets/img/ch10/p051.jpg","anim":null,"fig":null,"points":null,"check":{"q":"心肌细胞中乙酰胆碱受体激活后，效应器K+通道开放引起的结果是？","o":["A. 细胞内K+外流，膜超极化，减缓心肌收缩频率","B. K+内流，膜超极化，加快心肌收缩","C. 细胞内K+外流，膜去极化，加快心肌收缩","D. K+内流，膜去极化，减缓心肌收缩"],"a":"A","e":"心肌细胞中K+通道开放致K+外流、膜超极化，从而减缓心肌收缩频率。","oe":["K+外流、超极化、减慢收缩频率，正确。","K+是外流而非内流，结果应减慢收缩。","K+外流导致超极化而非去极化。","K+外流引起超极化，而非内流去极化。"]},"cards":null,"mem":"心肌ACh开K+通道：K+外流、超极化、减慢收缩","big":"assets/img/ch10/big/p051.jpg"}],"mcq":[{"id":"ch10_mcq_2","mod":"4.1.1   G蛋白与跨膜信号转导","modI":8,"q":"下列不具有分子开关作用的蛋白是（            ）。","o":["A．G 蛋白","B．Ras 蛋白","C．接头蛋白","D．Rho 蛋白"],"a":"C","e":"接头蛋白在信号通路中既不能被磷酸化，也不能结合 GTP，它只起偶联作用。而 G 蛋白、Ras 蛋白和 Rho 蛋白分别在不同的信号通路中发挥了分子开关的作用，当其结合 GTP 时处于活化状态，当其结合 GDP 时处于失活状态。Rho 在整联蛋白介导的信号传递中起分 子开关的作用。","kp":"ch10_s8_41","oe":["G蛋白结合GTP活化、结合GDP失活，具分子开关作用。","Ras蛋白结合GTP为活化态、结合GDP为失活态，属分子开关。","接头蛋白只起偶联作用，既不磷酸化也不结合GTP，无开关功能，正确。","Rho蛋白在整联蛋白信号中结合GTP活化，起分子开关作用。"]}],"judge":[{"id":"ch10_judge_3","modI":8,"q":"G 蛋白偶联受体被激活后，使相应的 G 蛋白解离成α、β、γ三个亚基，以进行信号传递。 （      ）","a":"错","e":"G 蛋白三聚体结合 GTP 后解离出成α亚基和βγ亚基复合物，β与γ亚基并未解离。","kp":"ch10_s8_49","oe":["误以为G蛋白三聚体激活后解离成α、β、γ三个亚基。","G蛋白结合GTP后只解离为α亚基与βγ复合物，β与γ并不分开。"]},{"id":"ch10_judge_5","modI":8,"q":"G 蛋白耦联的受体的 N 端结合 G 蛋白，C 端结合胞外信号。( )","a":"错","e":"G 蛋白耦联的受体的 N 端在细胞外侧结合胞外信号，C 端在细胞胞质侧。","kp":"ch10_s8_36","oe":["误将G蛋白偶联受体的N端与C端功能颠倒，故判对。","G蛋白偶联受体N端在细胞外侧结合胞外信号，C端位于胞质侧。"]},{"id":"ch10_judge_11","modI":8,"q":"细胞受体与腺苷酸环化酶同在质膜上，是相互分离的在功能上相关的两种蛋白。（                        ）","a":"对","e":"","kp":"ch10_s8_49","oe":["受体与腺苷酸环化酶是质膜上各自独立、经G蛋白功能偶联的两种蛋白。","误以为二者是同一蛋白或直接结合，其实它们在空间上相互分离。"]}],"fill":[{"id":"ch10_fill_2","modI":8,"q":"由 G 蛋白偶联受体所介导的细胞信号通路主要包括 ______、______和______。","a":"cAMP 信号通路；磷脂酰肌醇信号通路；G 蛋白偶联离子通道的信号通路","kp":"ch10_s8_49","oe":["经Gs/Gi调节腺苷酸环化酶，改变cAMP水平传信号","激活磷脂酶C，水解PIP2产生IP3和DAG","G蛋白直接门控离子通道，快速改变膜电位"]},{"id":"ch10_fill_9","modI":8,"q":"G 蛋白的______结构可以变化，并可以结合______使其成为关闭态。","a":"α亚基；ADP","kp":"ch10_s8_36","oe":["α亚基是G蛋白的活性亚基，可结合并水解鸟苷酸","α亚基结合GDP时为关闭态，结合GTP时被激活"]},{"id":"ch10_fill_13","modI":8,"q":"Gs 的α亚基和 G 的α亚基上都有细胞毒素 ADP 核糖基化位点，但结合的毒素是不同的， 前者结合是______，后者结合的是______。","a":"百日咳毒素；霍乱毒素","kp":"ch10_s8_35","oe":["Gsα是霍乱毒素的ADP核糖基化位点，被修饰后持续活化","Giα是百日咳毒素底物，修饰后不能抑制腺苷酸环化酶"]},{"id":"ch10_fill_16","modI":8,"q":"Ras 蛋白在 RTKs 介导的信号通路中起着关键作用，具有 活性，当结合______时为活 化状态，当结合 时为失活状态。GAP 增强 Ras 的 。","a":"GTPase；GTP；GDP；失活","kp":"ch10_s8_39","oe":["Ras是GTPase，结合GTP活化、结合GDP失活，GAP增强其水解"]}],"short":[{"id":"ch10_short_2","modI":8,"q":"什么是 Ras 蛋白，有何功能？Ras 突变会引起什么样的结果？","a":"（1）Ras 蛋白是 Ras 基因编码产物，是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位 于胞质侧，结合 GTP 时为活化态，结合 GDP 时失活，Ras 蛋白具有分子开关作用，激活磷 酸化级联反应。GAP 可增强 Ras 的 GTP 酶活性。Ras 释放 GDP 结合 GTP，需要鸟苷酸交换 因子参与。 （2）发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于 活化状态，导致恶性细胞转化和肿瘤的发生。","kp":"ch10_s8_34"},{"id":"ch10_short_4","modI":8,"q":"由哪些蛋白调控单体 G 蛋白的活性？","a":"鸟苷酸释放蛋白 Sos 通过促进释放 GDP 使 Ras 结合 GTP 而被激活；GTP 酶活化蛋白 GAP 通过促进 GTP 的水解而使 Ras 失活；GDI 通过抑制 GDP 的释放使 Ras 失活。","kp":"ch10_s8_41"},{"id":"ch10_short_7","modI":8,"q":"简述 NO 的作用机制。","a":"NO 是一种自由基性质的气体，具脂溶性，可快速扩散通过细胞膜，到达邻近靶细胞发 挥作用。 血管内皮细胞和神经细胞是 NO 的生成细胞。以 L-精氨酸为底物，在一氧化氮合酶(NOS) 的作用下，以还原型辅酶Ⅱ(NADPH)为电子供体，等量生成 NO 和 L-瓜氨酸。 可溶性鸟苷酸环化酶(GC)的激活是 NO 发挥作用的主要机制。NO 扩散进入靶细胞与靶蛋白 结合，与鸟苷酸环化酶活性中心的铁离子结合，改变酶的构象，导致酶活性增强和 cGMP 合成增多，cGMP 作为新的信使分子介导蛋白质的磷酸化等过程，发挥多种生物学作用。","kp":"ch10_s8_34"},{"id":"ch10_short_8","modI":8,"q":"类固醇激素受体和离子通道偶联受体所应用的信号机制都很简单，并且信号成分也十分 少。它们能导致起始信号的放大吗？如果是，如何放大起始信号？","a":"就类固醇激素受体来说，类固醇和受体形成一对一的复合物结合到 DNA 上从而激活转 录，因此在配体结合和转录激活之间没有放大作用。放大在随后发生，靶基因转录会产生许 多 mRNA 分子，而每一个 mRNA 分子又翻译产生许多蛋白质分子。 对于离子通道偶联受体，一个离子通道在开放时可通过成千上万个离子，这就是此类信号系 统的放大步骤。","kp":"ch10_s8_49"},{"id":"ch10_short_9","modI":8,"q":"比较植物中的信号传导途径和动物中的信号传导途径。","a":"这两类物种基本上采用十分近似的信号转导途径，除了少数的例外。两者都有胞内 Ca2+、 IP3 和 DAG 的变化，但动物独有环化核苷酸作为第二信使，植物独有水杨酸作为第二信使， 组氨酸激酶也是植物所特有的。","kp":"ch10_s8_39"},{"id":"ch10_short_10","modI":8,"q":"列表比较 PKA 与 PKC 信号转导系统。","a":"PKA 与 PKC 信号转导系统比较如表 9-1 所示： 表 9-1 PKA 与 PKC 信号转导系统的区别 比较项 PKA 信号系统        PKC 信号系统 目 受体  G 蛋白偶联受体          G 蛋白偶联受体 第二信 cAMP              IP3 和 DAG 使 G 蛋白活化，进而活 化磷脂酶 C（PLC）， G 蛋白活化，进而活化腺 第二信                 活化的 PLC 催化 PIP2 苷酸环化酶（AC），活化 使的产                 生成两个第二信使， 的 AC 催化细胞内的 ATP 生                   即 DAG 和 IP3，接着 生成 cAMP IP3 动员胞内钙库 ——内质网释放 Ca2 ＋ 到胞质内，与 CaM 结 合引起系列反应，而 DAG 在 Ca2 协同下激 ＋   活 PKC，再引起相应 的级联反应。这是一 个“双信使系统” 活化的 PKC 可使底物 蛋白磷酸化，激活下 cAMP 与无活性的 PKA 结 游基因调控蛋白。 效应  合释放催化亚基，可以磷 PKC 还可活化 Na ∕H ＋  ＋  酸化下游基因调控蛋白 交换引起细胞内 pH 升高 IP3-DAG 途径通过 IP3 cAMP 途径由环腺苷磷酸 信号的                  的一系列去磷酸化 二酯酶降解 cAMP 为 5＇ 终止                   形成自由的肌醇和 -AMP 而终止 DAG 的水解而终止","kp":"ch10_s8_34"}],"calc":[{"id":"ch10_calc_3","modI":8,"q":"何谓信号转导中的分子开关机制？举例说明。","a":"（1）分子开关机制 在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调 控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分 子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。 另一类是 GTPase 开关蛋白，结合 GTP 活化，结合 GDP 失活。 （2）分子开关机制举例 Ras 蛋白是一个典型的分子开关蛋白，通过其他蛋白质的作用使得 GTP 与其结合而处于激 活状态。一种 GTPase 激活蛋白可促进 Ras 蛋白将结合的 GTP 水解为 GDP，Ras 的工作类 似电路开关。如果 Ras 分子开关失去控制，一直处于激活状态，下游 MAPK 一直处于活跃 状态，使细胞有丝分裂失去控制，从而导致癌变。","kp":"ch10_s8_34"},{"id":"ch10_calc_4","modI":8,"q":"试比较 G 蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","a":"G 蛋白偶联受体是含有 7 个疏水肽段形成的跨膜α螺旋区，其 N 端在细胞外侧，C 端在 细胞胞质侧的受体。G 蛋白偶联受体介导的信号通路：配体-受体结合后，通过与 G 蛋白的 偶联，在细胞内产生第二信使，从而将胞外信号传递到细胞内，影响细胞的行为。G 蛋白偶 联受体介导的信号通路主要包括 cAMP 信号通路和磷脂酰肌醇信号通路。 （1）cAMP 信号通路：细胞外信号（激素，第一信使）与相应 G 蛋白偶联的受体结合，导 致细胞内 cAMP（第二信使）的水平变化而引起细胞反应的信号通路。腺苷酸环化酶（效应 酶）调节胞内 cAMP 的水平，cAMP 被环腺苷酸磷酸二酯酶降解清除。 其反应链为：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白→基因转录。 生物学功能：①调节肝细胞和肌细胞的糖原代谢；②调控真核细胞的基因表达。 （2）磷脂酰肌醇信号通路：通过 G 蛋白偶联受体介导的磷脂酰肌醇信号通路的信号转导， 通过磷酸酯酶 C（效应酶）完成，是双信使系统反应链。此通路的特点是胞外信号被膜受体 接受后，同时产生两个第二信使：IP3 和 DAG，分别激活 IP3-Ca2 和 DAG-PKC 途径，实现 ＋   细胞对外界信号的应答。 生物学功能：①IP3-Ca2 通路中 IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，Ca2 释放进 ＋                             ＋      ＋   入细胞质基质，通过结合钙调蛋白引起细胞反应。 ②DAG-PKC 通路中 DAG 活化并激活与质膜结合的 PKC，PKC 作用于下游底物，参与众多 生理过程，例如细胞分泌、肌肉收缩、细胞增殖、分化等。","kp":"ch10_s8_49"}],"term":[{"id":"ch10_term_2","modI":8,"term":"G 蛋白（trimeric GTP-binding regulatory protein）。","def":"G 蛋白（trimeric GTP-binding regulatory protein）是三聚体 GTP 结合蛋白，由α、β和γ 三个亚基组成，α亚基结合 GDP 处于关闭状态，结合 GTP 处于开启状态。α亚基具有 GTP 酶活性，能催化所结合的 ATP 水解，恢复无活性的三聚体状态。在细胞信号转导过程中起 着分子开关的作用。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_3","modI":8,"term":"GTP 酶活化蛋白（GTPase-acivating prorein，GAP）。","def":"GTP 酶活化蛋白（GTPase-acivating protein，GAP）是一种含有 SH2 结构域，可与被活 化受体的磷酸化酪氨酸残基结合的蛋白，它的功能是增强 Ras 蛋白的 GTP 酶活性，促进 Ras 蛋白从活化状态到失活的转变，从而与信号转导相关。","kps":"","kp":"ch10_s8_42"},{"id":"ch10_term_4","modI":8,"term":"磷酸酶(phosphatase)。","def":"从蛋白质上除去磷酸基团。对于不同的底物蛋白，去磷酸化可使其激活或失活，并终止 细胞内信号转导。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_6","modI":8,"term":"钙调蛋白","def":"钙调蛋白（CaM）是一种真核细胞普遍存在的 Ca2 应答蛋白，含有 4 个结构域，每个 ＋   结构域可结合一个 Ca2 。CaM 本身无活性，它活化靶酶过程可分为两步：Ca2 与 CaM 结合 ＋                       ＋   形成活化态的 Ca2 -CaM 复合体；与靶酶结合将其活化。CaM 活化靶酶是一个受 Ca2 浓度 ＋                             ＋   控制的可逆反应。","kps":"","kp":"ch10_s8_36"}]}],"mcq":[{"id":"ch10_mcq_1","mod":"1.2   细胞内的信号分子","modI":3,"q":"下列有关气体信号分子 NO 的说法，错误的是（          ）。","o":["A．在平滑肌细胞内，L 精氨酸在 NO 合酶催化作用下生成 NO","B．NO 通过增强可溶性鸟苷酸环化酶的活性，发挥作用","C．鸟苷酸环化酶催化 GTP 生成 cGMP，cGMP 介导蛋白质的磷酸化","D．NO 通过舒张血管平滑肌治疗心绞痛，NO 也参与大脑的学习记忆生理过程"],"a":"A","e":"血管内皮细胞和神经细胞是 NO 的生成细胞，NO 再经扩散进入平滑肌细胞发挥作 用。","kp":"ch10_s3_8","oe":["NO由血管内皮细胞和神经细胞产生后扩散入平滑肌，A项来源错误。","NO通过激活可溶性鸟苷酸环化酶发挥作用，该说法正确。","鸟苷酸环化酶催化GTP生成cGMP，经PKG使蛋白磷酸化，正确。","NO舒张血管平滑肌可治心绞痛，也参与学习记忆，说法正确。"]},{"id":"ch10_mcq_2","mod":"4.1.1   G蛋白与跨膜信号转导","modI":8,"q":"下列不具有分子开关作用的蛋白是（            ）。","o":["A．G 蛋白","B．Ras 蛋白","C．接头蛋白","D．Rho 蛋白"],"a":"C","e":"接头蛋白在信号通路中既不能被磷酸化，也不能结合 GTP，它只起偶联作用。而 G 蛋白、Ras 蛋白和 Rho 蛋白分别在不同的信号通路中发挥了分子开关的作用，当其结合 GTP 时处于活化状态，当其结合 GDP 时处于失活状态。Rho 在整联蛋白介导的信号传递中起分 子开关的作用。","kp":"ch10_s8_41","oe":["G蛋白结合GTP活化、结合GDP失活，具分子开关作用。","Ras蛋白结合GTP为活化态、结合GDP为失活态，属分子开关。","接头蛋白只起偶联作用，既不磷酸化也不结合GTP，无开关功能，正确。","Rho蛋白在整联蛋白信号中结合GTP活化，起分子开关作用。"]},{"id":"ch10_mcq_3","mod":"一、信号分子","modI":1,"q":"对于由整联蛋白介导的信号传递，下列哪项说法错误？（            ）","o":["A．胞外配体主要为细胞外基质成分，如纤连蛋白等","B．整联蛋白与胞外配体的相互作用只产生一种胞内信号，即胞内 Ca2+浓度增加","C．当胞外配体与整联蛋白结合，可导致分子开关蛋白 Rho 蛋白激活","D．最终作用是与细胞增殖相关的基因被激活，细胞周期相关蛋白合成"],"a":"B","e":"整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞质基质，肌 醇第二信使的合成，胞内酪氨酸残基的磷酸化等。","kp":"ch10_s1_5","oe":["胞外配体主要是纤连蛋白等细胞外基质成分，说法正确。","整联蛋白可产生Ca2+升高、肌醇第二信使、酪氨酸磷酸化等多种信号，B错。","配体与整联蛋白结合可激活分子开关蛋白Rho，说法正确。","最终激活细胞增殖相关基因并合成细胞周期相关蛋白，说法正确。"]},{"id":"ch10_mcq_4","mod":"二、受体(receptor)","modI":4,"q":"下列关于信号分子的描述中，不正确的是（                ）。","o":["A．神经递质属于亲脂性信号","B．本身不具有酶的活性","C．能传递信息","D．可作为作用底物"],"a":"A","e":"神经递质属于亲水性信号分子。","kp":"ch10_s4_11","oe":["神经递质属亲水性信号分子而非亲脂性，故A错误。","信号分子本身不具酶活性，须与受体结合发挥作用，正确。","信号分子能传递信息，该说法正确。","信号分子可作为作用底物，该说法正确。"]},{"id":"ch10_mcq_5","mod":"1.2   细胞内的信号分子","modI":3,"q":"动物细胞内引起储存 Ca2 释放的第二信使分子是（               ）。[浙江师范大学 2011 研] ＋","o":["A．IP3","B．DAG","C．cAMP","D．cGMP"],"a":"A","e":"IP3（三磷酸肌醇）作为第二信使，从质膜扩散到细胞质，引起 Ca2 从内质网钙库 ＋   中释放出来，导致细胞内 Ca2 浓度瞬间增高，这一作用发生在几乎所有真核细胞中。 ＋","kp":"ch10_s3_8","oe":["IP3作为第二信使扩散至内质网，打开钙通道促使Ca2+释放，正确。","DAG主要激活蛋白激酶C，不直接引起内质网钙库释放。","cAMP激活PKA，与内质网储存钙的释放无直接关系。","cGMP激活PKG，不引起内质网储存钙的释放。"]},{"id":"ch10_mcq_6","mod":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","modI":6,"q":"表皮生长因子（EGF）的穿膜信号转导是通过（                ）实现的。[中山大学 2008 研]","o":["A．活化酪氨酸激酶","B．活化酪氨酸磷酸酶","C．cAMP 调节途径","D．cGMP 调节途径"],"a":"A","e":"EGF 的受体分子是酪氨酸激酶受体，EGF 可以活化酪氨酸激酶受体，使其获得激 酶活性，从而传导信号。","kp":"ch10_s6_22","oe":["EGF受体属酪氨酸激酶受体，结合EGF后激活其激酶活性，正确。","酪氨酸磷酸酶催化去磷酸化，与EGF受体被激活相反。","EGF不通过cAMP调节途径实现穿膜信号转导。","EGF不通过cGMP调节途径实现穿膜信号转导。"]},{"id":"ch10_mcq_7","mod":"绪论 · 概览","modI":0,"q":"霍乱杆菌引起急性腹泻是由于（              ）。","o":["A．G 蛋白持续激活","B．G 蛋白不能被激活","C．受体封闭","D．蛋白激酶 PKC 功能异常","E．蛋白激酶 PKA 异常"],"a":"A","e":"","kp":"ch10_s0_0","oe":["霍乱毒素使Gs的α亚基持续激活，腺苷酸环化酶过度活化，正确。","霍乱毒素是持续激活G蛋白，而非使G蛋白不能被激活。","霍乱弧菌引起腹泻并非受体被封闭所致。","蛋白激酶C功能异常与霍乱弧菌腹泻机制无关。","PKA异常是G蛋白持续激活的下游后果，非霍乱毒素直接作用。"]},{"id":"ch10_amcq_1","mod":"三、NO信号[Ca2+→NO→cGMP→PKG]","modI":5,"q":"关于「NO信号[Ca2+→NO→cGMP→PKG]」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. NO acts only locally because it has a short half-life (about","C. 同一个细胞上不同受体应答不","D. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基"],"a":"B","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13","oe":["同一信号在不同细胞反应不同属信号传递一般特点，非NO信号要点。","NO半衰期短，只能局部发挥作用，符合NO气体信号特征，正确。","同一细胞上不同受体应答不同属受体特异性，与NO信号通路无关。","多肽激素的肽链长度描述属激素分类，与NO信号通路无关。"]},{"id":"ch10_amcq_3","mod":"4.1 G protein-Cou","modI":7,"q":"关于「G protein-Cou」，下列说法正确的是（　）","o":["A. 同一种化学信号在不同细胞中","B. 同一个细胞上不同受体应答不","C. 蛋白质与多肽激素：肽链长度3-几百个氨基酸残基","D. The receptor activation stimulated by light causes a fall rather than a rise in"],"a":"D","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27","oe":["同一信号在不同细胞反应不同属信号传递特点，非G蛋白偶联受体内容。","同一细胞上不同受体应答不同属受体特异性，与本题无关。","多肽激素的肽链长度属信号分子分类，与G蛋白偶联受体无关。","光激活受体使cGMP水平下降而非上升，属GPCR光转导，正确。"]}],"judge":[{"id":"ch10_judge_1","modI":2,"q":"细胞间的通讯就是通过细胞间形成缝隙连接，是细胞质相互沟通而实现的。（              ）","a":"错","e":"间隙连接仅仅是细胞通讯的一种方式，细胞通讯还可以通过分泌化学信号以及细胞 直接接触而实现，而且这两种方式是相对较普遍的。","kp":"ch10_s2_7","oe":["误以为细胞通讯仅有间隙连接一种方式，故判对。","间隙连接只是方式之一，还普遍存在分泌化学信号及细胞直接接触等方式。"]},{"id":"ch10_judge_2","modI":4,"q":"所有的受体都是跨膜蛋白质。（       ）","a":"错","e":"细胞表面的受体多为跨膜糖蛋白，但细胞内的受体如基因调控蛋白等不一定是。","kp":"ch10_s4_11","oe":["误以为受体均为跨膜蛋白，故判对。","胞内受体（如核受体、基因调控蛋白）并非跨膜蛋白，故“所有”说法错误。"]},{"id":"ch10_judge_3","modI":8,"q":"G 蛋白偶联受体被激活后，使相应的 G 蛋白解离成α、β、γ三个亚基，以进行信号传递。 （      ）","a":"错","e":"G 蛋白三聚体结合 GTP 后解离出成α亚基和βγ亚基复合物，β与γ亚基并未解离。","kp":"ch10_s8_49","oe":["误以为G蛋白三聚体激活后解离成α、β、γ三个亚基。","G蛋白结合GTP后只解离为α亚基与βγ复合物，β与γ并不分开。"]},{"id":"ch10_judge_4","modI":6,"q":"激素受体都具有酪氨酸受体结构域。(       )","a":"错","e":"激素受体都具有各自激素的特异结构域。","kp":"ch10_s6_22","oe":["误以为激素受体都含酪氨酸激酶结构域，故判对。","各类激素受体具有各自激素的特异结构域，并非都有酪氨酸受体结构域。"]},{"id":"ch10_judge_5","modI":8,"q":"G 蛋白耦联的受体的 N 端结合 G 蛋白，C 端结合胞外信号。( )","a":"错","e":"G 蛋白耦联的受体的 N 端在细胞外侧结合胞外信号，C 端在细胞胞质侧。","kp":"ch10_s8_36","oe":["误将G蛋白偶联受体的N端与C端功能颠倒，故判对。","G蛋白偶联受体N端在细胞外侧结合胞外信号，C端位于胞质侧。"]},{"id":"ch10_judge_6","modI":5,"q":"来源于质膜的不同信号能通过细胞内不同信号途径间的相互作用而被整合。（         ）","a":"对","e":"","kp":"ch10_s5_18","oe":["胞内不同信号转导途径之间存在交叉对话，可对多种膜来源信号进行整合。","误以为各信号通路彼此孤立，其实通路间相互作用可实现信号整合。"]},{"id":"ch10_judge_7","modI":0,"q":"ras 是一个癌基因。（  ）","a":"错","e":"ras 是一个原癌基因，如果带有使其始终处于活化状态的突变，才会变成癌基因。","kp":"ch10_s0_0","oe":["误以为ras本身就是癌基因，故判对。","ras是原癌基因，只有发生使其持续活化的突变后才变为癌基因。"]},{"id":"ch10_judge_8","modI":0,"q":"乙酰胆碱对一个动物的不同细胞有不同的效应，而且它和不同细胞上的不同受体分子相 结合。（      ）","a":"对","e":"比如，乙酰胆碱通过结合一种 G 蛋白耦联受体而减弱心肌细胞的搏动；通过结合 另一不同的乙酰胆碱受体而刺激骨骼肌细胞的收缩。这种受体是一种配体门控离子通道。","kp":"ch10_s0_3","oe":["乙酰胆碱可结合心肌G蛋白偶联受体减弱搏动，结合骨骼肌配体门控通道刺激收缩。","误以为一种信号分子只对应一种受体和一种效应，忽略受体类型的多样性。"]},{"id":"ch10_judge_9","modI":3,"q":"NO 作为信号分子，它能使细胞内的 cAMP 水平升高。（              ）","a":"错","e":"NO 释放后可以激活其受体，从而刺激生成第二信使 cGMP，cGMP 的作用是通过 cGMP 依赖的蛋白激酶 G 的活化抑制肌动-肌球蛋白复合物信号通路，导致血管平滑肌的舒 张。","kp":"ch10_s3_8","oe":["误以为NO通过升高cAMP发挥作用，故判对。","NO激活受体后生成第二信使cGMP，经蛋白激酶G引起血管平滑肌舒张。"]},{"id":"ch10_judge_10","modI":1,"q":"细胞外信号都是通过细胞表面受体来进行跨膜信号传递的。（                    ）","a":"错","e":"有的脂溶性的信号分子可以跨膜进入细胞与胞内受体结合。","kp":"ch10_s1_5","oe":["误以为所有胞外信号都必须经细胞表面受体传递。","脂溶性信号分子可穿膜进入细胞与胞内受体结合，故“都”的说法错误。"]},{"id":"ch10_judge_11","modI":8,"q":"细胞受体与腺苷酸环化酶同在质膜上，是相互分离的在功能上相关的两种蛋白。（                        ）","a":"对","e":"","kp":"ch10_s8_49","oe":["受体与腺苷酸环化酶是质膜上各自独立、经G蛋白功能偶联的两种蛋白。","误以为二者是同一蛋白或直接结合，其实它们在空间上相互分离。"]},{"id":"ch10_ajudge_2","modI":5,"q":"NO acts only locally because it has a short half-life (about","a":"对","e":"本页要点：NO acts only locally because it has a short half-life (about","kp":"ch10_s5_13","oe":["NO半衰期极短，扩散距离有限，只能作用于局部，故说法正确。","误以为NO可远距离稳定运输，忽视了它极短的半衰期。"]},{"id":"ch10_ajudge_4","modI":7,"q":"The receptor activation stimulated by light causes a fall rather than a rise in","a":"对","e":"本页要点：The receptor activation stimulated by light causes a fall rather than a rise in","kp":"ch10_s7_27","oe":["光激活视紫红质后引起cGMP浓度下降而非升高，从而产生视觉信号。","误以为光激活受体使cGMP升高，方向判断正好相反。"]}],"fill":[{"id":"ch10_fill_1","modI":2,"q":"生物体内的化学信号分子一般可以分为______和______两类。","a":"亲脂性的信号分子；亲水性的信号分子","kp":"ch10_s2_7","oe":["亲脂性信号分子可穿过脂双层，与胞内受体结合","亲水性信号分子不能过膜，需与膜表面受体结合"]},{"id":"ch10_fill_2","modI":8,"q":"由 G 蛋白偶联受体所介导的细胞信号通路主要包括 ______、______和______。","a":"cAMP 信号通路；磷脂酰肌醇信号通路；G 蛋白偶联离子通道的信号通路","kp":"ch10_s8_49","oe":["经Gs/Gi调节腺苷酸环化酶，改变cAMP水平传信号","激活磷脂酶C，水解PIP2产生IP3和DAG","G蛋白直接门控离子通道，快速改变膜电位"]},{"id":"ch10_fill_3","modI":6,"q":"从蛋白结构看，蛋白激酶 A 是由______组成的，而蛋白激酶 C 是______组成。","a":"四个亚基；只有一条肽链","kp":"ch10_s6_22","oe":["PKA由两个调节亚基和两个催化亚基组成四聚体","PKC只由一条肽链构成，含调节区和催化区"]},{"id":"ch10_fill_4","modI":3,"q":"在体内发现的第一个气体信号分子是______。","a":"NO","kp":"ch10_s3_8","oe":["NO是首先发现的气体信号分子，可扩散并舒张血管"]},{"id":"ch10_fill_5","modI":4,"q":"根据信号转导机制和受体蛋白类型的不同，细胞表面受体可以分为______、______ 、 ______。","a":"离子通道耦联受体；G 蛋白耦联受体；酶连受体","kp":"ch10_s4_11","oe":["离子通道耦联受体即配体门控离子通道","G蛋白耦联受体经G蛋白调节效应器传信号","酶连受体胞内具酶活性或招募酶，如受体酪氨酸激酶"]},{"id":"ch10_fill_6","modI":1,"q":"细胞的信号传递是______、______、______、______的______过程。","a":"多通路；多环节；多层次；高度复杂可控","kp":"ch10_s1_5","oe":["同一信号可经多条通路传递，体现多通路性","信号传递需经受体、G蛋白、效应酶等多环节","信号可在膜、胞质、核等多个层次传递整合","该过程高度复杂，又受多种机制精细调控","整体是一个多级放大、可精确调控的信号转导过程"]},{"id":"ch10_fill_7","modI":4,"q":"甾类激素诱导的基因活化分为两个阶段：______和______。","a":"直接活化少数特殊基因转录的初级反应阶段；初级反应的基因产物再活化其他基因产生延迟 的次级反应","kp":"ch10_s4_12","oe":["激素受体复合物先直接激活少数特殊基因转录","初级反应产物再激活其他基因，产生延迟次级反应"]},{"id":"ch10_fill_8","modI":1,"q":"通过黏合斑由整联蛋白介导的信号传递通路有两条：______和______。","a":"由细胞表面到细胞核的信号通路；由细胞表面到细胞质核糖体的信号通路","kp":"ch10_s1_5","oe":["一条由细胞表面经信号传至细胞核，调节基因表达","另一条由细胞表面传至细胞质核糖体，调节蛋白合成"]},{"id":"ch10_fill_9","modI":8,"q":"G 蛋白的______结构可以变化，并可以结合______使其成为关闭态。","a":"α亚基；ADP","kp":"ch10_s8_36","oe":["α亚基是G蛋白的活性亚基，可结合并水解鸟苷酸","α亚基结合GDP时为关闭态，结合GTP时被激活"]},{"id":"ch10_fill_10","modI":6,"q":"受体自磷酸化的结果是激活了受体的______活性，磷酸化的酪氨酸残基可被含有______ 结构域的胞内信号蛋白识别。","a":"酪氨酸蛋白激酶；SH2","kp":"ch10_s6_22","oe":["配体使受体二聚化，自磷酸化激活酪氨酸蛋白激酶","磷酸化酪氨酸残基可被含SH2结构域的蛋白识别"]},{"id":"ch10_fill_11","modI":3,"q":"NO 在胞外极不稳定，被氧化后以______的形式存在于细胞外液中。","a":"硝酸根或亚硝酸根","kp":"ch10_s3_8","oe":["NO不稳定，氧化成硝酸根或亚硝酸根后才稳定存在"]},{"id":"ch10_fill_12","modI":1,"q":"动物细胞间通讯连接的主要方式是______，植物细胞的通讯连接方式是通过______。","a":"间隙连接；胞间连丝","kp":"ch10_s1_5","oe":["动物细胞间以间隙连接沟通，允许小分子直接通过","植物细胞间通过胞间连丝相连，是其特有连接"]},{"id":"ch10_fill_13","modI":8,"q":"Gs 的α亚基和 G 的α亚基上都有细胞毒素 ADP 核糖基化位点，但结合的毒素是不同的， 前者结合是______，后者结合的是______。","a":"百日咳毒素；霍乱毒素","kp":"ch10_s8_35","oe":["Gsα是霍乱毒素的ADP核糖基化位点，被修饰后持续活化","Giα是百日咳毒素底物，修饰后不能抑制腺苷酸环化酶"]},{"id":"ch10_fill_14","modI":0,"q":"自身免疫性受体病是由于______。","a":"机体产生抗自身受体的抗体，与受体结合后使受体失去功能或改变作用方向查看答 案","kp":"ch10_s0_0","oe":["机体产生抗自身受体的抗体，结合后使受体失活或改变作用"]},{"id":"ch10_fill_15","modI":6,"q":"细胞内的受体具有同源性，一般由 800 个氨基酸组成，分为三个结构域，即______，______ 和______。","a":"C 端与信号分子结合部位；中部与 DNA 结合部位；N 端激活基因转录部位查看答 案","kp":"ch10_s6_22","oe":["C端为与信号分子（激素）结合的部位","中间为与DNA结合的结构域，常含锌指结构","N端为激活基因转录的结构域，调节表达"]},{"id":"ch10_fill_16","modI":8,"q":"Ras 蛋白在 RTKs 介导的信号通路中起着关键作用，具有 活性，当结合______时为活 化状态，当结合 时为失活状态。GAP 增强 Ras 的 。[南开大学 2007 研]","a":"GTPase；GTP；GDP；失活","kp":"ch10_s8_39","oe":["Ras是GTPase，结合GTP活化、结合GDP失活，GAP增强其水解"]},{"id":"ch10_fill_17","modI":2,"q":"细胞分泌化学信号的作用方式可分为：________、________、________；通过化学突触 传递神经信号。[郑州大学 2006 研]","a":"自分泌；内分泌；旁分泌","kp":"ch10_s2_6","oe":["自分泌指信号分子作用于自身或同类细胞","内分泌指信号经血液运输作用于远处靶细胞","旁分泌指信号分子作用于邻近的靶细胞"]}],"term":[{"id":"ch10_term_1","modI":2,"term":"细胞通讯（cell communication）。","def":"细胞通讯（cell communication）是指一个细胞发出的信号通过某种介质传递到另一细胞， 并使其产生相应的反应。细胞通讯在多细胞生物体的发生和组织的构建，协调细胞的功能， 控制细胞的生长和分裂中发挥了重要的作用。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_2","modI":8,"term":"G 蛋白（trimeric GTP-binding regulatory protein）。","def":"G 蛋白（trimeric GTP-binding regulatory protein）是三聚体 GTP 结合蛋白，由α、β和γ 三个亚基组成，α亚基结合 GDP 处于关闭状态，结合 GTP 处于开启状态。α亚基具有 GTP 酶活性，能催化所结合的 ATP 水解，恢复无活性的三聚体状态。在细胞信号转导过程中起 着分子开关的作用。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_3","modI":8,"term":"GTP 酶活化蛋白（GTPase-acivating prorein，GAP）。","def":"GTP 酶活化蛋白（GTPase-acivating protein，GAP）是一种含有 SH2 结构域，可与被活 化受体的磷酸化酪氨酸残基结合的蛋白，它的功能是增强 Ras 蛋白的 GTP 酶活性，促进 Ras 蛋白从活化状态到失活的转变，从而与信号转导相关。","kps":"","kp":"ch10_s8_42"},{"id":"ch10_term_4","modI":8,"term":"磷酸酶(phosphatase)。","def":"从蛋白质上除去磷酸基团。对于不同的底物蛋白，去磷酸化可使其激活或失活，并终止 细胞内信号转导。","kps":"","kp":"ch10_s8_34"},{"id":"ch10_term_5","modI":6,"term":"离子通道耦联受体（ion-channel-coupled receptor）。","def":"离子通道耦联受体是由多亚基组成的受体一离子通道复合体，本身既有结合位点，又是 离子通道，其跨膜信号转导无需中间步骤。","kps":"","kp":"ch10_s6_22"},{"id":"ch10_term_6","modI":8,"term":"钙调蛋白（Calmodulin (CaM)）","def":"钙调蛋白（CaM）是一种真核细胞普遍存在的 Ca2 应答蛋白，含有 4 个结构域，每个 ＋   结构域可结合一个 Ca2 。CaM 本身无活性，它活化靶酶过程可分为两步：Ca2 与 CaM 结合 ＋                       ＋   形成活化态的 Ca2 -CaM 复合体；与靶酶结合将其活化。CaM 活化靶酶是一个受 Ca2 浓度 ＋                             ＋   控制的可逆反应。","kps":"","kp":"ch10_s8_36"},{"id":"ch10_term_7","modI":2,"term":"signal transduction（Signal transduction）","def":"signal transduction 的中文名称是信号转导。信号转导是指一个细胞发出的信息，可通过 介质传递到另一个细胞并产生相应的反应的过程，是一种复杂的系统通讯活动及协助细胞的 活动。信号转导可以实现细胞间通讯，是协调多细胞生物细胞间功能、控制细胞的生长和分 裂、组织发生与形态建成所必需的关键过程。","kps":"","kp":"ch10_s2_7"},{"id":"ch10_term_8","modI":6,"term":"RTK（Receptor tyrosine kinase (RTK)）","def":"RTK 的中文名称是受体酪氨酸激酶。受体酪氨酸激酶是一类酶联受体，既是受体，又 具有酶功能。当 RTK 与其配体结合后，两个受体在膜上二聚化，两个受体分子具有微弱的 蛋白激酶活性，当它们相互靠近后通过相互磷酸化的机制将二者自身的蛋白激酶活化，使下 游蛋白的酪氨酸残基磷酸化，从而实现信号转导的功能。所有的受体酪氨酸激酶都由三个部 分组成：具配体结合位点的胞外结构域、单次跨膜的疏水α螺旋区、具酪氨酸蛋白激酶活性 的胞内结构域。","kps":"","kp":"ch10_s6_22"},{"id":"ch10_term_9","modI":2,"term":"细胞通讯（Cell communication）","def":"细胞通讯是指一个细胞发出的信息通过介质（又称配体）传递到另一个靶细胞并与其相 应的受体相互作用，然后通过细胞信号转导产生靶细胞内一系列生理生化变化，最终表现为 靶细胞整体的生物学效应的过程。","kps":"","kp":"ch10_s2_7"}],"short":[{"id":"ch10_short_1","modI":0,"q":"简述细胞通讯的方式。","a":"（1）细胞通过分泌化学信号进行的通讯，包括内分泌、旁分泌、自分泌和化学突触等。 （2）细胞间接触性依赖的通讯：细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白。 （3）间隙连接：使细胞质相互沟通，实现代谢偶联或电偶联。","kp":"ch10_s0_1","kps":"①分泌化学信号：内分泌、旁分泌、自分泌、化学突触；②接触依赖通讯：信号分子与受体为跨膜蛋白；③间隙连接：代谢偶联或电偶联"},{"id":"ch10_short_2","modI":8,"q":"什么是 Ras 蛋白，有何功能？Ras 突变会引起什么样的结果？","a":"（1）Ras 蛋白是 Ras 基因编码产物，是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位 于胞质侧，结合 GTP 时为活化态，结合 GDP 时失活，Ras 蛋白具有分子开关作用，激活磷 酸化级联反应。GAP 可增强 Ras 的 GTP 酶活性。Ras 释放 GDP 结合 GTP，需要鸟苷酸交换 因子参与。 （2）发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于 活化状态，导致恶性细胞转化和肿瘤的发生。","kp":"ch10_s8_34","kps":"Ras为小GTP结合蛋白，具GTP酶活性，结合GTP活化、GDP失活；突变Ras不能水解GTP，锁定活化态致肿瘤"},{"id":"ch10_short_3","modI":0,"q":"蛋白质获取磷酸基团在细胞信号系统传导中的作用如何？","a":"（1）细胞内的信号蛋白主要分为两大类：一类在蛋白激酶的作用下磷酸化，共价结合 ATP 所提供的磷酸基团；另一类则在信号作用下结合 GTP，通常以 GTP 取代 GDP。 （2）这两种胞内信号蛋白的共同特征是，在信号达到时通过获得一个或几个磷酸集团而被 激活，而在信号减弱时能去除这些集团，从而失去活性。在信号中继网中，某个信号蛋白磷 酸化通常造成下游的蛋白依次发生磷酸化，形成磷酸化级联反应。","kp":"ch10_s0_0","kps":"信号蛋白：蛋白激酶催化磷酸化、结合ATP磷酸基团；另一类结合GTP。特征：磷酸化激活、去磷酸失活，磷酸化传递成级联反应"},{"id":"ch10_short_4","modI":8,"q":"由哪些蛋白调控单体 G 蛋白的活性？","a":"鸟苷酸释放蛋白 Sos 通过促进释放 GDP 使 Ras 结合 GTP 而被激活；GTP 酶活化蛋白 GAP 通过促进 GTP 的水解而使 Ras 失活；GDI 通过抑制 GDP 的释放使 Ras 失活。","kp":"ch10_s8_41","kps":"Sos促GDP释放使Ras结合GTP激活；GAP促GTP水解使Ras失活；GDI抑制GDP释放使Ras失活"},{"id":"ch10_short_5","modI":4,"q":"霍乱毒素通过什么机制引起腹泻的？","a":"霍乱毒素是一种作用于 G 蛋白的毒素，它可将 NAD+上的 ADP-核糖基团共价结合到 Gs 的α亚基上，使蛋白核糖化，这样抑制了α亚基的 GTP 酶活性，从而抑制了 GTP 的水解， 使 Gs 一直处于激活状态。结果使腺苷酸环化酶处于永久活性状态，cAMP 的形成无法终止， 引起 Na+与水分子不断分泌到肠腔，而导致严重腹泻。","kp":"ch10_s4_11","kps":"霍乱毒素使Gs的α亚基ADP-核糖化，抑制其GTP酶活性，Gs持续激活；腺苷酸环化酶永久活化、cAMP无法终止，致腹泻"},{"id":"ch10_short_6","modI":0,"q":"简述日咳产生的细胞学原因。","a":"百日咳毒素催化 Gi 的α亚基 ADP－核糖基化，降低了 GTP 与 Gi 的α亚基的结合水平， 使 Gi 的α亚基不能活化，从而阻断了 Ri 受体对腺苷酸环化酶的抑制作用。","kp":"ch10_s0_0","kps":"百日咳毒素催化Gi的α亚基ADP-核糖基化，Gi的α亚基不能活化，阻断Ri受体对腺苷酸环化酶的抑制"},{"id":"ch10_short_7","modI":8,"q":"简述 NO 的作用机制。","a":"NO 是一种自由基性质的气体，具脂溶性，可快速扩散通过细胞膜，到达邻近靶细胞发 挥作用。 血管内皮细胞和神经细胞是 NO 的生成细胞。以 L-精氨酸为底物，在一氧化氮合酶(NOS) 的作用下，以还原型辅酶Ⅱ(NADPH)为电子供体，等量生成 NO 和 L-瓜氨酸。 可溶性鸟苷酸环化酶(GC)的激活是 NO 发挥作用的主要机制。NO 扩散进入靶细胞与靶蛋白 结合，与鸟苷酸环化酶活性中心的铁离子结合，改变酶的构象，导致酶活性增强和 cGMP 合成增多，cGMP 作为新的信使分子介导蛋白质的磷酸化等过程，发挥多种生物学作用。","kp":"ch10_s8_34","kps":"NO为脂溶性气体，扩散过膜；NOS催化L-精氨酸、NADPH生成NO；NO与鸟苷酸环化酶铁离子结合、酶活化，cGMP增多"},{"id":"ch10_short_8","modI":8,"q":"类固醇激素受体和离子通道偶联受体所应用的信号机制都很简单，并且信号成分也十分 少。它们能导致起始信号的放大吗？如果是，如何放大起始信号？","a":"就类固醇激素受体来说，类固醇和受体形成一对一的复合物结合到 DNA 上从而激活转 录，因此在配体结合和转录激活之间没有放大作用。放大在随后发生，靶基因转录会产生许 多 mRNA 分子，而每一个 mRNA 分子又翻译产生许多蛋白质分子。 对于离子通道偶联受体，一个离子通道在开放时可通过成千上万个离子，这就是此类信号系 统的放大步骤。","kp":"ch10_s8_49","kps":"类固醇激素受体：结合DNA激活转录无放大，放大在后，靶基因转录多mRNA、翻译多蛋白；离子通道受体：通道开放通过上万离子"},{"id":"ch10_short_9","modI":8,"q":"比较植物中的信号传导途径和动物中的信号传导途径。","a":"这两类物种基本上采用十分近似的信号转导途径，除了少数的例外。两者都有胞内 Ca2+、 IP3 和 DAG 的变化，但动物独有环化核苷酸作为第二信使，植物独有水杨酸作为第二信使， 组氨酸激酶也是植物所特有的。","kp":"ch10_s8_39","kps":"途径基本近似；均有Ca2+、IP3、DAG变化；动物独有环化核苷酸为第二信使；植物独有水杨酸为第二信使及组氨酸激酶"},{"id":"ch10_short_10","modI":8,"q":"列表比较 PKA 与 PKC 信号转导系统。","a":"PKA 与 PKC 信号转导系统比较如表 9-1 所示： 表 9-1 PKA 与 PKC 信号转导系统的区别 比较项 PKA 信号系统        PKC 信号系统 目 受体  G 蛋白偶联受体          G 蛋白偶联受体 第二信 cAMP              IP3 和 DAG 使 G 蛋白活化，进而活 化磷脂酶 C（PLC）， G 蛋白活化，进而活化腺 第二信                 活化的 PLC 催化 PIP2 苷酸环化酶（AC），活化 使的产                 生成两个第二信使， 的 AC 催化细胞内的 ATP 生                   即 DAG 和 IP3，接着 生成 cAMP IP3 动员胞内钙库 ——内质网释放 Ca2 ＋ 到胞质内，与 CaM 结 合引起系列反应，而 DAG 在 Ca2 协同下激 ＋   活 PKC，再引起相应 的级联反应。这是一 个“双信使系统” 活化的 PKC 可使底物 蛋白磷酸化，激活下 cAMP 与无活性的 PKA 结 游基因调控蛋白。 效应  合释放催化亚基，可以磷 PKC 还可活化 Na ∕H ＋  ＋  酸化下游基因调控蛋白 交换引起细胞内 pH 升高 IP3-DAG 途径通过 IP3 cAMP 途径由环腺苷磷酸 信号的                  的一系列去磷酸化 二酯酶降解 cAMP 为 5＇ 终止                   形成自由的肌醇和 -AMP 而终止 DAG 的水解而终止","kp":"ch10_s8_34","kps":"PKA：cAMP，G蛋白→腺苷酸环化酶→cAMP→PKA；PKC：IP3/DAG，G蛋白→磷脂酶C→DAG→PKC"},{"id":"ch10_short_11","modI":1,"q":"举例说明 G 蛋白偶联细胞表面受体介导信号跨膜转导的通路及其作用机制。 相关试题：G-蛋白偶联系统信号转导的主要特点是什么？","a":"G 蛋白偶联细胞表面受体介导信号跨膜转导的通路主要有两条：cAMP 信号通路和磷脂 酰肌醇信号通路。同时，在磷脂酰肌醇信号通路中，存在一个“双信使系统”，因而 G 蛋白 偶联受体信号转导形成一个复杂的网络结构。 （1）cAMP 信号通路 ①信号通路：激素→G 蛋白偶联受体→G 蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白。 ②作用机制：cAMP 活化 PKA，PKA 催化亚基转位进入细胞核，使基因调控蛋白（cAMP 应答元件结合蛋白，CREB）磷酸化，磷酸化的基因调控蛋白 CREB 与核内 CREB 结合蛋白 （CBP）特异结合形成复合物，复合物与靶基因调控序列结合，激活靶基因的表达。 （2）磷脂酰肌醇信号通路“双信使系统” 胞外信号分子与 GPCR 结合，活化 G 蛋白，进而激活磷脂酶 C（PLC），催化 PIP2 水解生 成 IP3 和 DAG 两个第二信使。 ①IP3-Ca2 信号通路 ＋   a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→IP3→胞内 Ca2 浓度升高→Ca2 结合蛋白（CaM）→钙调蛋白依赖激酶→基因调控蛋白。 ＋             ＋   b．作用机制：IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，引起 Ca2 释放并进入细胞质 ＋         ＋   基质，通过结合钙调蛋白引起细胞反应，如引起肌细胞的收缩。 ②DAG-PKC 信号通路 a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→DAG→激活 PKC→蛋白磷酸化或者促 Na ／H 交换使胞内 pH 变化等。 ＋   ＋   b．作用机制：IP3-Ca2 信号通路释放的 Ca2 将细胞质中游离的蛋白激酶 C（PKC）募集到细 ＋           ＋   胞质膜上，结合在质膜上的第二信使 DAG 活化并激活与质膜结合的 PKC，接着 PKC 作用 于下游底物，引起多种细胞反应，如细胞分泌、肌肉收缩、细胞增殖分化等。","kp":"ch10_s1_5","kps":"两条通路：cAMP、磷脂酰肌醇。cAMP：激素→GPCR→G蛋白→腺苷酸环化酶→cAMP→PKA；PKA使CREB磷酸化"},{"id":"ch10_short_12","modI":0,"q":"细胞信号转导的复杂性主要表现在哪几个方面？","a":"细胞信号转导的复杂性主要表现在以下方面： （1）多途径多层次的细胞信号传递通路具有收敛性和发散性的特点。每种受体都能识别与 结合各自的特异性配体，来自各种非相关受体的信号，可以在细胞内收敛激活一个共同的效 应器（如 Ras 或 Raf 蛋白）的信号。另外，来自相同配体的信号（如表皮生长因子或胰岛素）， 又可发散激活各种不同的效应器，导致多样化的细胞应答。 （2）细胞信号转导既具有专一性，又具有作用的相似性。配体与受体在结构上的互补是细 胞信号转导具有专一性的重要基础；同时细胞信号转导又有相似的作用机制，因此细胞面临 各种纷杂的胞外信号时，只通过少数几种第二信使便可介导多种多样的细胞应答反应。如不 同细胞因子与受体组成的复合体中往往含有相同亚基，由此诱导相似的信号转导；一种配体 与受体结合可诱发多种信号转导途径，如在配体作用下，RTK 不同位点的 Tyr 残基自磷酸 化，可分别结合不同信号蛋白或接头蛋白，引出不同的信号通路；G 蛋白与受体偶联可介导 腺苷酸环化酶和 PLC 等，分别引出 cAMP 和 IP3-DAG 两种信号通路。 （3）信号转导过程有放大作用，但这种放大作用又必须受到适度调控，这表现为信号放大 作用和信号终止作用的并存。正常生理条件下，激素配体本身对受体数目的影响，信号分子 的磷酸化与去磷酸化，G 蛋白的 GTP 或 GDP 结合状态可逆变化，Ca2 的释放与回收等，都 ＋   可使信号转导精确而适度，不是持续的而是对胞外信号瞬间的反应，一旦破坏了这种正常的 正负反馈机制，细胞就会病变。 （4）当细胞长期暴露于某种形式的刺激下时，细胞对刺激的反应会降低，即细胞适应现象。 细胞适应的方式有：逐渐降低表面受体数目；快速钝化受体，降低受体配体的亲和力；在受 体已经被激活的情况下，其下游信号蛋白发生变化，使信号通路受阻。这种适应性是通过负 反馈条件实现的。 （5）细胞信号转导的复杂性还表现在它的非线性方面。细胞无时无刻不在复杂环境的信号 轰炸之下，这些信号分别协调启动细胞各种信号途径，最后做出合理的应答反应。因此，细 胞各种不同信号通路不是彼此孤立的，其最重要的特征就是形成一个复杂的信号网络系统， 它具有高度的非线性特点，被称为交叉对话。这种机制使信号经网络系统分析、整合后最终 表现为特定的生理功能，从而使细胞具有一定自我修复机制和补偿能力。","kp":"ch10_s0_0","kps":"①收敛性（不同受体汇聚效应器）、发散性（同配体激活不同效应器）；②专一（配体受体互补）与相似（少数第二信使介导多样应答）"},{"id":"ch10_short_13","modI":0,"q":"试述参与细胞信号转导的细胞膜受体的种类与特点。","a":"参与细胞信号转导的细胞膜受体的种类与特点如下： （1）酶联受体 受体结构域具有潜在酶活性或者受体本身不具有酶活性但其胞内段与酶联系，在受到刺激时 能激活下游靶酶。如生长因子类受体，这类受体存在于细胞膜上，受体本身具有酪氨酸激酶 的活性，能直接催化底物的磷酸化。 （2）离子通道受体 某些神经递质的受体，它们也存在于细胞膜上，其本身是一种或几种离子的离子通道，配体 与这类受体结合后，改变了受体的空间构象，使离子通道开放或关闭，控制着离子进出细胞。 （3）G 蛋白偶联的受体 普遍存在于各类真核细胞表面，通过与细胞内 G 蛋白偶联，受到刺激时改变 G 蛋白的构象， 从而激活下游靶蛋白活性，引起应答。如神经递质、激素、肽类和胺类配体等的受体。","kp":"ch10_s0_0","kps":"①酶联受体：胞内域具酶活性或与酶相连；②离子通道受体：配体结合使通道开闭；③G蛋白偶联受体：经G蛋白激活下游靶蛋白"},{"id":"ch10_short_14","modI":4,"q":"概述细胞表面受体的分类（配体、受体、信号转导机制）。","a":"受体是指一类能够识别和选择性结合某种配体（信号分子）的大分子，主要是糖蛋白和 糖脂。细胞表面受体主要识别和结合亲水性信号分子，包括分泌型信号分子（如神经递质、 多肽类激素、生长因子等）或膜结合型信号分子（细胞表面抗原、细胞表面黏着分子等）。 根据信号转导机制和受体蛋白类型的不同，细胞表面受体分为： （1）离子通道偶联受体，受体本身既有信号（配体）结合位点，又是离子通道。 （2）G 蛋白偶联受体（GPCR），是细胞表面受体中最大家族。 （3）酶联受体，其中一种受体胞内结构域具有潜在酶活性，另一类是受体本身不具酶活性， 而是受体胞内段与酶相联系。","kp":"ch10_s4_11","kps":"受体为膜上识别亲水信号的糖蛋白/糖脂；三类：①离子通道受体；②G蛋白偶联受体GPCR；③酶联受体（胞内域具酶活性）"},{"id":"ch10_short_y1","modI":4,"q":"比较cAMP信号通路与磷脂酰肌醇信号通路在受体、效应酶、第二信使和主要功能上的差异。","a":"①受体：二者均为G蛋白偶联受体（7次跨膜）。②效应酶：cAMP通路的效应酶是腺苷酸环化酶（AC）；磷脂酰肌醇通路的效应酶是磷脂酶C（PLC）。③第二信使：cAMP通路的第二信使是cAMP；磷脂酰肌醇通路的第二信使是IP3和DAG（并涉及Ca2+）。④主要功能：cAMP通路经PKA磷酸化靶蛋白，调节糖原代谢、基因表达等；磷脂酰肌醇通路经IP3促Ca2+释放、DAG激活PKC，调节细胞分泌、收缩、增殖和基因表达等。","kps":"受体:均GPCR;效应酶:AC vs PLC;第二信使:cAMP vs IP3/DAG(+Ca2+);功能:PKA调节代谢/基因 vs PKC/Ca2+调节分泌增殖","type":"比较型"}],"calc":[{"id":"ch10_calc_1","modI":6,"q":"试述细胞接受化学信号后调节基因表达的途径？","a":"（1）细胞内受体的本质是激素激活的基因调控蛋白，当细胞内受体接受甾类激素后， 会引起受体构象变化，使得结合在受体上的抑制蛋白复合物解离，暴露出受体与 DNA 结合 的位点，受体被激活，激活的受体通过结合于特异 DNA 序列将调节基因的表达。（20 由细 胞外受体接受水溶性的激素信号，通过信号转导在细胞内会产生第二信号分子 IP3／DG 和 第三信使 Ca 离子。蛋白激酶 C(PKC)在 DG 和 Ca2+浓度的升高条件下，激活细胞内的靶酶 蛋白激酶 C，PKC 激活时成为膜结合的酶，属于多功能丝氨酸、苏氨酸激酶，可作用于胞 质中的某些酶，参与生化反应的调节；也可作用于细胞核的转录因子，参与基因表达的调控。","kp":"ch10_s6_23","kps":"胞内受体(甾类激素)→构象变化→结合DNA调控基因;胞外受体→第二信使IP3/DG、Ca2+→PKC→作用酶或转录因子"},{"id":"ch10_calc_2","modI":7,"q":"从受体的角度解读家族性高胆固醇血症的发病机理。","a":"在肝细胞及肝外组织的细胞膜表面广泛存在着低密度脂蛋白(LDL)受体，它能与血浆中 富含胆固醇的 LDL 颗粒相结合，并经受体介导的内吞作用进入细胞。在细胞内受体与 LDL 解离，再回到细胞膜，而 LDL 则在溶酶体内降解并释放出胆固醇，供给细胞代谢需要并降 低血浆胆固醇含量。如果由于各种原因(如受体合成受损；受体发生细胞内转运障碍；受体 与配体结合力降低；受体内吞缺陷；受体再循环障碍)导致受体数量减少或功能异常，其对 血浆 LDL 的清除能力降低，患者出生后血浆 LDL 含量即高于正常，发生动脉粥样硬化的危 险也显著升高。","kp":"ch10_s7_27","kps":"LDL受体介导内吞;受体减少/功能异常(合成/转运/结合/内吞/再循环缺陷)→LDL清除下降→动脉粥样硬化"},{"id":"ch10_calc_3","modI":8,"q":"何谓信号转导中的分子开关机制？举例说明。","a":"（1）分子开关机制 在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调 控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分 子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。 另一类是 GTPase 开关蛋白，结合 GTP 活化，结合 GDP 失活。 （2）分子开关机制举例 Ras 蛋白是一个典型的分子开关蛋白，通过其他蛋白质的作用使得 GTP 与其结合而处于激 活状态。一种 GTPase 激活蛋白可促进 Ras 蛋白将结合的 GTP 水解为 GDP，Ras 的工作类 似电路开关。如果 Ras 分子开关失去控制，一直处于激活状态，下游 MAPK 一直处于活跃 状态，使细胞有丝分裂失去控制，从而导致癌变。","kp":"ch10_s8_34","kps":"分子开关:磷酸化/去磷酸化(激酶/磷酸酶);GTPase(GTP活/GDP失活);例Ras-MAPK失控→癌变"},{"id":"ch10_calc_4","modI":8,"q":"试比较 G 蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","a":"G 蛋白偶联受体是含有 7 个疏水肽段形成的跨膜α螺旋区，其 N 端在细胞外侧，C 端在 细胞胞质侧的受体。G 蛋白偶联受体介导的信号通路：配体-受体结合后，通过与 G 蛋白的 偶联，在细胞内产生第二信使，从而将胞外信号传递到细胞内，影响细胞的行为。G 蛋白偶 联受体介导的信号通路主要包括 cAMP 信号通路和磷脂酰肌醇信号通路。 （1）cAMP 信号通路：细胞外信号（激素，第一信使）与相应 G 蛋白偶联的受体结合，导 致细胞内 cAMP（第二信使）的水平变化而引起细胞反应的信号通路。腺苷酸环化酶（效应 酶）调节胞内 cAMP 的水平，cAMP 被环腺苷酸磷酸二酯酶降解清除。 其反应链为：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白→基因转录。 生物学功能：①调节肝细胞和肌细胞的糖原代谢；②调控真核细胞的基因表达。 （2）磷脂酰肌醇信号通路：通过 G 蛋白偶联受体介导的磷脂酰肌醇信号通路的信号转导， 通过磷酸酯酶 C（效应酶）完成，是双信使系统反应链。此通路的特点是胞外信号被膜受体 接受后，同时产生两个第二信使：IP3 和 DAG，分别激活 IP3-Ca2 和 DAG-PKC 途径，实现 ＋   细胞对外界信号的应答。 生物学功能：①IP3-Ca2 通路中 IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，Ca2 释放进 ＋                             ＋      ＋   入细胞质基质，通过结合钙调蛋白引起细胞反应。 ②DAG-PKC 通路中 DAG 活化并激活与质膜结合的 PKC，PKC 作用于下游底物，参与众多 生理过程，例如细胞分泌、肌肉收缩、细胞增殖、分化等。","kp":"ch10_s8_49","kps":"GPCR(7次跨膜);cAMP通路(AC-cAMP-PKA)与磷脂酰肌醇通路(PLC-IP3/DAG-Ca2+/PKC);效应酶、第二信使、功能"},{"id":"ch10_calc_5","modI":4,"q":"图解细胞表面受体调节基因表达的信号通路。","a":"相关图解参见 9.1 复习笔记中图 9-1-2 至图 9-1-9。 （1）G 蛋白偶联受体介导的信号通路 ①激活离子通道的 G 蛋白偶联受体介导的信号通路 a．心肌细胞上 M 乙酰胆碱受体激活的 G 蛋白开启 K 通道。 ＋   b．Gt 蛋白偶联的光受体的活化诱发 cGMP 门控阳离子通道的关闭。 ②激活或抑制腺苷酸环化酶的 G 蛋白偶联受体 ③激活磷脂酶 C，以 IP3 和 DAG 作为双信使的 G 蛋白偶联受体介导的信号通路 （2）酶联受体介导的信号转导 ①受体酪氨酸激酶及 RTK-Ras 蛋白信号通路 ②PI3K-PKB（Akt）信号通路 ③TGF-β受体及其 TGF-β-Smad 信号通路 ④细胞生长因子受体与 JAK-STAT 信号通路 （3）其他细胞表面受体介导的信号通路 ①Wnt 受体和 Hedgehog 受体介导的信号通路 ②NF-κB 和 Notch 信号通路","kp":"ch10_s4_11","kps":"G蛋白偶联受体通路;酶联受体(RTK-Ras、PI3K-Akt、TGF-β-Smad、JAK-STAT);Wnt/Hh、NF-κB、Notch"},{"id":"ch10_calc_y2","modI":7,"q":"说明G蛋白的活化-失活循环及其作为分子开关的作用机制。","a":"①静息时G蛋白由α、β、γ三亚基组成，α亚基结合GDP，处于失活态。②配体与G蛋白偶联受体结合，受体活化并作为GEF促使α亚基释放GDP、结合GTP。③α-GTP与βγ解离，活化的α-GTP（或βγ）去激活效应器（如腺苷酸环化酶、磷脂酶C），产生第二信使。④α亚基具GTPase活性，将GTP水解为GDP（可被RGS蛋白加速），α-GDP与βγ重新结合，G蛋白失活，信号终止。⑤因此G蛋白通过GTP/GDP循环在活化与失活间切换，起分子开关作用；其持续活化（如霍乱毒素修饰）可导致疾病。","kps":"失活:Gα-GDP+βγ;受体(GEF)促GDP→GTP;α-GTP激活效应器;GTPase水解→失活;分子开关;持续活化致病(霍乱毒素)","type":"机制型"},{"id":"ch10_calc_y3","modI":4,"q":"设计实验验证某种激素通过cAMP-PKA通路调节靶细胞代谢。","a":"思路：检测激素处理后cAMP水平、PKA活性及下游代谢变化。①用该激素处理靶细胞，在不同时间点检测细胞内cAMP含量（放射免疫法或ELISA）。②检测PKA活性及其底物蛋白的磷酸化水平（免疫印迹）。③检测下游代谢指标（如糖原磷酸化酶活化、糖原分解）。④对照与阻断：用腺苷酸环化酶抑制剂或PKA抑制剂预处理，观察效应是否被阻断；设未加激素对照。预期：激素处理后cAMP升高、PKA活化、下游代谢改变，且可被AC/PKA抑制剂阻断，证明其经cAMP-PKA通路起作用。","kps":"激素处理测cAMP;测PKA活性/底物磷酸化;测下游代谢;AC/PKA抑制剂阻断;对照;预期被阻断","type":"实验设计型"}],"appcards":[{"front":"简述细胞通讯的方式。","back":"（1）细胞通过分泌化学信号进行的通讯，包括内分泌、旁分泌、自分泌和化学突触等。 （2）细胞间接触性依赖的通讯：细胞间直接接触，信号分子与受体都是细胞的跨膜蛋白。 （3）间隙连接：使细胞质相互沟通，实现代谢偶联或电偶联。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"什么是 Ras 蛋白，有何功能？Ras 突变会引起什么样的结果？","back":"（1）Ras 蛋白是 Ras 基因编码产物，是一种小的 GTP 结合蛋白，具有 GTP 酶活性，位 于胞质侧，结合 GTP 时为活化态，结合 GDP 时失活，Ras 蛋白具有分子开关作用，激活磷 酸化级联反应。GAP 可增强 Ras 的 GTP 酶活性。Ras 释放 GDP 结合 GTP，需要鸟苷酸交换 因子参与。 （2）发生突变的 Ras 蛋白能够与 GTP 结合，但不能将其水解成 GDP，从而使自身锁定于 活化状态，导致恶性细胞转化和肿瘤的发生。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"蛋白质获取磷酸基团在细胞信号系统传导中的作用如何？","back":"（1）细胞内的信号蛋白主要分为两大类：一类在蛋白激酶的作用下磷酸化，共价结合 ATP 所提供的磷酸基团；另一类则在信号作用下结合 GTP，通常以 GTP 取代 GDP。 （2）这两种胞内信号蛋白的共同特征是，在信号达到时通过获得一个或几个磷酸集团而被 激活，而在信号减弱时能去除这些集团，从而失去活性。在信号中继网中，某个信号蛋白磷 酸化通常造成下游的蛋白依次发生磷酸化，形成磷酸化级联反应。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"由哪些蛋白调控单体 G 蛋白的活性？","back":"鸟苷酸释放蛋白 Sos 通过促进释放 GDP 使 Ras 结合 GTP 而被激活；GTP 酶活化蛋白 GAP 通过促进 GTP 的水解而使 Ras 失活；GDI 通过抑制 GDP 的释放使 Ras 失活。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"霍乱毒素通过什么机制引起腹泻的？","back":"霍乱毒素是一种作用于 G 蛋白的毒素，它可将 NAD+上的 ADP-核糖基团共价结合到 Gs 的α亚基上，使蛋白核糖化，这样抑制了α亚基的 GTP 酶活性，从而抑制了 GTP 的水解， 使 Gs 一直处于激活状态。结果使腺苷酸环化酶处于永久活性状态，cAMP 的形成无法终止， 引起 Na+与水分子不断分泌到肠腔，而导致严重腹泻。","mod":4,"modName":"二、受体(receptor)","points":""},{"front":"简述日咳产生的细胞学原因。","back":"百日咳毒素催化 Gi 的α亚基 ADP－核糖基化，降低了 GTP 与 Gi 的α亚基的结合水平， 使 Gi 的α亚基不能活化，从而阻断了 Ri 受体对腺苷酸环化酶的抑制作用。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"简述 NO 的作用机制。","back":"NO 是一种自由基性质的气体，具脂溶性，可快速扩散通过细胞膜，到达邻近靶细胞发 挥作用。 血管内皮细胞和神经细胞是 NO 的生成细胞。以 L-精氨酸为底物，在一氧化氮合酶(NOS) 的作用下，以还原型辅酶Ⅱ(NADPH)为电子供体，等量生成 NO 和 L-瓜氨酸。 可溶性鸟苷酸环化酶(GC)的激活是 NO 发挥作用的主要机制。NO 扩散进入靶细胞与靶蛋白 结合，与鸟苷酸环化酶活性中心的铁离子结合，改变酶的构象，导致酶活性增强和 cGMP 合成增多，cGMP 作为新的信使分子介导蛋白质的磷酸化等过程，发挥多种生物学作用。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"类固醇激素受体和离子通道偶联受体所应用的信号机制都很简单，并且信号成分也十分 少。它们能导致起始信号的放大吗？如果是，如何放大起始信号？","back":"就类固醇激素受体来说，类固醇和受体形成一对一的复合物结合到 DNA 上从而激活转 录，因此在配体结合和转录激活之间没有放大作用。放大在随后发生，靶基因转录会产生许 多 mRNA 分子，而每一个 mRNA 分子又翻译产生许多蛋白质分子。 对于离子通道偶联受体，一个离子通道在开放时可通过成千上万个离子，这就是此类信号系 统的放大步骤。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"比较植物中的信号传导途径和动物中的信号传导途径。","back":"这两类物种基本上采用十分近似的信号转导途径，除了少数的例外。两者都有胞内 Ca2+、 IP3 和 DAG 的变化，但动物独有环化核苷酸作为第二信使，植物独有水杨酸作为第二信使， 组氨酸激酶也是植物所特有的。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"列表比较 PKA 与 PKC 信号转导系统。","back":"PKA 与 PKC 信号转导系统比较如表 9-1 所示： 表 9-1 PKA 与 PKC 信号转导系统的区别 比较项 PKA 信号系统        PKC 信号系统 目 受体  G 蛋白偶联受体          G 蛋白偶联受体 第二信 cAMP              IP3 和 DAG 使 G 蛋白活化，进而活 化磷脂酶 C（PLC）， G 蛋白活化，进而活化腺 第二信                 活化的 PLC 催化 PIP2 苷酸环化酶（AC），活化 使的产                 生成两个第二信使， 的 AC 催化细胞内的 ATP 生                   即 DAG 和 IP3，接着 生成 cAMP IP3 动员胞内钙库 ——内质网释放 Ca2 ＋ 到胞质内，与 CaM 结 合引起系列反应，而 DAG 在 Ca2 协同下激 ＋   活 PKC，再引起相应 的级联反应。这是一 个“双信使系统” 活化的 PKC 可使底物 蛋白磷酸化，激活下 cAMP 与无活性的 PKA 结 游基因调控蛋白。 效应  合释放催化亚基，可以磷 PKC 还可活化 Na ∕H ＋  ＋  酸化下游基因调控蛋白 交换引起细胞内 pH 升高 IP3-DAG 途径通过 IP3 cAMP 途径由环腺苷磷酸 信号的                  的一系列去磷酸化 二酯酶降解 cAMP 为 5＇ 终止                   形成自由的肌醇和 -AMP 而终止 DAG 的水解而终止","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"举例说明 G 蛋白偶联细胞表面受体介导信号跨膜转导的通路及其作用机制。 相关试题：G-蛋白偶联系统信号转导的主要特点是什么？","back":"G 蛋白偶联细胞表面受体介导信号跨膜转导的通路主要有两条：cAMP 信号通路和磷脂 酰肌醇信号通路。同时，在磷脂酰肌醇信号通路中，存在一个“双信使系统”，因而 G 蛋白 偶联受体信号转导形成一个复杂的网络结构。 （1）cAMP 信号通路 ①信号通路：激素→G 蛋白偶联受体→G 蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白。 ②作用机制：cAMP 活化 PKA，PKA 催化亚基转位进入细胞核，使基因调控蛋白（cAMP 应答元件结合蛋白，CREB）磷酸化，磷酸化的基因调控蛋白 CREB 与核内 CREB 结合蛋白 （CBP）特异结合形成复合物，复合物与靶基因调控序列结合，激活靶基因的表达。 （2）磷脂酰肌醇信号通路“双信使系统” 胞外信号分子与 GPCR 结合，活化 G 蛋白，进而激活磷脂酶 C（PLC），催化 PIP2 水解生 成 IP3 和 DAG 两个第二信使。 ①IP3-Ca2 信号通路 ＋   a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→IP3→胞内 Ca2 浓度升高→Ca2 结合蛋白（CaM）→钙调蛋白依赖激酶→基因调控蛋白。 ＋             ＋   b．作用机制：IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，引起 Ca2 释放并进入细胞质 ＋         ＋   基质，通过结合钙调蛋白引起细胞反应，如引起肌细胞的收缩。 ②DAG-PKC 信号通路 a．信号通路：胞外信号分子→G 蛋白偶联受体→G 蛋白→磷脂酶 C（PLC）→DAG→激活 PKC→蛋白磷酸化或者促 Na ／H 交换使胞内 pH 变化等。 ＋   ＋   b．作用机制：IP3-Ca2 信号通路释放的 Ca2 将细胞质中游离的蛋白激酶 C（PKC）募集到细 ＋           ＋   胞质膜上，结合在质膜上的第二信使 DAG 活化并激活与质膜结合的 PKC，接着 PKC 作用 于下游底物，引起多种细胞反应，如细胞分泌、肌肉收缩、细胞增殖分化等。","mod":1,"modName":"一、信号分子","points":""},{"front":"细胞信号转导的复杂性主要表现在哪几个方面？","back":"细胞信号转导的复杂性主要表现在以下方面： （1）多途径多层次的细胞信号传递通路具有收敛性和发散性的特点。每种受体都能识别与 结合各自的特异性配体，来自各种非相关受体的信号，可以在细胞内收敛激活一个共同的效 应器（如 Ras 或 Raf 蛋白）的信号。另外，来自相同配体的信号（如表皮生长因子或胰岛素）， 又可发散激活各种不同的效应器，导致多样化的细胞应答。 （2）细胞信号转导既具有专一性，又具有作用的相似性。配体与受体在结构上的互补是细 胞信号转导具有专一性的重要基础；同时细胞信号转导又有相似的作用机制，因此细胞面临 各种纷杂的胞外信号时，只通过少数几种第二信使便可介导多种多样的细胞应答反应。如不 同细胞因子与受体组成的复合体中往往含有相同亚基，由此诱导相似的信号转导；一种配体 与受体结合可诱发多种信号转导途径，如在配体作用下，RTK 不同位点的 Tyr 残基自磷酸 化，可分别结合不同信号蛋白或接头蛋白，引出不同的信号通路；G 蛋白与受体偶联可介导 腺苷酸环化酶和 PLC 等，分别引出 cAMP 和 IP3-DAG 两种信号通路。 （3）信号转导过程有放大作用，但这种放大作用又必须受到适度调控，这表现为信号放大 作用和信号终止作用的并存。正常生理条件下，激素配体本身对受体数目的影响，信号分子 的磷酸化与去磷酸化，G 蛋白的 GTP 或 GDP 结合状态可逆变化，Ca2 的释放与回收等，都 ＋   可使信号转导精确而适度，不是持续的而是对胞外信号瞬间的反应，一旦破坏了这种正常的 正负反馈机制，细胞就会病变。 （4）当细胞长期暴露于某种形式的刺激下时，细胞对刺激的反应会降低，即细胞适应现象。 细胞适应的方式有：逐渐降低表面受体数目；快速钝化受体，降低受体配体的亲和力；在受 体已经被激活的情况下，其下游信号蛋白发生变化，使信号通路受阻。这种适应性是通过负 反馈条件实现的。 （5）细胞信号转导的复杂性还表现在它的非线性方面。细胞无时无刻不在复杂环境的信号 轰炸之下，这些信号分别协调启动细胞各种信号途径，最后做出合理的应答反应。因此，细 胞各种不同信号通路不是彼此孤立的，其最重要的特征就是形成一个复杂的信号网络系统， 它具有高度的非线性特点，被称为交叉对话。这种机制使信号经网络系统分析、整合后最终 表现为特定的生理功能，从而使细胞具有一定自我修复机制和补偿能力。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"试述参与细胞信号转导的细胞膜受体的种类与特点。","back":"参与细胞信号转导的细胞膜受体的种类与特点如下： （1）酶联受体 受体结构域具有潜在酶活性或者受体本身不具有酶活性但其胞内段与酶联系，在受到刺激时 能激活下游靶酶。如生长因子类受体，这类受体存在于细胞膜上，受体本身具有酪氨酸激酶 的活性，能直接催化底物的磷酸化。 （2）离子通道受体 某些神经递质的受体，它们也存在于细胞膜上，其本身是一种或几种离子的离子通道，配体 与这类受体结合后，改变了受体的空间构象，使离子通道开放或关闭，控制着离子进出细胞。 （3）G 蛋白偶联的受体 普遍存在于各类真核细胞表面，通过与细胞内 G 蛋白偶联，受到刺激时改变 G 蛋白的构象， 从而激活下游靶蛋白活性，引起应答。如神经递质、激素、肽类和胺类配体等的受体。","mod":0,"modName":"绪论 · 概览","points":""},{"front":"概述细胞表面受体的分类（配体、受体、信号转导机制）。","back":"受体是指一类能够识别和选择性结合某种配体（信号分子）的大分子，主要是糖蛋白和 糖脂。细胞表面受体主要识别和结合亲水性信号分子，包括分泌型信号分子（如神经递质、 多肽类激素、生长因子等）或膜结合型信号分子（细胞表面抗原、细胞表面黏着分子等）。 根据信号转导机制和受体蛋白类型的不同，细胞表面受体分为： （1）离子通道偶联受体，受体本身既有信号（配体）结合位点，又是离子通道。 （2）G 蛋白偶联受体（GPCR），是细胞表面受体中最大家族。 （3）酶联受体，其中一种受体胞内结构域具有潜在酶活性，另一类是受体本身不具酶活性， 而是受体胞内段与酶相联系。","mod":4,"modName":"二、受体(receptor)","points":""},{"front":"试述细胞接受化学信号后调节基因表达的途径？","back":"（1）细胞内受体的本质是激素激活的基因调控蛋白，当细胞内受体接受甾类激素后， 会引起受体构象变化，使得结合在受体上的抑制蛋白复合物解离，暴露出受体与 DNA 结合 的位点，受体被激活，激活的受体通过结合于特异 DNA 序列将调节基因的表达。（20 由细 胞外受体接受水溶性的激素信号，通过信号转导在细胞内会产生第二信号分子 IP3／DG 和 第三信使 Ca 离子。蛋白激酶 C(PKC)在 DG 和 Ca2+浓度的升高条件下，激活细胞内的靶酶 蛋白激酶 C，PKC 激活时成为膜结合的酶，属于多功能丝氨酸、苏氨酸激酶，可作用于胞 质中的某些酶，参与生化反应的调节；也可作用于细胞核的转录因子，参与基因表达的调控。","mod":6,"modName":"四、细胞膜表面的受体(信号分子为亲水蛋白质、","points":""},{"front":"从受体的角度解读家族性高胆固醇血症的发病机理。","back":"在肝细胞及肝外组织的细胞膜表面广泛存在着低密度脂蛋白(LDL)受体，它能与血浆中 富含胆固醇的 LDL 颗粒相结合，并经受体介导的内吞作用进入细胞。在细胞内受体与 LDL 解离，再回到细胞膜，而 LDL 则在溶酶体内降解并释放出胆固醇，供给细胞代谢需要并降 低血浆胆固醇含量。如果由于各种原因(如受体合成受损；受体发生细胞内转运障碍；受体 与配体结合力降低；受体内吞缺陷；受体再循环障碍)导致受体数量减少或功能异常，其对 血浆 LDL 的清除能力降低，患者出生后血浆 LDL 含量即高于正常，发生动脉粥样硬化的危 险也显著升高。","mod":7,"modName":"4.1 G protein-Cou","points":""},{"front":"何谓信号转导中的分子开关机制？举例说明。","back":"（1）分子开关机制 在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调 控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分 子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。 另一类是 GTPase 开关蛋白，结合 GTP 活化，结合 GDP 失活。 （2）分子开关机制举例 Ras 蛋白是一个典型的分子开关蛋白，通过其他蛋白质的作用使得 GTP 与其结合而处于激 活状态。一种 GTPase 激活蛋白可促进 Ras 蛋白将结合的 GTP 水解为 GDP，Ras 的工作类 似电路开关。如果 Ras 分子开关失去控制，一直处于激活状态，下游 MAPK 一直处于活跃 状态，使细胞有丝分裂失去控制，从而导致癌变。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"试比较 G 蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","back":"G 蛋白偶联受体是含有 7 个疏水肽段形成的跨膜α螺旋区，其 N 端在细胞外侧，C 端在 细胞胞质侧的受体。G 蛋白偶联受体介导的信号通路：配体-受体结合后，通过与 G 蛋白的 偶联，在细胞内产生第二信使，从而将胞外信号传递到细胞内，影响细胞的行为。G 蛋白偶 联受体介导的信号通路主要包括 cAMP 信号通路和磷脂酰肌醇信号通路。 （1）cAMP 信号通路：细胞外信号（激素，第一信使）与相应 G 蛋白偶联的受体结合，导 致细胞内 cAMP（第二信使）的水平变化而引起细胞反应的信号通路。腺苷酸环化酶（效应 酶）调节胞内 cAMP 的水平，cAMP 被环腺苷酸磷酸二酯酶降解清除。 其反应链为：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP 依赖的蛋白 激酶 A→基因调控蛋白→基因转录。 生物学功能：①调节肝细胞和肌细胞的糖原代谢；②调控真核细胞的基因表达。 （2）磷脂酰肌醇信号通路：通过 G 蛋白偶联受体介导的磷脂酰肌醇信号通路的信号转导， 通过磷酸酯酶 C（效应酶）完成，是双信使系统反应链。此通路的特点是胞外信号被膜受体 接受后，同时产生两个第二信使：IP3 和 DAG，分别激活 IP3-Ca2 和 DAG-PKC 途径，实现 ＋   细胞对外界信号的应答。 生物学功能：①IP3-Ca2 通路中 IP3 结合并开启内质网膜上 IP3 敏感的 Ca2 通道，Ca2 释放进 ＋                             ＋      ＋   入细胞质基质，通过结合钙调蛋白引起细胞反应。 ②DAG-PKC 通路中 DAG 活化并激活与质膜结合的 PKC，PKC 作用于下游底物，参与众多 生理过程，例如细胞分泌、肌肉收缩、细胞增殖、分化等。","mod":8,"modName":"4.1.1 G蛋白与跨膜信号转导","points":""},{"front":"图解细胞表面受体调节基因表达的信号通路。","back":"相关图解参见 9.1 复习笔记中图 9-1-2 至图 9-1-9。 （1）G 蛋白偶联受体介导的信号通路 ①激活离子通道的 G 蛋白偶联受体介导的信号通路 a．心肌细胞上 M 乙酰胆碱受体激活的 G 蛋白开启 K 通道。 ＋   b．Gt 蛋白偶联的光受体的活化诱发 cGMP 门控阳离子通道的关闭。 ②激活或抑制腺苷酸环化酶的 G 蛋白偶联受体 ③激活磷脂酶 C，以 IP3 和 DAG 作为双信使的 G 蛋白偶联受体介导的信号通路 （2）酶联受体介导的信号转导 ①受体酪氨酸激酶及 RTK-Ras 蛋白信号通路 ②PI3K-PKB（Akt）信号通路 ③TGF-β受体及其 TGF-β-Smad 信号通路 ④细胞生长因子受体与 JAK-STAT 信号通路 （3）其他细胞表面受体介导的信号通路 ①Wnt 受体和 Hedgehog 受体介导的信号通路 ②NF-κB 和 Notch 信号通路","mod":4,"modName":"二、受体(receptor)","points":""}],"jyq":[{"id":"jyq_ch10_1","kind":"fill","q":"酶关联受体都是跨膜蛋白质，其在细胞外表面具有而在细胞质溶质或本身内有。","a":"配体结合区；酶活性。","src":"山东大学，2006年","kp":null,"e":"酶关联受体的胞外部分识别并结合配体，胞内部分或受体本身具有酶活性，故两空依次为配体结合区、酶活性。","oe":["细胞外表面是受体识别并结合信号分子的部位，即配体结合区。","受体胞内区或受体本身具有催化结构域，配体结合后激活其酶活性。"]},{"id":"jyq_ch10_2","kind":"short","q":"离子通道可分为三种不同形式。","a":"电压门通道；配体门通道；应力激活通道。","src":"湖北大学，2007年","kp":null},{"id":"jyq_ch10_3","kind":"short","q":"试述结合高尔基体的结构特征及生理功能。","a":"遍存在于真核细胞中的一种细胞器。电子显微镜所观察到的高尔基体最富有特征性的结构是由一些（通常是4～8个）排列较为整齐的扁平膜囊堆叠在一起，构成了高尔基体的主体结构。扁囊多呈弓形，也有的呈半球形或球形。均由光滑的膜围绕而成，膜表面无核糖体颗粒附着。高尔基复合体由平行排列的扁平膜囊、大囊泡和小囊泡等三种膜状结构所组成。它有两个面：形成面和成熟面，来自内质网的蛋白质和脂从形成面逐渐向成熟面转运。高尔基体的顺面是囊泡结构，靠近糙面内质网，中间部分是扁平膜囊，反面也是囊泡结构。扁平膜囊是高尔基复合体的主体部分。一般由3～10层扁平膜囊平行排列在一起组成一个扁平膜囊堆，每层膜囊之间的距离为15～30nm，每个扁平囊是由两个平行的单位膜构成，膜厚6～7nm。小泡在扁平囊的周围有许多小囊泡，直径40～80nm。这些小囊泡较多地集中在高尔基复合体的形成面。一般认为它是由附近的糙面内质网出芽形成的运输泡。它们不断地与高尔基体的扁平膜囊融合，使扁平膜囊的膜成分不断得到补充。液泡多见于扁平膜囊扩大之末端，可与之相连。直径0.1～0.5um，泡膜厚约8nm。高尔基体的功能：参与细胞的分泌活动，将内质网合成的多种蛋白质进行加工、分类与包装，并分门别类地运送到细胞的特定部位或分泌到细胞外。内质网上合成的脂类一部分也要通过高尔基体向细胞质膜等部位运输。因此，高尔基体是细胞内物质运输的交通枢纽。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_4","kind":"mcq","q":"下列哪些物质可能是配体（ligand）（）。","o":["A. 激素","B. 神经递质","C. 药物","D. 抗原"],"a":"A","src":"华中农业大学，2009年","kp":null,"e":"配体是能与受体特异性结合的信号分子，激素是细胞信号转导中最典型的配体。","oe":["A. 激素：正确，激素是经典的细胞外信号配体，与靶细胞受体特异结合。","B. 神经递质：错误，本题以激素为标准配体，神经递质通常归为神经信号分子。","C. 药物：错误，药物为外源化学物，不属于生理性信号配体。","D. 抗原：错误，抗原与抗体特异结合，不属于信号转导配体。"]},{"id":"jyq_ch10_5","kind":"mcq","q":"可进行自身磷酸化的受体是（）。","o":["A. 磷脂酰肌醇系统","B. 腺苷酸环化酶系统","C. 鸟苷酸环化酶系统","D. 酪氨酸蛋白激酶系统"],"a":"D","src":"南开大学，2009年","kp":null,"e":"酪氨酸蛋白激酶型受体具有酪氨酸激酶活性，可发生自身磷酸化。","oe":["A. 磷脂酰肌醇系统：错误，该系统受体本身不催化自身磷酸化。","B. 腺苷酸环化酶系统：错误，其受体通过G蛋白激活腺苷酸环化酶。","C. 鸟苷酸环化酶系统：错误，其受体具鸟苷酸环化酶活性，而非自身磷酸化。","D. 酪氨酸蛋白激酶系统：正确，该受体可发生自身磷酸化。"]},{"id":"jyq_ch10_6","kind":"short","q":"第二信使（secondarymessenger）","a":"作用是将水溶性信号分子转换为胞内信号，如cAMP、cGMP、三磷酸肌醇（IP）和二酰基甘油（DG）。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_7","kind":"short","q":"膜受体（membranereceptor）","a":"膜受体是指细胞膜上分布的能识别化学信号（配基）的镶嵌蛋白质。合，最终使细胞内产生相应的化学反应或生物学效应。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_8","kind":"short","q":"离子通道（ionchannel）","a":"生物膜对无机离子的跨膜运输有被动运输（顺离子浓度梯度）和主动运输（逆离子浓度梯度）两种方式。被动运输的通路称离子通道。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_9","kind":"short","q":"配体（ligand）能与细胞膜受体结合的化学信号分子称为配体。包括激素、细胞因子、神经递质、药物及抗原等，它们分别与膜受体特异结合后将导致细胞内发生相应的生物学效应。","a":"","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_10","kind":"short","q":"刺激型受体（stimulateReceptor，Rs）","a":"cAMP信号通路上的刺激型信号受体（Rs）通过Gs来刺激腺苷酸环化酶的活性。肾上腺素（B型）受体，胰高血糖素受体，促甲状腺素受体，后叶加压素受体，促黄体生长素受体，促卵泡激素受体等。作用于激活型受体的信号分子有肾上腺素、胰高血糖素，以及ACTH。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_11","kind":"short","q":"激活型的G-蛋白（stimulateG蛋白）","a":"此系统中的G蛋白接受了受体的信号后，α亚基被激活，并将信号传递给腺苷酸环化酶，使该酶激活，提高细胞质中cAMP的浓度。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch10_12","kind":"judge","q":"亲脂性信号分子通过与细胞表面受体结合传递信号。","a":"错","src":"华中师范大学，2008年","kp":null,"oe":["若选对，是忽略了亲脂性分子可穿过质膜；它们多与胞内或核内受体结合。","亲脂性信号分子能透过细胞膜，与胞内（核）受体结合，而非细胞表面受体，说法错误。"]},{"id":"jyq_ch10_13","kind":"short","q":"细胞信号传递的基本特征包括。","a":"收敛或发散；信号放大作用；专一性和相似性；适应性。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch10_14","kind":"short","q":"目前认为第二信使主要有等。","a":"cAMP;Ca²+；IP3。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch10_15","kind":"mcq","q":"细胞识别（）。","o":["A. 是细胞通讯的结果","B. 亦称细胞通讯","C. 是细胞通讯的一个重要环节","D. 与细胞通讯无关"],"a":"C","src":"南京师范大学，2009年","kp":null,"e":"细胞识别是细胞通讯过程中的重要环节，通过表面分子相互辨认。","oe":["A. 是细胞通讯的结果：错误，细胞识别是前提和环节，不是结果。","B. 亦称细胞通讯：错误，细胞识别与细胞通讯不是同一概念。","C. 是细胞通讯的一个重要环节：正确，识别是通讯过程的起始步骤。","D. 与细胞通讯无关：错误，细胞识别与细胞通讯密切相关。"]},{"id":"jyq_ch10_16","kind":"short","q":"简述磷脂酰肌醇信号通路的起始、转导、终止的过程。","a":"是G蛋白偶联受体的信号转导通路中的一种途径，在磷脂臻物考通路咨逾外信号4分70与第九章细胞信号转导细胞表面G蛋白耦联型受体结合，激活质膜上的磷脂酶C（PLC-β），使质膜上4，5-二磷酸磷脂酰肌醇（PIP2）水解成1，4，5-三磷酸肌醇（IP）和二酰基甘油（DG）两个第二信使，胞外信号转换为胞内信号。IP3与内质网上的IP，配体门钙通道结合，开启钙通道，使胞内Ca浓度升高。激活各类依赖钙离子的蛋白。DG结合于质膜上，可活化与质膜结合的蛋白激酶C。PKC以非活性形式分布于细胞溶质中，当细胞接受刺激，产生IP，使Ca浓度升高，PKC便转位到质膜内表面，被DG活化，PKC可以使蛋白质的丝氨酸/苏氨酸残基磷酸化是不同的细胞产生不同的反应，如细胞分泌、肌肉收缩、细胞增殖和分化等。IP，信号的终止是通过去磷酸化形成IP2，或被磷酸化形成IP4。Ca²+由质膜上的Ca²+泵和Na*-Ca²+交换器将抽出细胞，或由内质网膜上的钙泵抽进内质网；DG通过两种途径终止其信使作用：一是被DG-激酶磷酸化成为磷脂酸，进人磷脂酰肌醇循环；二是被DG酯酶水解成单酯酰甘油。","src":"华东师大，2009年","kp":null},{"id":"jyq_ch10_17","kind":"short","q":"论述磷脂酰肌醇信号通路。","a":"细胞表面G蛋白耦联型受体结合，激活质膜上的磷脂酶C（PLC-β），使质膜上4，5-二磷酸磷脂酰肌醇（PIP2）水解成1，4，5-三磷酸肌醇（IP）和二酰基甘油（DG）两个第二信使，胞外信号转换为胞内信号，这一信号系统又称为“双信使系统”。IP与内质网上的IP配体门钙通道结合，开启钙通道，使胞内Ca浓度升高。激活各类依赖钙离子的蛋白。DG结合于质膜上，可活化与质膜结合的蛋白激酶C（PKC）。PKC可以使蛋白质的丝氨酸/苏氨酸残基磷酸化是不同的细胞产生不同的反应，如细胞分泌、肌肉收缩、细胞增殖和分化等。IP，信号的终止是通过去磷酸化形成IP2，或被磷酸化形成IP4；DG通过两种途径终止其信使作用：一是被DG-激酶磷酸化成为磷脂酸，进入磷脂酰肌醇循环；二是被DG酯酶水解成单酯酰甘油。","src":"浙江理工大学，2009年","kp":null},{"id":"jyq_ch10_18","kind":"short","q":"试述细胞表面受体介导的信号跨膜传递的种类与分布。","a":"膜表面受体主要有三类：①离子通道型受体；②G蛋白耦联型受体；③酶耦联的受体。离子通道型受体是一类自身为离子通道的受体，即配体门通道。主要存在于神经、肌肉等可兴奋细胞，其信号分子为神经递质。三聚体GTP结合调节蛋白简称G蛋白，位于质膜胞质侧，由αB、三个亚基组成，α和亚基通过共价结合的脂肪酸链尾结合在膜上，G蛋白在信号转导过程中起着分子开关的作用，当α亚基与CDP结合时处于关闭状态，与GTP结合时处于开启状态，α亚基具有CTP酶活性，能催化所结合的ATP水解，恢复无活性的三聚体状态，其GTP酶的活性能被RGS增强。RGS也属于GAP。G蛋白耦联型受体为7次跨膜蛋白，受体胞外结构域识别胞外信号分子并与之结合，胞内结构域与C蛋白耦联。通过与C蛋白耦联，调节相关酶活性，在细胞内产生第二信使，从而将胞外信号跨膜传递到胞内。G蛋白耦联型受体包括多种神经递质、肽类激素和趋化因子的受体，在味觉、视觉和嘎觉中接受外源理化因素的受体亦属G蛋白耦联型受体。由C蛋白耦联受体所介导的细胞信号通路主要包括：cAMP信号通路和磷脂酰肌醇信号通路。cAMP信号途径：在cAMP信号途径中，细胞外信号与相应受体结合，调节腺苷酸环化酶活性，通过第二信使cAMP水平的变化，将细胞外信号转变为细胞内信号。磷脂酰肌醇途径：在磷脂酰肌醇信号通路中胞外信号分子与细胞表面G蛋白耦联型受体结合，激活质膜上的磷脂酶C（PLC-β），使质膜上4，5-二磷酸磷脂酰肌醇（PIP2）水解成1，4,5-三磷酸肌醇（IP）和二酰基甘油（DG）两个第二信使，胞外信号转换为胞内信号，这一信号系统又称为“双信使系统”。酶偶联型受体分为两类，其一是本身具有激酶活性，如肽类生长因子（EGF，PDGF，CSF等）受体；其二是本身没有酶活性，但可以连接非受体酪氨酸激酶，如细胞因子受体超家族。这类受体的共同点是：①通常为单次跨膜蛋白；②接受配体后发生二聚化而激活，起动其下游信号转导。已知六类：①受体酪氨酸激酶；②酪氨酸激酶连接的受体；③受体酪氨酸磷脂酶；④受体丝氨酸/苏氨酸激酶；5受体鸟苷酸环化酶；6组氨酸激酶连接的受体（与细菌的趋化性有关）。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch10_19","kind":"short","q":"何谓信号转导中的分子开关机制？","a":"举例说明。答在细胞内一系列信号传递的级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调控。对每个反应既要求有激活机制还要求有失活机制，负责这种正、负调控的蛋白质称为分子开关。一类是通过蛋白激酶使之磷酸化而激活，通过蛋白磷酸酯酶使之去磷酸化而失活。另一类是GTPase开关蛋白，结合GTP活化，结合GDP失活。Ras蛋白就是一个典型的分子开关蛋白，通过其他蛋白质的作用使得GTP与其结合而处于激活状态。一种GTP酶激活蛋白可促进将结合的GTP水解为GDP，Ras的工作类似电路开关。如果Ras分子开关失去控制一直处于激活状态，下游MAPK一直处于活跃状态，使得细胞有丝分裂失去控制，从而导致癌变。","src":"姜益泉《辅导与习题集》","kp":null}],"outline":["信号分子与受体类型","受体→G蛋白→效应器→第二信使","NO/cGMP","G 蛋白分子开关","信号放大"],"outlineMap":[1,8,5,8,3]};